,(70,3,10,'(န) ဤဘဒ္ဒကမ္ဘာတွင် ဦးစွာပွင့်တော်မူသော ကကုသန်မြတ်စွာဘုရား။', NULL)
,(71,3,1,'ကချင်တိုင်းရင်းသား။ ကချင်လူမျိုး။', NULL)
,(72,3,1,'ကြာပွတ်။ နှင်တံ။', NULL)
,(73,3,16,'(န) မျောက်လေပွေ။ မျောက်မောင်းမ။', NULL)
,(74,3,1,'လက်စွပ်။','‘လစိန်’ နှင့်အတူတူ။')
,(75,3,1,'မက်မန်းသီး။', NULL)
,(76,3,4,'၁။ အဖန်တလဲလဲပြုသည်။ ထပ်ခါထပ်ခါပြုသည်။','ဟီုကဆမ် = ကြိမ်ဖန်များစွာပြောသည်။ ထပ်ခါတလဲလဲပြောသည်။ || “ဒေသမွဲ သ္ဒဟ်ဒေသသတ်ဂမျိ သတ်မၞုံ ကဵုဒြၚ် စှ်ေကၠေံတုဲဂပ်ဂဝ်တွာ်။ ဇကုမဟွံတီ နူဇမ္ၚောဲသၟာန်တဆံအာ ညးဟီုသ္ဂောံတီ တီတုဲဂွံစှ်ေဝေၚ်ရ။” (သၠပတ်ဒ္ၚောဝ်သၜောံ) = “တစ်ခုသောဒေသသည် အဆိပ်ရှိသတ္တဝါ ဦးချိုရှိသတ္တဝါတို့၏ အရပ်ဒေသဖြစ်ပါက ရှောင်ရှား၍သွားသင့်၏။ အကယ်၍မိမိမသိပါက သိရန်အဝေးမှ အထပ်ထပ်မေးလျက်မေးလျက် သွားလော့။ သူတစ်ပါးပြောပြ၍ မိမိသိပြီးလျှင် ရှောင်ရှားနိုင်ပါလိမ့်မည်။”')
,(76,3,4,'၂။ စမ်းတဝါးတဝါးသွားသည်။ သတိနှင့်ဖြည်းဖြည်းးသွားသည်။','ကွာ်ကဆမ်အာ = စမ်းစမ်းပြီးလျှောက်သွားသည်။ စမ်းတဝါးဝါးလျှောက်သွားသည်။')
,(77,3,4,'၁။ ဆွသည်။ ထိုးဆွသည်။','“လ္ပကဆော်သ္ၚိသာဲညိ။” = “ပျားအုံကို မထိုးဆွပါနှင့်။”')
,(77,3,4,'၂။ ကလိထိုးသည်။','ကဆော်ဂၞိၚ် = ခါးကြားကလိထိုးသည်။ || ကဆော်ပါၚ်ကၞက် = ချိုင်းကြားကလိထိုးသည်။')
,(78,3,1,'အဆင့်။','မွဲကဆၚ် = တစ်ဆင့်။')
,(79,3,1,'အမျိုးသမီးကချေသည်။ အငြိမ့်မင်းသမီး။', NULL)
,(80,3,4,'၁။ ဆောင့်သည်။','ကဆံၚ်ဖျေံ = ဆောင့်ချသည်။')
,(80,3,4,'၂။ လျှော်ဖွပ်သည်။','ကဆံၚ်ပလောအ် = အင်းကျီလျှော်ဖွပ်သည်။')
,(80,3,3,'(နဝိ) မာသော။ ကြမ်းသော။','“ကောန်ညးဒိုက်ခၞံၚ် သ္ၚု ကဆံၚ်လ္ပမ္ငိုဟ်။” = “သူဆင်းရဲသား ဆန်ကြမ်းကို မာသည်ဟု မရေရွတ်ပါလေနှင့်။”')
,(81,3,4,'၁။ (အဝတ်အစား) လျှော်ဖွပ်သည်။', NULL)
,(81,3,4,'၂။ ဆောင့်အောင့်သည်။', NULL)
,(82,3,4,'စူဆောင့်သည်။ ဆောင့်အောင့်သည်။ ဆောင့်ကြီးအောင့်ကြီး ပြုမူသည်။', NULL)
,(83,3,4,'ရွေ့သည်။ လျှောဆင်းသည်။','“ကဆေတ်စှ်ေနူတၞံဆု။” = “သစ်ပင်ပေါ်မှ လျှောဆင်းသည်။”')
,(84,3,4,'လျှောသည်။','ကဆေဝ်စှ်ေ = လျှောကျသည်။')
,(85,3,4,'မြင်းပြေးပြေးသည်။ ကဆုန်ပေါက်ပြေးသည်။', NULL)
,(86,3,4,'ရှပ်တိုက်လျှောက်သည်။','ကဆေအ်ဒၞပ် = ဘိနပ်ရှပ်တိုက်ပြီး လမ်းလျှောက်သည်။')
,(87,3,4,'ဖနောင့်ကိုပင့်လျက် ခြေဖျားဖြင့်လည်းကောင်း၊ ခြေဖျားကိုပင့်လျက် ဖနေင့်ဖြင့်ထောက်၍လည်းကောင်း လျှောက်သွားသည်။ (ကွာ်ကဆေအ်ထ ဍိုတ်မ္ဂးဂှ် ပင်လဝ်ဒနေဟ်တုဲ နကဵုတၞုၚ်ဇိုၚ်ကီု၊ ပင်လဝ်တၞုၚ်ဇိုၚ်တုဲ နကဵုဒနေဟ်ကီု ထံက်တုဲမသ္အာရောၚ်။ (တြာဲဝိနယသၚ်ရိုဟ်ဂြဳ။ ဒု—ကၞပ်။ မုက်—၃ဝ။ စန္ဒိမာမဟာထေရ်။)', NULL)
,(88,3,4,'၁။ ကြွသည်။ ကြွမြန်းသည်။','“တ္ၚဲယးတေံ က္ညကၠုၚ်သ္ၚိပိုဲဍိက်တအ်ညိကျာ်။” = “မနက်ဖြန်ခါ တပည့်တော်တို့အိမ်သို့ ကြွတော်မူပါဘုရား။”')
,(88,3,4,'၂။ ပင့်သည်။ ပင့်ဆောင်သည်။ ပင့်ခေါ်သည်။','“ယွံအမာတ်၊ စှ်ေက္ညပတိုန်ဣသိတေံမွဲညိ” သၟိၚ်ဂး။ (ဇ—၁၄၉။ အစွောံ။) = “အမတ်၊ ထိုရသေ့အား ဆင်း၍ပင့်ခေါ်ချေလော့” ဟုမင်းဆို၏။ || “အမာတ်ညာတ်ကျာ်တြဲတုဲ စှ်ေဂိုၚ်ကေတ်ဗဗေၚ်တုဲ က္ညပၠောပ်ဏာကျာ်တြဲပ္ဍဲသ္ၚိရ။” (ဇ—၁၅၄။ အစွောံ။) = “ထိုစစ်သူကြီး သည်ထွက်၍ သပိတ်တော်ကို ယူပြီးလျှင် မြတ်စွာဘုရားကို အိမ်တွင်းသို့ပင့်၍—။” (ညောင် ကန်)')
,(88,3,9,'(ကြိရှေ့ဆက်) တိုက်တွန်းသည့်အနက်၊ မေတ္တာရပ်ခံသည့်အနက်ဖြင့် ကြိယာကိုထောက်ပံ့သည့် စကားလုံး။','“ဒုဟ်အဲနွံဂှ် မိက္ညအေၚ်ဒုၚ်ညိအဴ။” = “ကျွန်တော့်အပြစ်ရှိသည် ကို အမေသည်းခံပါ။” || “ယွံတေမဳဂၠုယာဲဟိုဲ၊ က္ညနာဲဟီုအရေဝ်ကဵုမိညိရလေဝ်ကောန်။” (ဇ—တေ မဳ။ အစွောံ။) = “အို—မယ်မယ့်သားမောၚ်တေမိရဲ့၊ မယ်မယ့်ကို စကားပြောပါတော့လားသားရယ်။”')
,(89,3,4,'အလျင်အမြန်ပြုလုပ်သည်။ အဆောတလျင်ပြုလုပ်သည်။','“မွဲဏှေအ်ညိ ဟွံဂတာပ် ကွဳပၟတ်ရ။ က္ညက်အာရ။” = “တော်ကြာ မီးရထားမမှီဘဲနေမယ်။ မြန်မြန်သွားပါတော့။”')
,(90,3,1,'နွေရာသီ။', NULL)
,(91,3,5,'နွေခေါင်ခေါင်။ နွေလည်ခေါင်။', NULL)
,(92,3,4,'အော်ဟစ်သည်။ ဟစ်ကြွေးသည်။','က္ညာၚ်ကော် = အော်ခေါ်သည်။')
,(93,3,4,'အသံကုန်အော်ဟစ်သည်။', NULL)
,(94,3,4,'အားသွန်ခွန်စိုက်ကြိုးစားသည်။ အပတ်တကုတ်ကြိုးစားသည်။','ကညောန်ကတ်လိက် = စာကို အပတ်တကုတ် လေ့လာသင်ကြားသည်။')
,(95,3,4,'ရုန်းသည်။','ကညဟ်ရုန်၊ ရုန်ကညဟ် = အတင်းရုန်းသည်။ || “လၟဂှ် ဍေံကၠုၚ်ညံၚ် သွိုဟ်ဂတးကီု။ ၜိုၚ်ဗောဓိသတ်ဂှ် ရုန်ကညဟ်သီုဒြဟတ် ဇုက်ဂှ်ဒကုတ် ဒြေပ်စလာ်အာကၠေံရ။” (ဇ—၂ဝ၆။ အစွောံ။) = “မိုဃ်းကြိုးကဲ့သို့သောအဟုန်ဖြင့် လာလတ်သောမုဆိုးကိုမြင်၍ ဘုရားလောင်းသမင်သည် အားကုန်ရုန်းရာ ကျော့ကွင်းကြိုးပြတ်သွားသည်ရှိသော် ခုန်လွှားပြေးသွား ၏။”')
,(96,3,1,'အတွန့်။ အတွန့်အလိပ်။ (ပါဠိ—ဝလိ','ဝလဳ)')
,(97,3,1,'အထွာ။ အထွာဆိုင်။ တစ်ထွာအတိုင်းအတာ။', NULL)
,(97,3,4,'၁။ ထွာသည်။ အထွာဖြင့် တိုင်းတာသည်။', NULL)
,(97,3,4,'၂။ ခြေဖနောင့်ပင့်၍ ခြေဖျားထောက်သည်။', NULL)
,(97,3,1,'အထွာ။ အထွာဆိုင်။ တစ်ထွာအတိုင်းအတာ။','က္ဍကျောဝ် = ခြေဖျားထောက်၍ ချောင်းကြည့်သည်။ က္ဍကေတ် = ခြေဖျားထောက်၍လှမ်းယူသည်။')
,(98,3,4,'(ကျွတ်ကောင်ကဲ့သို့) ထွာ၍ထွာ၍သွားသည်။', NULL)
,(99,3,4,'မာကြောသောအရာဝတ္ထုပေါ်သို့ တစ်စုံတစ်ခုကျသောအခါ မြည်သောအသံ။', NULL)
,(100,3,1,'မာကြောသောအရာဝတ္ထုပေါ်သို့ တစ်စုံတစ်ခုကျသောအခါ မြည်သောအသံ။', NULL)
,(101,3,1,'သံမဏိ။','ပသဲက္ဍာၚ် = သံမဏိ။')
,(102,3,4,'(ကြက်ဥဘဲဥများ သားမပေါက်ပဲ) ပုပ်သွားသည်။','“ခၟာဲစာၚ်က္ဍိုၚ်အာရ။” = “ကြက်ဥ သားမပေါက်ပဲ ပုပ်သွားပြီ။”')
,(102,3,1,'ထီး။','ဒလဝ်က္ဍိုၚ် = ထီးဆောင်းသည်။ ကဍိုၚ်ဇၞောဝ်၊ က္ဍိုၚ်ဇၞောဝ် (န) တံခွန်ကုက္ကား။')
,(103,3,1,'ထီးဖြူတော် (မင်းမြောက်တန်ဆာငါးပါးတွင် ပါဝင်သည်။)', NULL)
,(104,3,16,'‘ခ္ဍတ်တဲ’ ရှု။', NULL)
,(105,3,9,'မြေကွက်ကို ရေတွက်ရာတွင် သုံးသောစကားလုံး။','တိၜါကၞ = လယ်မြေနှစ် ကွက်။ လယ်မြေနှစ်ခင်း။')
,(106,3,1,'၁။ စင်။','ကၞာလဵု = ဗူးစင်။')
,(106,3,1,'၂။ ယာယီတဲ။ မဏ္ဍပ်။ ကနနား။', NULL)
,(107,3,1,'ရေးချအာ။ —ာ။ —ါ။', NULL)
,(108,3,1,'အလှူမဏ္ဍပ်။ တရားမဏ္ဍပ်။', NULL)
,(109,3,4,'တစ်စုံတစ်ဦးသီးသောအခါ “ပျောက်ပါစေ၊ ပျောက်ပါစေ” ဟူသောအနက်ဖြင့် ဟန့်တားရွတ်ဆိုပေးသောစကား။', NULL)
,(110,3,16,'‘ကၞာၚ်’ ရှု။', NULL)
,(111,3,1,'၁။ တံစို့၊ တံကျင်။','ဖျုန်မွဲကဏောတ် = အသားတစ်စို့။ ‘စၞတ်’ နှင့်အတူတူ။')
,(111,3,1,'၂။ ထိပ်။ အထွတ်။', NULL)
,(112,3,5,'နောက်ဆုံး၊ အဆုံးစွန်။', NULL)
,(113,3,4,'‘ကၞပ်’ ရှု။', NULL)
,(114,3,4,'ဆူသည်၊ ဆူပွက်သည်။','ဍာ်ကၞံ = ရေဆူသည်။')
,(115,3,3,'ကျစ်ထားသော။','ဇုက်ကၞေၚ် = ကျစ်ထားသောကြိုး။')
,(115,3,1,'နဖူး။', NULL)
,(116,3,1,'ကွပ်ပျစ်။ အိမ်ကပြင်။', NULL)
,(117,3,1,'၁။ ပိုးခါးပန်းကြိုး။', NULL)
,(117,3,1,'၂။ ကညစ်။', NULL)
,(118,3,1,'မစင်။ ကျင်ကြီး။','လေအ်ကၞေအ် = ကနုတံ၊ မစင်သုတ်သော တုတ်ချောင်း။ နောက်ဖေးကုန်းရန်တုတ်တံ။ || ခဍာ်မွဲဂှ် ဟီုကဵုခဍာ်မွဲဂှ် “ယွံမ၊ အဲပတုံစုတ်က ဏေအ် ပ္ဍဲက္ဍိုပ်ဗမၞးပြောဟိတ်ဂှ်ညိ။” (ဇ—၁၄ဝ။ အစွောံ။) = တခုသောကျီးသည် တခုသော ကျီးကို “အဆွေ၊ ငါသည် ဤပုဏ္ဏား၏အပေါ်­ မစင်ကိုချအံ့” ဟုဆို၏။ (ညောင်ကန်)')
,(118,3,4,'မစင်စွန့်သည်။ ကျင်ကြီးစွန့်သည်။','“ကမၠိုၚ်ဍာ် သၚ်ဂမၠိုၚ်မပပြဘိုက်ဂှ် (ကၠဵုဂှ်) ဍေံကဏေအ် ပတ်သြဴစုတ်တုဲ ဍေံအာကၠေံရ။” (ဇ—၂၇၁။ အစွောံ။) = “ရဟန်းသံဃာများ သုံးဆောင်သော ရေတွင်း­ ထိုခွေးသည် ကျင်ကြီးကျင်ငယ်စွန့်၍ သွား၏။” || “စာၚ်မွဲဒီုလတူဂှ် ကဏေအ်ပ္တုံဒးစာၚ်အသၟဝ်ဂှ်—။” (ဇ—၂၈၄။ အစွောံ။) = “အထက်­အိပ်သောကြက်သည် — ကျင်ကြီးကိုစွန့် ချသည်ရှိသော် အောက်­အိပ်သောကြက်၏ ကိုယ်ပေါ်­ကျ၏။” (ညောင်ကန်)')
,(119,3,1,'ဝဲ။','“ရာဒနာသၟိက်ဂွံတိတ်ဗၠးနူ ဝဲခၞံၚ်သြဃသံသာ”= “သံသရာဝဲသြဃမှ လွတ် မြောက်ရပါစေကြောင်း ဆုတောင်း၏။” || “ယွံဣသိ၊ ဗြဴမ္ဂးဝွံဂှ် ဍေံမဒှ်ကဏှံၚ်ကာမတဏှာရောၚ်၊ ဍေံမၞုံသဘဴမဗ္ဂေတ်ဇြောတ်တလီုဖျေံညး ပ္ဍဲအပါဲရောၚ်။” (၅၅ဝ။ ဇ—၅ဝ၇။ ၈—၉ဝ။ အစွောံ။) = “(ရှင်ရသေ့)၊ မိန်းမတို့မည်သည်ကား ကာမဂုဏ်ဖြင့် လည်စေတတ်သောကြောင့် ဝဲနှင့်တူကုန်၏။” (၅၅ဝ။ စတု—၅၅ဝ။ ညောင်ကန်။)')
,(120,3,10,'(န) သူ့ကျေးဇူးကို သိတတ်ခြင်း။', NULL)
,(121,3,10,'(န) ကျေးဇူးသိတတ်ခြင်း။ ကျေးဇူးသိတတ်သောသူ။','“မပတၠကတ ညူဂုန် လ္ပရိုဟ်စဒဒိုက်တၟာတုဲ မဂွံတီဂုန်ညး ခၠေဝ်ဂုန်ညးညိ။” (ဇ—၄၈။ အစွောံ။) = “ကျေး ဇူးသိတတ်သောသူအဖြစ် ဆင်းရဲဒုက္ခကို မရှုမူဘဲ ကျေးဇူးရှင်အား ကျေးဇူးဆပ်ပါလေ။”')
,(122,3,1,'လတာမြေ။', NULL)
,(123,3,1,'ကတိ။ ခံဝန်ချက်။ ပဋိညာဉ်။', NULL)
,(124,3,10,'(န) ကတိပြုချက်။ ကတိကဝတ်။','သ္ပကတိကဝတ် = ကတိကဝတ်ပြုသည်။')
,(125,3,1,'နှုတ်ဂတိ။ နှုတ်ခံဝန်ချက်။', NULL)
,(126,3,16,'၁။ ပူသည်။—သော။','‘ဍာ်မကတဴလောန်ဗၞတ်။’ (ဇ—၁၅၂။ အစွောံ။) = ‘ပူလွန်းသောရေ။’')
,(126,3,16,'၂။ ပူပန်သည်။—သော။','“အဲပသၟိၚ်ဂှ် သတ္တံကတဴကီု တၜိုဟ်ကီု ဍေံဟီုဇီု အဲဂွံမိၚ်ညိ” သၟိၚ်ချပ်။ (ဇ—၂၈၉။ အစွောံ။) = “ငါမင်းပြုသည်မှာ လူအပေါင်းတို့ ပူပန်ကုန်သလော အေးချမ်းကုန်သလော ၄င်းတို့ပြောဆိုကြသည်ကို ငါကြားလို၏” ဟုမင်းသည်ကြံ၏။ || ‘ဂမ္တဴ’ လည်းရှု။')
,(127,3,4,'၁။ ပူပြင်းသည်။ ပူအိုက်သည်။','“တ္ၚဲဏအ် ကျာလေဝ်ဟွံပိုက် က္တဴက္တာန်ကွေံရ။” = “ဒီနေ့ လေလည်းမတိုက်၊ အလွန်ပူအိုက်တာပဲ။”')
,(127,3,4,'၂။ ဆူပူသည်။','“ဍုၚ်ကွာန်ကတဴကတာန်။”= “မြို့ရွာဆူပူသည်၊ မငြိမ်မသက်ဖြစ်သည်။” || ‘ဂမ္တဴဂမ္တာန်’ (န) လည်းရှု။')
,(128,3,4,'‘ကတဴစိုတ်’ (ကြိ) နှင့်အတူတူ။','“သတ်တံကၠောဝ်ဗျဵု ကတဴကတာန် စိုတ်။” (ဇ—၇၇။ အစွောံ။) = “သတ္တဝါအပေါင်းတို့သည် ငတ်မွတ်ဆာလောၚ်၍ စိတ်ဆင်းရဲပူ ပန်ကုန်၏။”')
,(129,3,4,'နားပူသည်။ နားပူအောင်လုပ်သည်။ နားပူနားဆာလုပ်သည်။', NULL)
,(130,3,4,'စိတ်ဆင်းရဲပူပန်သည်။','“ယွံဥပ္ပး၊ ညးတမၠာတေံဂှ် ဗြဴပအနာစာရဂှ်တီတုဲ ကတဴ စိုတ်ထေဲပၞတ်တုဲ မိၚ်ဒလောံဗ္တောန်တၠပညာတုဲ ဟွံဂွံထေဲပၞတ်တုဲ ပ္တန်ကၠေံစိုတ်တုဲတြဟွံသေၚ်ဟာ” ကျာ်တြဲဂး။ (ဇ—၆၅။ အစွောံ။) = “သီတင်းသည်၊ ရှေးသူတို့သည် မယားဖောက်ပြန်သည်ကို သိ၍ စိတ်ဆင်းရဲပူပန်၍ အမျက်ထွက်သော်လည်း ပညာရှိတို့၏အဆုံးအမကို နာကြားရပြီးသည် ရှိသော် အမျက်မထွက်တော့ဘဲ စိတ်တည်ငြိမ်အောင်ပြုဖူးကုန်ပြီ” ဟုမြတ်စွာဘုရားမိန့်၏။ ‘ဂမ္တဴစိုတ်’ (န) လည်းရှု။')
,(131,3,4,'နှလုံးပူပန်သည်။','“(သၟိၚ်) စံၚ်တူသ္ပာသြိုဟ် ကတဴဖျုန်ဂြိုဟ်တုဲ ဆီဇွောဝ် တိတ်အာနူကအ်တုဲ က္တဵုဒှ်အာယဲရ။” (၅၅ဝ။ ဇ—၄၆၇။ ၇—၁၅၄။ အစွောံ။) = “မင်းသည် နှလုံးမသာသည်ဖြစ်၍ ရင်သည်ခြောက်တပ်၍ နှလုံးပူပန်၍ လည်မှသွေးယိုထွက်၍ အနာဖြစ်၏။”')
,(132,3,4,'မိုးတိမ်အုံ့ဆိုင်း၍ ပူအိုက်သည်။', NULL)
,(133,3,4,'ရင်ပူသည်။', NULL)
,(134,3,4,'ပူအိုက်သည်။ လေးကောင်းလေသန့်မရ ပူအိုက်မွန်းကျပ်သည်။', NULL)
,(135,3,1,'လည်ကုပ်။', NULL)
,(136,3,4,'စေးနှဲသည်။ ကပ်စေးနှဲသည်။','‘ဂမ္တက်’ (နဝိ/ကြိ/န) လည်းရှု။')
,(137,3,16,'ခါးသော။—သည်။','“တၞံဆုသၟတ်ဝွံ ၜိုန်ဍေံသွတ်ဒၟံၚ်ဏီဂှ်လေဝ် မၞုံရှ်ဍေံ ကတၚ်လောန်နူဂျိ—။” (ဇ—၁၄၉။ အစွောံ။) = “ဤသစ်ပင်ငယ်သည် ငယ်နုနေသေးသော်လည်း အဆိပ်ထက်ခါးသော အရသာရှိ၏။”')
,(137,3,16,'ခါးသော။—သည်။','‘ဂမ္တၚ်’ (န/နဝိ) လည်းရှု။')
,(138,3,4,'နားခါးသည်။', NULL)
,(139,3,3,'(အရသာ) အလွန်ခါးသော။ ခါးချစ်သော။','“(တၞးကောန်ဆုသၠီဂှ်) သၟတ် (ကောန်သၟိၚ်)ဂှ် ၜှ်ကေတ်မွဲတၞးတုဲ သ္ၚာဲၚိတ်ဏာရ။ ကတၚ်သအဝ်အာ အလုံကအ်တုဲ ချဟ်ထောံ ကၠေံရ။” (ဇ—၁၄၉။ အစွောံ။) = “မင်းသားငယ်သည် တမာပင်ငယ်မှ အရွက်တစ်ရွက်ကို ခူးယူပြီးလျှင် ဝါးမျိုလိုက်၏။ ခံတွင်းတစ်ခုလုံး ခါးချစ်သွားသဖြင့် ထွေးထုတ်ပစ်လိုက်၏။”')
,(140,3,3,'အလွန်ခါးသော။ ခါးချစ်သော။', NULL)
,(141,3,4,'ဆူပူသည်။ ထကြွဆူပူသည်။','“ပ္ဍဲလက်ထက်သၟိၚ်ဏအ် ဍုၚ်ကွာန် က္တံၚ်က္တဴရ။” = “ဤမင်းလက်ထက်တွင် တိုင်းပြည်ဆူပူသည်။” || ‘ဂမ္တံၚ်ဂမ္တဴ’ (န) လည်းရှု။')
,(142,3,1,'တွင်း။ ချိုင့်။ ကျင်း။','ကတိုၚ်ဂေါ် = မီးသွေးဖုတ်သောမြေတွင်း။ မီးသွေးကျင်း။ || ကတိုၚ်သ္ၚိဝတ် = အိမ်သာတွင်း။ အိမ်သာကျင်း။ || ကတိုၚ်နရက် = ငရဲတွင်း။')
,(143,3,4,'မြှောက်တင်သည်။ အပေါ်သို့ပစ်တင်သည်။ ပစ်လွှင့်သည်။','“ယာဲဂှ် ဗၟက် ကဵုကောန်ၚာ်သၟတ် ကတိုၚ်ဝေၚ်ကောန်ရ။” = “မိခင်သည် ကလေးငယ်ကို မြှောက်တင်၍ က စားကျီစယ်သည်။”')
,(144,3,4,'ပျော်ရွှင်မြူးထူးသည်။ တက်ကြွရွှင်လန်းသည်။','ဝေၚ်ဂြိုၚ်ကတိုၚ် ကမှ် = ကစားမြူးထူးသည်။ (ပါဠိ—ကဳဠတိ) || “သီုကဵုဟွံဗစာရဏာတဴကဵုဓဝ်သၚ်္ခါရ လက္ခဏ ယာန်ပိပြကာတုဲ ပွမကဵုတဴဒါန် မွဲဟာန်ကေုာံပေဲါသဘၚ် ဝေၚ်ဂြိုၚ်ကတိုၚ်ကၟဟ် ဝိဝိၚ်ဟိုတ်မာဲတဴဂှ် ဒှ်ဒါနမၞုံကဵုတွဳဗွိုၚ်ဍေံမောဟ မ္ဂးယၟုရ” (သၚ်္ခါရဘေဒနဳ/ဝိန္ဒသာရ) = “လက္ခဏာသုံးတန်ရှိသော သင်္ခါရတရားကို မဆင်ခြင်မူဘဲ ပွဲလမ်းသဘင်ဖြင့် ကစားရွှင်ပျော်မြူးထူး၍ တွေဝေမေ့လျော့ လျက် အလှူဒါနပြုခြင်းသည် မောဟအခြံအရံရှိသော အလှူဒါနမည်၏။”')
,(145,3,4,'(ကြက်မ) ကတော်သည်။', NULL)
,(146,3,4,'လက်ဝါးပြင်နှစ်ဖက်ဖြင့် လှိမ့်ပွတ်သည်။','လောက်စာလုံး လုံးသည်။ || ကတာတ်ကွာၚ်တောဝ်ကၞး = မုန့်ဗိုင်းတောင့်ဖြစ်အောင် လက်ဝါးပြင်နှစ်ဖက်ဖြင့် လှိမ့်ပွတ်ပြုလုပ်သည်။ || “(ကောန်ဆုသၠီဂှ်) ကောန်သၟိၚ်ဂှ်ပိုက်ကေတ်တုဲ ကတာတ်ဖလှေက်ကၠေံရ။” (ဇ—၁၄၉။ အစွောံ။) = “မင်းသားသည် တမာပင်ငယ်ကို နုတ်ယူပြီးလျှင် လက်ဖဝါးနှစ်ဖက်ဖြင့် ပွတ်ခြေပစ်လိုက်၏။” || “တ္ၚေက်ဝွံ အဲကတာတ်ဖလှေက်ကၠေံ ကဵုဂတာတဲအဲရ” ကလော်မွဲဂး။ = (တယောက်သောရက္ခိုသ်သည်ကား “ထိုကျေးသားကို လက်တို့ဖြင့်နယ်၍ ခြေအံ့” ဟုဆို၏။ (ညောင်ကန်)')
,(148,3,4,'လက်ပူတိုက်သည်။', NULL)
,(149,3,1,'၁။ ကြွက်နို့။','“ပ္ဍဲက္ဍိုပ်အဲ ကတောတ်မွဲမၞုံ သော်ဗ္ဒန်လဝ်—။” (ဇ— ၇၈။ အစွောံ။) မြန်မာ(ညောင်ကန်)မူ­ ‘မှဲ့’ ဟုဆိုထားသည်။)')
,(149,3,1,'၂။ သစ်ပင်ပင်စည်ရှိအဖု။ အဖုအထစ်။', NULL)
,(150,3,1,'ကြက်ငှက်အမြစ်။','သွဂြိုဟ်ကတာန်စာၚ် = ကြက်အသည်းအမြစ်ဟင်း။')
,(150,3,4,'နာကျင်သည်။ နာသောဒုက္ခဝေဒနာဖြစ်သည်။','“ဗောဓိသတ်တုန် အစာသဝ်ဂှ် စုတ်ဂဥုဲတုဲ သရမတ်ဂှ် ဗွဲပြဟ်စိန်အာရ၊ ဟွံဂျိဟွံကတာန်ရ။” (၅၅ဝ။ ဇ—၄၉၉။ ၇—၄ဝဝ။ အစွောံ။) = “ဘုရားလောင်းသည် သမားတော်က ဆေးထည့်ပေးသည်ရှိသော် မျက်စိအနာသည် လျင်စွာကျက်သွား၏၊ နာကျင်သောဒုက္ခဝေဒနာ မရှိသည်ဖြစ်၏။” || ‘ဂျိကတာန်’ လည်းရှု။')
,(151,3,4,'(အမဲရွတ်ကဲ့သို့) ပျဉ်းတွဲသည်။ မာသည်။','“ဖျုန်ဏအ် ကတေန်ကွေံရ။” = “ဤအသားသည် အလွန်ပျဉ်းတွဲသည်။”')
,(151,3,3,'ပျဉ်းတွဲသော။','“ဖျုန်ကတေန်ဂှ် ဍုန်ထောံညိ။” = “ပျဉ်းတွဲသောအသားကို ချက်လိုက်ပါ။”')
,(152,3,1,'နား။ နားရွက်။', NULL)
,(153,3,4,'နားပူသည်။', NULL)
,(154,3,4,'နားပါးသည်။ သဘောပေါက်လွယ်သည်။', NULL)
,(155,3,4,'ပြောရဆိုရ လက်ဝင်သည်။ သဘောမပေါက်ဖြစ်သည်။ နားဝေးသည်။', NULL)
,(156,3,1,'နတ်နား။ နတ်အကြား။', NULL)
,(157,3,1,'နားမျက်စိ။ (ဥပစာ) သတင်းရရှိရာနေရာ။ (မိမိအား) အမြဲသတင်းပေးသူ။','“ဍေံဂှ် ကတောဝ်မတ်အဲရောၚ်။ ဂုန်နူဍေံရ အဲဂွံတီဒၟံၚ်ပရိုၚ်နာနာသာ်ရောၚ်။” = “သူသည် ငါ၏နားမျက်စိဖြစ်သည်။ သူ့ကျေးဇူးကြောင့်သာလျှင် သတင်းမျိုးစုံကို ငါကြားသိနေရသည်။”')
,(158,3,4,'မဟုတ်မမှန်ပြောဆိုသည်ကို အဟုတ်အမှန်ဟု မှတ်ယူသည်။ နားယောင်သည်။', NULL)
,(159,3,4,'နားလေးသည်။ နားထိုင်းသည်။', NULL)
,(160,3,4,'တိုးတိုးပြောသည်ကိုပင် ကြားသည်။ ကြားလွယ်သည်။ နားကောင်းသည်။', NULL)
,(161,3,4,'နားပင်းသည်။', NULL)
,(162,3,4,'နားအေးသည်။ နားအေးပါးအေးရှိသည်။', NULL)
,(164,3,4,'၁။ (အိပ်ရာမှ) ထသည်။','က္တဵုနူသ္တိက် = အိပ်ရာမှထသည်။')
,(164,3,4,'၂။ (အနာရောဂါစ သည်) ပြန်ထသည်။ ပြန်ဆိုးဝါးလာသည်။','ယဲက္တဵု၊ ယဲကလေၚ်က္တဵု = ရောဂါပြန်ထသည်။')
,(164,3,4,'၃။ နိုးထစေသည်။ နိုးထအောင်လုပ်သည်။','“မၚ်ဗၠာဲသဥ္ဇိဝတုန် မန်မက္တဵုဇွဂှ်မကတ် မန်မဆေဝ်ဒဝ်ဇွ ဂှ်ဟွံကတ်။” (ဇ—၁၅ဝ။ အစွောံ။) = “သဥ္ဇိဝလုလင်သည် အလောင်းကိုထစေသော မန္တရားကိုသင်၏။ အလောင်းကိုတားမြစ်သော မန္တရားကိုကားမသင်။”')
,(164,3,4,'၄။ ထသည်။ ထကြွသောင်း ကျန်းသည်။','“ဗ္ဂဲဟွံမွဲမ္ဂး ကၞိက္တဵု။” = “ကြောင်မရှိလျှင် ကြွက်ထသည်။” || ကမၠတ်ဒမၠကတဵု = သူခိုးဓါးပြထကြွသောင်းကျန်းသည်။')
,(164,3,4,'၅။ (ဖုန်စသည်) ထသည်။ အထုအထည်နှင့် ပြန့်လွင့် လွှမ်းမိုးသည်။','ဂဗိုက်က္တဵု၊ လမၠိုက်က္တဵု = ဖုန်ထသည်။ ဖုန်ထူသည်။')
,(165,3,4,'တဟားဟားနှင့် ရယ်ရွှင်ဖွယ်ရာပြောသည်။ ရယ်မောရအောင်ပြုသည်။','“အခိၚ်ညးတၞဟ်တိက် လ္ပက္တဵုဝေၚ်ဂရိုၚ်ညိ။” = “သူများအိပ်ချိန်မှာ တဟားဟားနှင့် ရယ်စ ရာမလုပ်ပါနှင့်။” || “(ရသိပစရဵုသဳလတံဂှ်) — က္တဵုဂရိုၚ်တုဲ ဟီုဝေၚ်ဂြိုၚ်ဂလာန်နာနာသာ်—။” (ဇ—၂၉၉။ အစွောံ။) = “သီလကိုပြက်ရယ်ပြုကုန်သော ရသေ့တို့သည် အမျိုးမျိုးသော ရယ်ရွှင်ဖွယ်စကားကို ပြောဆိုကုန်လျက် ရယ်မောလျက်သာ နေကြကုန်၏။”')
,(166,3,4,'ဒေါသထွက်အောင် ထိုးဆွပြောဆိုသည်။ စိတ်ဆိုးလာအောင်လုပ်သည်။','“ဍေံဂှ် ဒှ်မၞိတ်စိုတ်ဂၠေံမွဲရောၚ်၊ လ္ပက္တဵုစိုတ်ဍေံညိ။” = “သူသည် စိတ်တိုသောလူတစ်ယောက်ဖြစ်သည်။ သူ့စိတ်ကို မဆွပါနှင့်။”')
,(167,3,1,'အဖြစ်အပျက်။ ဖြစ်ကြောင်း။ ဖြစ်စဉ်။','“အတိုၚ်က္တဵုဒဒှ်အိုဿီုဂှ် သေဋ္ဌဳဗြဴ ဟီုတွံကဵုရ။” (ဇ—၁၄။ အစွောံ။) = “သူဌေးမသည် အလုံးစုံသောအဖြစ်အပျက်ကို ပြောပြပေး၏။” || “ကျာ်တွံကဵု က္တဵုဒဒှ်အတိက်တေံရ။” (ဇ—၁၅၅။ အစွောံ။) = “အတိတ်ဖြစ်ကြောင်းကို မြတ်စွာဘုရားဟောတော်မူ၏။” || “ပရိုၚ်က္တဵုဒဒှ်ကၟိန်ဇကု သီုဖအိုတ်ဂှ် (သေဋ္ဌဳ) လ္ၚောဝ်ပ္တီကျာ်တြဲ ရ။” (ဇ—၂၉၁။ အစွောံ။) = “မိမိတူ၏ဖြစ်ကြောင်းအလုံးစုံကို သူဌေးသည် မြတ်စွာဘုရားအား ရှိခိုးလျှောက်ထား၏။”')
,(168,3,4,'ဖြစ်ပေါ်သည်။ ဖြစ်ပွားသည်။ ဖြစ်ထွန်းသည်။','က္တဵုဒှ်ယဲ = ရောဂါဖြစ်ပွားသည်။ || တဵုဒှ်ပၞာန် = စစ်ဖြစ်ပွားသည်။ || ကသဳတိက္တဵုဒှ် = မြေငလျင်ဖြစ်ပေါ်သည်။ ငလျင်လှုပ်သည်။ || က္တဵုဒှ်ဓဝ်စံၚ်တူ = စိတ်နှလုံးပူပန်သည်။ || က္တဵုဒှ်ကရုဏာ = ကရုဏာဖြစ်သည်။ ကရုဏာသက်သည်။ || က္တဵုဒှ်ပ္ဍဲဍုၚ်သွဝ် = နတ်ပြည်­ဖြစ်သည်။ နတ်အဖြစ်ကိုရသည်။ || “ဒကာဗြဴဂှ် ယဲက္တဵုဒှ်တုဲ ပကၠေံကာဂစိုတ်ရ။” (ဇ—၁၄၆။ အစွောံ။) = “ထိုဒကာမသည်လည်း ရောဂါဖြစ်၍သေ၏။” || “ဘိမ္မာထေရဳက္တဵုဒှ်ယဲကျာ—။” (ဇ—၂၉၂။ အစွောံ။)')
,(169,3,4,'အလိုအလျောက်ဖြစ်ပေါ်သည်။ သဘာဝအလျောက်ဖြစ်ပေါ်သည်။','“(ဗောဓိသတ်ဒှ်ချေံဗ္တာၚ်) အာစသြောံသာလဳ မက္တဵုဒှ်ဗတ်ဍေံ ပ္ဍဲလစသိၚ်ဃဵုဂှ်ရ။” (ဇ—၁၉၆။ အစွောံ။) = “ဘုရားလောင်းမြင်းဖြူသည် သိန်းဃိုဠ်အိုင်­ အလိုလိုသာလျှင်ဖြစ်သော သလေးစပါးကို သွား၍စား၏။”')
,(170,3,4,'(လူအဖြစ်)မွေးဖွားလာသည်။ လူဖြစ်လာသည်။','တ္ၚဲက္တဵုဒှ်မၞိဟ် = မွေးနေ့။')
,(171,3,4,'ဖြစ်ပေါ်လာစေသည်။ ဖန်တီးသည်။ ဖန်ဆင်းသည်။','“ညာတ်ဒြပ်ညး လ္ပက္တဵုဗဒှ် လောဘညိ။” = “သူတပါး၏ဥစ္စာကိုမြင်၍ လောဘမဖြစ်ပါစေနှင့်။” || “သၟိၚ်ဣန်က္တဵုဗဒှ်ရုပ်ထဴ ဗျုမွဲတုဲ ပြာပ်ကၠုၚ်ဇရေၚ်ဗောဓိသတ်ရ။” = “သိကြားမင်းသည် လူအိုအသွင်ဖန်ဆင်းပြီး ဘုရားလောင်းအနားသို့ ချဉ်းကပ်လာသည်။”')
,(172,3,4,'သားဖွားသည်။ ကလေးမွေးသည်။','“ပ္ဍဲတ္ၚဲဂှ်ကီု ဍိက်ဗြဴသေဋ္ဌဳဂှ်လေဝ်က္တဵုဗဒှ် ကောန်တြုံမွဲကီု။” (ဇ—၁၂၅။ အစွောံ။) = “ထိုသူဌေး၏ကျွန်မသည်လည်း ထိုနေ့­ပင်လျှင် သားဖွား၏။”')
,(173,3,4,'အရယ်အပြုံးကို ဖြစ်စေသည်။ (ဥမစာ) ဝမ်းသာပျော်ရွှင်စေသည်။ ဝမ်း မြောက်ရွှင်လန်းစေသည်။','“မိဗောဓိသတ် ညာတ်ကောန်ဟွံချိုတ်ဂှ်တုဲ မကလိဂွံပိုန်ဂှ်တုဲ သီုပဳတိ သောမနုဟ် သ္ဍိုက်မၠိုက်ပ္ဍဲကောန် ဗွဲမလောန်ဂှ်တုဲ သီုမုက်မဂေါဝ် က္တဵုဗဒှ်ဂရိုၚ်ဂအီကဵုဗောဓိသတ် ဗွဲမလောန်ရ။” (၅၅ဝ။ ဇ—၃၉၈။ ဒု—၄၅၆/၄၅၇။ အစွောံ။) = “ဘုရားလောင်း၏မိခင်သည် သားမသေဘဲ စည်းစိမ်ဥစ္စာရသည်ကိုမြင်၍ ပီတိသောမနဿဖြင့် သား­အလွန်ချစ်မြတ်နိုး၍ ရွှင်ကြည်သောမျက်နှာဖြင့် သားနှင့်တကွ အရယ်အပြုံးကို ဖြစ်စေ၏။”')
,(174,3,4,'(တစ်စုံတစ်ခုသော အကြောင်းအရာကို) ပြောဆိုဆွေးနွေးသည်။','“ဂမှဳဂမၠိုၚ် ကၠုၚ်ကောံပ္ဍဲဇြပ်ဓဝ်တုဲ က္တဵုဗဒှ်ဂလာန် (စပ်ကဵုသၟိၚ်ပဿိုန်ရ။)” (ဇ—၄၉၅။ အစွောံ။) = “ရ ဟန်းတို့သည် တရားသဘင်­ လာရောက်စုဝေး၍ ကောသလမင်းအကြောင်းကို ပြောဆိုဆွေးနွေး ကြကုန်၏။”')
,(175,3,10,'(န) စာပေပို့ချသူ။ ကထိက။', NULL)
,(176,3,1,'၁။ ပွင့်ချပ်။ ပွင့်ဖတ်။','ကထိုက်ပ္ကဴ = ပန်းပွင့်ချပ်။')
,(176,3,1,'၂။ တန်ဆောင်မုန်းလ။','‘ကထိုန်’ လည်းရှု။ “ပ္ဍဲတိဗ္ၚညးဒြာတ်မ ပ္ဍဲဂိတုကထိုက်ဂှ် ရဴမသြောံဂှ် ဍေံမကၠုတ်တိုန်ကီု—။”(ဇ— ၂၆၁။ အစွောံ။) = “လယ်­ပျိုးအပ်သော တန်ဆောင်မုန်းလ­ ယူ၍ထားအပ်သောမျိုးစေ့သည် ပေါက်သကဲ့သို့—။” (ညောင်ကန်)')
,(177,3,4,'၁။ အလုံးဖြစ်အောင်လုပ်သည်။','ကထေၚ်မဂဝေၚ် = လောက်စာလုံးလုံးသည်။')
,(177,3,4,'၂။ (အဝတ်အင်းကျီ) တွန့်သည်။' ,'“ပလောအ်ကထေၚ်အိုတ်ရ။” = “အင်းကျီတွန့်ကုန်ပြီ။”')
,(178,3,11,'(န) ၁။ ကထိန်။','သ္ၚာကထိုန် = ကထိန်သင်္ကန်း။')
,(178,3,11,'(န) ၂။ တန်ဆောင်မုန်းလ။','တန်ဆောင်မုန်းလကို မွန်ဘာသာတွင် ‘ကထိုက်’ ဟုလည်းခေါ်သည်။')
,(179,3,4,'ထိုင်လျက်ဖင်တွန်းပြီးသွားသည်။ ဖင်တွန်းရွေ့သည်။', NULL)
,(180,3,1,'ဂဒူး။ ပက်ကလာ။', NULL)
,(181,3,1,'ကာ။ ဒိုင်း။ လွှား။', NULL)
,(182,3,1,'ခြေသလုံးကြွက်သား။', NULL)
,(183,3,1,'၁။ ကဒတ်ဥ။','“ကဒါတ်ဗက်ဗျ ကောန်ဗက်မိမ” (မွန်စကားပုံ) = “ကဒတ်ကောင်းမ ကောင်း ကဒတ်မျိုးဥကို လိုက်၍ဖြစ်သည်။ သားသမီးကောင်းမကောင်း မိဘကို လိုက်၍ဖြစ် သည်။” (မြန်မာဝေါဟာရ ‘ကဒတ်’ သည် မွန်ဝေါဟာရ ‘ကဒါတ်’ မှ ဆင်းသက်လာသည်။)')
,(183,3,1,'၂။ အသည်း။ (ခေတ်ဟောင်းသုံး)', NULL)
,(184,3,1,'ကတွတ်သီး။','ယိုဟ်ကဒေါတ် = ကဒွတ်ယို။ (မြန်မာဝေါဟာရ ‘ကတွတ်’ သည် မွန်ဝေါဟာရ ‘ကဒေါတ်’ မှ ဆင်းသက်လာသည်။)')
,(185,3,1,'ကတိုးကောင်။ နံ့သာအိတ်ရှိသော ဒရယ်တစ်မျိုး၊', NULL)
,(186,3,1,'၁။ ကတော့။', NULL)
,(186,3,1,'၂။ (ငှက်ပျောစသည်၏) အဖူး။','ဂဒအ်ဗြာတ် = ၁။ ငှက်ပျောဖူး။ ၂။ ခြေသလုံး။')
,(187,3,4,'လိမ်လည်ထိမ်ဝှက်သည်။ မဟုတ်မမှန်ပြောဆိုသည်။','“ယွံသၟိၚ် ဣန်၊ ဂလာန်ကနိက်မုသာဂှ် မရာတ်ဟီုရောၚ်သွံ။” (၅၅ဝ။ ဇ—၃ဝ၁။ ဒု—၁၂၈။ အစွောံ။) = “သိကြားမင်း၊ လိမ်လည်ထိမ်ဝှက်သော မုသားစကားကို သၚ်မင်းကြီး ပြောဆိုဘိသည်တကား။”')
,(188,3,4,'မုသားဆိုသည်။ မဟုတ်မမှန်ပြောဆို သည်။','“ယွံညးမပြဲ၊ ဂကူပိုဲဝွံဂှ် ဓဝ်ကုသလကမ္မပထစှ်ဂှ် ပ္အာတဴရ။ ဂလာန်ကဏိက်လအိက်ဂှ် ဆအယာံမာတ်ဂရိုၚ်ပွေၚ်ကီုလေဝ် ပိုဲဟွံဂွံဟီု၊ ——။” (၅၅ဝ။ ဇ—၄၄၇။ ၇—၂၁။ အစွောံ။) = “ဆရာ၊ ငါတို့သည် ဒါနသီလအစရှိသော ကုသလကမ္မပထ တရားဆယ်ပါးကို ကျင့်ကုန်၏။ မဟုတ်မမှန်သောစကားကိုလည်း (ရယ်ရွှင်ဖွယ်သဘောမျှလည်း) မဆိုကုန်။ ——။” (၅၅ဝ။ တ— ၆၇ဝ။ ညောင်ကန်။)')
,(189,3,1,'ချင်ရွေးပမာဏ။','ထဝ်မွဲကနန် = ရွှေတစ်ချင်ရွေး။ (ဇ—၄။ အစွောံ။ ညောင်ကန်။)')
,(190,3,4,'ဆောက်လုပ်သည်။ တည်သည်။ ဖန်တီးသည်။','ကနှံပြကိုဟ် = ကျမ်းပြုသည်။ ‘ခၞံ’ ရှု။')
,(190,3,4,'မုန့်တီ။', NULL)
,(191,3,4,'တည်ထောင်သည်။ ဖန်တီးသည်။ တီထွင်သည်။', NULL)
,(192,3,4,'လျှော်ဖွပ်သည်။','ကပိုက်ပလောအ် = အင်္ကျီလျှော်ဖွပ်သည်။')
,(193,3,1,'အကြော်။','ကပံၚ်လဵု = ဗူးသီးကြော်။')
,(194,3,1,'ကင်ပွန်းရွက်၊ ကင်ပွန်းသီး။', NULL)
,(195,3,1,'စားပွဲခုံ။','‘လဗံက်’ ရှု။')
,(196,3,12,'(န) ကဗျာ။', NULL)
,(197,3,1,'မကန်း။ မကရ်း။ (မွန်—က + ပါဠိ—မကရ)', NULL)
,(198,3,1,'၁။ ရေကန်။', NULL)
,(198,3,1,'၂။ ကမာကောင်။ ခရုကမာ။','မြန်မာဝေါဟာရ ‘ကမာ’ သည် မွန်ဝေါဟာရ ‘ကၟာ’ မှ ဆင်းသက်လာသည်။')
,(198,3,1,'၃။ အမြွှာ။','ကောန်ကၟာ = အမြွှာကလေး။')
,(199,3,1,'အမိုး။','ကၟဳစိၚ် = အိမ်ခေါင်အမိုး။')
,(199,3,4,'အမိုးမိုးသည်။','ကၟဳသ္ၚိ = အိမ်မိုးသည်။')
,(200,3,16,'‘ကၟု’ ရှု။', NULL)
,(201,3,1,'၁။ (တိရစ္ဆာန်)အထီး။','ဂၠဴကၟက် = နွားထီး။')
,(201,3,1,'၂။ အဆွဲ။','ကၟက်မန်စှ်သာ် = မွန်စာရှိအဆွဲဆယ်မျိုး။ || နကၟက် = ဆွဲတောင်း။')
,(202,3,1,'လည်ဆွဲ။ ဆွဲကြိုး။', NULL)
,(203,3,1,'ကျောက်ကပ်။', NULL)
,(204,3,4,'(အိပ်နေစဉ်) ယောင်သည်။', NULL)
,(205,3,4,'(အိပ်နေစဉ်) ယောင်ယမ်းသည်။', NULL)
,(206,3,1,'အခေါင်း။','ကမော်ဆု = သစ်ခေါင်း။')
,(207,3,4,'(ရေစသည်) ခပ်သည်။ ငင်သည်။','ကၟံက်ဍာ် = ရေခပ်သည်။ ရေငင်သည်။ || “သြောအ်ဂှ် ကၟံက်စုတ်ပ္ဍဲနညိ။” = “စပါးကို တောင်းထဲသို့ ခပ်ထည့်ပါ။”')
,(208,3,1,'၁။ နံရံ။ တံတိုင်း။','ကၟာၚ်ဍုၚ် = မြို့ရိုး။ || ကမာၚ်ကျာ် = ဘုရားဝင်းတံတိုင်း။')
,(208,3,1,'၂။ အုန်းပင်တက်ရာတွင်သုံးသော ခြေတွင်စွပ်သည့်ဂွင်း။ ဆင်ထူး။', NULL)
,(209,3,1,'အိမ်ကပြင်။','ကမေၚ်ဂတမုက်သ္ၚိ = အိမ်ရှေ့ကပြင်။ || ကမေၚ်ဖဴ = အိမ် နောက်ဖေးကပြင်။')
,(210,3,4,'အမြစ်မှကျွတ်လန်သည်။—စေသည်။','“လဗိုတ်ကျာဇၞော်ဒြဟတ် ပိုက်ကၠုၚ်တုဲ တၞံဆုမတဴပ္ဍဲဝါတဂါ — မွဲတၞံၜါတၞံတံဂှ် ဒေါမ်ကဝ်ကမိုၚ်အာ သီုရိုဟ်သီုတၞံရ။” (ဇ—၇၄။ အစွောံ။) = “လေပြင်းမုန်တိုင်းတိုက်ခတ်လတ်သော် လွင်ပြင်­တည်သော တစ်ပင်နှစ်ပင်တည်းသော သစ်ပင်တို့သည် လဲပြိုကျိုးကျကုန်၍ အပင်ရောအမြစ်ပါ ကျွတ်လန်ကုန်၏။” || “ကျာဒမြာတ် ကၟိုၚ် ဖျေံတၞံဆုမွဲတၞံရ။” = “လေပြင်းသည် သစ်ပင်တစ်ပင်ကို အမြစ်မှ ကျွတ်လန်သွားစေသည်။”')
,(211,3,1,'မြက်။','“ကမတ်တမြံၚ် ဂၠဴညးစဖအိုတ်ကၠေံတုဲ ကမတ်မတိုန်တၟိဂှ် ဂၠဴပိုဲမဂွံစရ။” (၅၅ဝ။ ဇ—၁။ ပ—၂။ အစွောံ။) = “ရှေ့မှသွားသောနွားတို့သည် ဟောင်းကုန်ကြမ်းကုန်သော မြက်တို့ကို စားရကုန်၏။ ငါတို့၏နွားတို့သည် တဘန်ပေါက်ကုန်သော ချိုသောမြက်တို့ကို စား ရကုန်လတ္တံ့။” (၅၅ဝ။ ပ—၁ဝ။ ညောင်ကန်။) || “ပတွဵုနူသၟိၚ် မဂိုၚ်ကေတ်ကၠေံအာဲကၟာဲဂှ်တုဲ (စိၚ်ဗြဴဗျုဂှ်) ကၟတ်သၠဆုတံဂှ် မဒးဂၠာဲစပ္ဍဲဂြိုပ်တုဲ သီုဒဒိုက် မဂွံဂျိုၚ်လမျီုရ။” (၅၅ဝ။ ဇ—၄ဝ၉။ ဒု—၅ဝ၈။ အစွောံ။) = “(မင်းသည် ဆင်အိုမ၏ စည်းစိမ်အခြံအရံကို သိမ်းယူ၏။) ထိုအခါမှစ ၍ ကိုးကွယ်ရာမရှိသည်ဖြစ်၍ တောမြက်သစ်ရွက်တို့ကိုစားလျက် (ဆင်းရဲစွာ) အသက်ကို မွေးရ၏။” (၅၅ဝ။ တ—၃၃၇။ ညောင်ကန်။)')
,(212,3,1,'ယင်ခေါင်းမြက်။', NULL)
,(213,3,1,'မြက်မွှေး။', NULL)
,(214,3,1,'ပြိန်းမြက်။ (ပါဠိ—ပဗ္ဗဇ)', NULL)
,(215,3,1,'ဖြူဆံမြက်။ (ပါဠိ—မုဥ္ဇ)', NULL)
,(216,3,1,'ဆင်ငိုမြက်။', NULL)
,(217,3,1,'မြေဇာမြက်။', NULL)
,(218,3,1,'ဖောင်းခါးမြက်။ (ပါဠိ—ပေါဋကိတိဏ) ကမတ်ဗရံက် (ဇ—၂၁၁။ အစွောံ။)', NULL)
,(219,3,1,'မြားမြက်။ (ပါဠိ—တေဇန','တေဇနဳ) (‘လာဲ’ လေဝ်ဂး။)')
,(220,3,1,'စပါးရိုင်း။ ဂျုံရိုင်း။', NULL)
,(221,3,1,'သက်ကယ်မြက်။ သမန်းမြက်။', NULL)
,(222,3,1,'သက်ကယ်ကြီးမြက်။ ပင်လယ်သက်ကယ်။ (ပါဠိ—ဣက္ခု ဂန္ဓာ)', NULL)
,(223,3,1,'ကျိတ်မှန်ပင်။', NULL)
,(224,3,1,'ပန်းရင်း။ ပန်းရင်းမြက်။ (ဆေးဖက်ဝင်) (ပါဠိ—ဥသဳရ)', NULL)
,(225,3,1,'လင်းတငှက်။','‘တၟာတ်’ ဟုလည်းရေးသည်။')
,(225,3,4,'ပိတ်သည်။','“ကမာတ်ထောံတရၚ်ညိ။” = “တံခါးပိတ်လိုက်ပါ။” || ကမာတ်ကလောန် = အလုပ်ပိတ်သည်။ || ကမာတ်ဖျာ = စျေးပိတ်သည်။ || ကမာတ်ဘာ = ကျောင်းပိတ်သည်။ || ကမာတ်ရုၚ် = ရုံးပိတ်သည်။')
,(226,3,4,'ပါးစပ်ပိတ်သည်။ နှုတ်ပိတ်သည်။ မပြောမဆိုအောင်တားမြစ်သည်။', NULL)
,(227,3,4,'မျက်စိပိတ်သည်။ မျက်မှောင်ချသည်။','“အလဵုအသဳတၠအဝဵုပၞာန် ဗၟာ (နဝတ) ဂှ် ကၟာတ်လဝ်မတ်ညးဍုၚ်ကွာန် ဟွံကဵုတီညာတ်ဒဒှ်မဍာံပြရ။” = “မြန်မာစစ်အာဏာ ရှင်အစိုးရ(နဝတ)သည် ပြည်သူများအား အဖြစ်မှန်ကိုမသိစေရန် မျက်မှောၚ်ချထား၏။”')
,(228,3,4,'အားစိုက်သည်။ အားတင်းသည်။','“ကၟန်လဝ်ညိ။” = “အားတင်းထားပါ။”')
,(228,3,5,'၁။ ခပ်မြန်မြန်။ ခပ်သုတ်သုတ်။ အလျင်စလို။','“ကၟန်ကြဴကြာတ်ထၟာဲပ္ၚာန်တုဲ အာပေဲါရ။” = “အိုးခွက်ပန်းကန်များကို ခပ်သုတ်သုတ်ဆေးကြောပြီး ပွဲသွားကြသည်။” || “ဗောဓိ သတ်ပန်ဏာကံတ္ၚဂှ် သၟိၚ်ထပှ်က္ဍိုၚ်ဗ္တာၚ် ညာတ်လိက်ပ္ဍဲသၠကံဂှ်တုဲ ဖေက်ဘဲဂစိုတ်တုဲ ကၟန်ဒဴစဴအာ ကၠေံအိုတ်ရ။” = “ဘုရားလောင်းသည် လေးမြားပစ်လွှတ်လိုက်ရာ ခုနစ်ပြည်ထောၚ်သောမင်းတို့သည် မြားရွက်ပါစာကိုမြင်၍ သေဘေးမှကြောက်ကုန်၍ အလျင်အမြန်ပြေးလေကုန်၏။”')
,(228,3,5,'၂။ တင်းကျပ်စွာ။ ခိုင်မြဲစွာ။','“ရပ်လဝ်ကဵုကၟန်မံၚ်။” = “မြဲမြဲကိုင်ထားပါ။” || “ဒကိုပ်ပလၚ်ဂှ် ကဝဲကၟာတ်လဝ်ကၟန်အာတုဲ ပံက်ဝါတ်ရ။” = “ထိုပုလင်းအဖုံးကို ရစ်လှည့်၍ ပိတ်ထားသည်မှာ တင်းကျပ်လွန်းသဖြင့် ဖွင့်ရန်ခက်သည်။”')
,(229,3,11,'(န) ‘ကၟိန်—၂’ (န) ရှု။', NULL)
,(230,3,4,'ခြေလက်ဖြင့်ဖက်တွယ်၍ တက်ဆင်းသည်။','“တၞံကြုက်ဇၞော်ဂှ် တၞဟ်န ကၟေန်ဂွါန်တိုန် ဟွံလောဲသွာရ။” = “ထိုသရက်ပင်ကြီးသည် ဖက်တွယ်တက်ရန် မလွယ်ကူပါ။”')
,(231,3,16,'‘ကမန်','“နာ်ဖေက်သပဝ်တုဲ ကမောန်ဒြေပ်ဒဴအာကၠေံရ။” (ဇ—၁၅၄။ အစွောံ။) = “နဂါးသည် ဂဠုန်ကိုမြင်သော် ကြောက်၍ အမြန်ထွက်ပြေးသွား၏။ ”ကၟန်’ (ကြိ/ကြိဝိ) နှင့်အတူတူ။')
,(232,3,1,'တာတမံ။ ဆည်ရိုး။ လယ်ကွက်ပေါင်ရိုး။','ကၟိုန်ပိုတ်၊ ကၟိုန်ပြိုဟ် = တာတမံ ကျိုးပေါက်သည်။ || ကၟိုန်ခံက် = လယ်ကွက်ဆည်ရိုး။ လယ်ကွက်တမံ။ ||ကၟိုန်ဇဵုကၟာ = ကန်ပေါင်ဆည်ရိုး။ || ကၟိုန်ဒဝိုၚ်၊ ကၟိုန်ဗွိုၚ် = ပတ်လည်ကန်ဆည်ရိုး။ ကန်ပေါင်ရိုးတမံ။ || ကၟိုန်သာတ်က = ငါးပက်တမံ။ ငါးပက်ကန်ဆည်။')
,(233,3,4,'(မေး) ငေါသည်။ ငေါထွက်သည်။ (သွားများကျိုးကုန်၍ မေးငေါထွက်သည်ကို ဆိုလိုသည်။)', NULL)
,(234,3,1,'ယက်မထောက်တိုင်။', NULL)
,(235,3,4,'တစ်ရှိန်တည်း အရှိန်ပြင်းသည်။ တစ်ဟုန်တည်း အဟုန်ပြင်းသည်။','ကမိုပ်ကၠုၚ် = တစ်ဟုန်တည်းလာသည်။ ဒေါမောနှင့်လာသည်။')
,(236,3,1,'ကြယ်သီး။','ကမောံပလောအ် = အင်းကျီကြယ်သီး။')
,(237,3,1,'ရေပွက်။', NULL)
,(238,3,4,'မုဆိုးမ', NULL)
,(241,3,4,'ပခုံး­ချိတ်ဆွဲသည်။ လွယ်သည်။','ကၟာဲလဝ်ထိုၚ် = အိတ်ကိုလွယ်ထားသည်။ || ကၟာဲလဝ်ဂၠိက် = ပုဆိုးကွင်းသိုင်း၍ ပခုံး­လွယ်ထားသည်။ (ကလေး)')
,(242,3,1,'ဧည့်သည်။','ကၟုဲပလုၚ် = ရပ်ဝေးမှလာသောဧည့်သည်။')
,(243,3,1,'အရွက်နု။ ပုရစ်။ အညွန့်။','ကၟဝ်မၚ်ဂၠန် = မန်ကျည်းရွက်နု။')
,(243,3,3,'၁။ (သစ်ပင်) ရွက်နုထွက်သည်။ အညွန့်ထွက်သည်။','“တၞံကြုက်ဂှ် ကၟဝ်ဒၟံၚ်ဣရ။” = “ထိုသရက်ပင်သည် ရွက်နုထွက်နေပြီ။” ‘ကမှဝ်’ ရှု။')
,(243,3,3,'၂။ မည်တွန်တောက်တီးသည်။ ဗျစ်တောက်ဗျစ်တောက်ပြောဆိုသည်။', NULL)
,(243,3,3,'၃။ ကမ္ဗလာ။', NULL)
,(244,3,1,'၁။ ချုံ။ အရုံ။ အစု။','ကမဵုတၞံပ္ကဴ = ပန်းပင်ချုံပုတ်။ || ကမဵုဝါၚ်ဗိုၚ် = စပါးလင် ချုံ။ စပါးလင်ရုံ။')
,(244,3,1,'၂။ ကွမ်းဝါးဖတ်။', NULL)
,(244,3,9,'တစ်ချုံ။ တစ်ရုံ။ တစ်စု။','ချောဲဒဇိပ်မွဲကၟဵု = နေစာမြက်စုတစ်စု။ || ဒုန်ၜါကၟဵု = ဝါးနှစ်ရုံ။')
,(245,3,1,'ကျိတ်မှန်ပင်။ ကျိတ်မှန်ရွက်။', NULL)
,(246,3,1,'တံမြက်စည်း။','ကွဟ်ကၟဟ်၊ တွံကၟဟ် = တံမြက်စည်းလှည်းသည်။')
,(247,3,1,'အခေါင်း။ သစ်ခေါင်း။','ခမှော်ဆု၊ ကမှံက်ဆု၊ ကမှော်ဆု = သစ်ခေါင်း။ “(ဗောဓိသတ်ဒေဝတဴ ပရုပ်ဒကုဲမွဲတုဲ) လောပ်အာပ္ဍဲကမှော်ဆု—။” (ဇ—၁၂၁။ အစွောံ။) = “ဘုရားလောင်းနတ်သည် ပုတ်သင်အသွင်ဖန်ဆင်း၍ သစ်ခေါင်းထဲသို့ ဝင်သွား၏။” || “ဆုဝွံ ခိုဟ်ရောၚ်ဂး၊ လၟုဟ်ဝွံ ဒှ်ဒၟံၚ်ကမှံက်ရောၚ်သွံ။” (ဇ—၁၂၁။ အစွောံ။) = “ဤသစ်ကို ကောင်းသည်ဟု ထင်ခဲ့၏။ ယခုမူ အခေါင်းပေါက်နှင့် ဖြစ်နေပါလား။” || “ပ္ဍဲကမှော်ဆုမွဲဂှ် ဇြုံ ဇာတ်မွဲနွံ။” (ဇ—၁၆၅။ အစွောံ။) = “တခုသောသစ်ခေါင်း­ မြွေသည်နေ၏။” (ညောင်ကန်)')
,(248,3,3,'(ထမင်း၊ ဟင်းစသည်) အအေးဖြစ်သော။ အကျန်ဖြစ်သော။','ဍာ်ကမုဟ် = ရေအေး။ || ပုၚ်ကမုဟ် = ထမင်းကျန်။ ထမင်းကြမ်း။ || ‘လမုဟ်’ ဟုလည်း ရေးထုံးရှိသည်။')
,(249,3,4,'လျှံသည်။', NULL)
,(250,3,1,'ပဲခွပ်။ ဓါးမ။ (ပါဠိ—တစ္ဆနဳ)', NULL)
,(250,3,4,'ဆွဲသည်။ ငင်သည်။','“ဍေံကၟေအ် လဝ်ကၞာၚ်ဆုဂှ်ရ။” = “သူသည် ထိုသစ်ကိုင်းကို ဆွဲငင်ထားသည်။”')
,(251,3,1,'ရဟန်း။','‘ဂမှဳ’/‘ခမဳ’ နှင့်အတူတူ။')
,(252,3,1,'အိမ်ကပြင်။ အိမ်ဦးခန်းပြင်။ လေသာဆောင်။', NULL)
,(253,3,1,'အငုံ။ အဖူူး။','ခၟောမ်ပ္ကဴ = ပန်းအဖူးအငုံ။')
,(254,3,1,'ရေပွက်။', NULL)
,(255,3,1,'ဥ။','ကမှာဲစာၚ် = ကြက်ဥ။ || ကမှာဲကြဴ = ပိန်းဥ။')
,(256,3,1,'ကမ္ဗလာ။ သားမွေးစသည်ဖြင့် ရက်သောအထည်။','“ဗောဓိသတ်သ ပေါတ်ကမှဝ်ဂှ်တုဲ ‘ပဏေတ်ကၞိကိတ်နွံညိအဴ’ ဗောဓိသတ်ဂး။” (ဇ—၄၆၃။ အစွောံ။) = “ထို (ဘုရားလောင်း) သုခမိန်သည် ကမ္ဗလာတို့ကိုလည်း လက်ဖြင့်သုံးသပ်၍ ‘ဤကမ္ဗလာဝယ် တစ်ခု သောအရပ်­ ကြွက်ခဲရာသည်ရှိ၏’ ဟုဆို၏။” (ညောင်ကန်)')
,(256,3,1,'ကမ္ဗလာ။ သားမွေးစသည်ဖြင့် ရက်သောအထည်။','‘သၞာပဏ္ဍုကမှဝ်’ လည်းရှု။')
,(257,3,3,'‘ကမိဟ်’ ရှု။', NULL)
,(258,3,4,'ရှုံးစေသည်။','“နာဲဗစာဂှ် သ္ဂုတ်သွာတ်သၞောဝ် ဟွံဒှ်ဗဗွဲဓဝ်၊ အမှုဇၞးဂှ် ကယျ ကၠေံရ။” = “ထိုတရားသူကြီးသည် မတရားသဖြင့် တရားဆုံးဖြတ်၏၊ နိုင်သောအမှုကို ရှုံးစေ ၏။”')
,(258,3,1,'ရှုံးခြင်း။ အရှုံး။','“(ပ္ဍဲသၟိၚ်ၜါမစၞေဟ်တဴဂှ်) ကယျဇနးမ္ဂးဂှ် သ္ဇိုၚ်သတီသန်။” (ဇ— ၃ဝ၁။ အစွောံ။) = “မင်းနှစ်ပါးတို့၏စစ်ထိုးခြင်း­ အရှုံးအနိုင် (ရှုံးခြင်းအောင်ခြင်း) မည်သည်ကို သိနိုင်ခဲလှ၏။” ‘ကျ’ (ကြိ)၊ ‘ကမျ’ (န/နဝိ) တို့လည်းရှု။')
,(259,3,4,'ကွာကျသည်။ ကွာကျစေသည်။','“ဒၞာဲလံက်လဝ်ဍာ်ဂဥုဲဂှ် ကှ်အာတုဲ ဍာ်ဂဥုဲကယျာတိတ်အိုတ်ရ။” = “ဆေးသုတ်ထားသောနေရာတွင် ခြောက်ပြီးဆေးတွေကွာထွက်ကုန်ပြီ။” || “သၟဝ်ဒကဝ်ဂှ် အဲစွံလဝ်သြန်မွဲကၠံ ကယျာရံၚ်ဒကဝ်ညိ။” = “ဖျာအောက်မှာ ငွေတစ်ရာ ငါထားထားတယ်၊ ဖျာကိုခွာကြည့်ပါ။”')
,(260,3,1,'ဝတ္ထုပစ္စည်း။','ကယျာဆု = သစ်ဖြင့်ပြုလုပ်ထားသော ဝတ္ထုပစ္စည်း။ || ကယျာတိ = မြေထည်ပစ္စည်း။ ‘ကြိယာ’ ရှု။')
,(261,3,4,'ပင့်ခေါ်ရာသို့ လိုက်ပါလာသည့်အတွက် ဆရာဝန်', NULL)
,(263,3,4,'စိုစွတ်သည်။ စွတ်စိုချွဲကျိသည်။ ကယီသည်။','“ဟာဲကၠိက်အယုတ်၊ — လၟုဟ်ဝွံ ဗှ်ေကယဳဒၟံၚ်ကဵုအသုဘ ဂပ်ဂဝ်က္ဍုဟ်ရောၚ်” ဇာဒိသိုၚ်ဂး။ (ဇ—၁၅၃။ အစွောံ။) = “ဟယ် ဝက်ယုတ်၊ ယခုအခါ နင့်ကိုယ်သည် စက်ဆုပ်ဖွယ်ကောင်းသော မစင်ဖြင့်စွတ်စိုပေကျံနေ၏” ဟု ခြင်္သေ့ဆို၏။')
,(264,3,4,'စိုစွတ်သည်။ စွတ်စိုပေကျံသည်။','“ညးဂှ် ကယဳကယဝ်စုတ် အလုံသ္ၚိဝွံရော။” (ဇ—၄၁၇။ အစွောံ။) = “အိမ်အလုံး­ကြဲ၍ အဘယ်သူသည် စိုစွတ်ပေကျံအောင် ပြုထားဘိသနည်း။”')
,(265,3,1,'လောက်ကောင်။', NULL)
,(266,3,4,'ဖင်တကြွကြွဖြစ်သည်။ ဃနာမငြိမ်ဖြစ်သည်။ ရွပိုးထိုးသည်။', NULL)
,(267,3,4,'လှည့်ဖြားသည်။ လိမ်လည်သည်။ (ပါဠိ—ကုဟက)', NULL)
,(268,3,1,'ယက္ကန်းနှတ်ကွင်း။ ယက်ကန်းတိုင် ချည်မျှင်သွင်းရန်နှတ်ကွင်း။', NULL)
,(269,3,4,'ကလိထိုးသည်။', NULL)
,(270,3,4,'ကလိထိုးသည်။', NULL)
,(271,3,1,'ကျော့ကွင်း။ (ပါဠိ—ဂဏူဌိပါသ)', NULL)
,(272,3,1,'ခေါင်းလောင်းသံပြုသည်။ ခေါင်းလောင်းထိုးသည်။', NULL)
,(273,3,1,'ဘုရားအနေကဇာ။','ထောံကယျောၚ်ကျာ် = ဘုရားအနေကဇာတင်သည်။ ‘ပ္တိုန်အယောၚ်ကျာ်’ ဟူ၍လည်း အရေးရှိသည်။')
,(274,3,1,'အဆင်တန်ဆာ။', NULL)
,(274,3,4,'ဆင်ယင်ပေးသည်။','“ကၞုဲမွဲဂှ် ကယိုၚ်လဝ်တုဲ နဇိုၚ်ကဵုဍေံကွာ်အာတုဲ—။” (ဇ—၂၅၇။ အစွောံ။) = “မျောက်တစ်ကောင်ကို ဆင်ယင်ပေးပြီးလျှင် ခြေနှစ်ဖက်တို့ဖြင့် လျှောက်သွားစေ၏။”')
,(275,3,1,'အလှအဆင်တန်ဆာပစ္စည်း။','“ဂၞိန်ယာတ်ကယိုၚ်ကယဝ်အဲတံဂှ် ကေတ်နၚ်ညိ။” = “ငါ၏အဝတ်အစားအဆင်တန်ဆာတို့ကို ယူဆောင်လာပါ။”')
,(275,3,4,'အလှဆင်ပေးသည်။ ဝတ်စားဆင်ယင်ပေးသည်။ တန်ဆာဆင်စေသည်။','“ဇကုဗောဓိသတ်ဂှ် ဂ္ညိ ဂ္ညာတ်ကယိုၚ်ကယဝ်တုဲ (သၟိၚ်အိန်)ပတိုန်လဝ်လတူက္ဍိုပ်စိၚ်ရ။” (ဇ—၁၉၄။ အစွောံ။) = “သိကြားမင်းသည် ဘုရားလောင်းကို ဝတ်စားတန်ဆာဆင်ယင်ပြီးလျှင် ဆင်ဦးခေါင်းထက်­ တင်ထား၏။” || “(သၟိၚ်တုန်) ကောန်ဗြဴပန်ဂှ် ကယိုၚ်ကယဝ်ဗွဲမဒးရးတုဲ ပ္ဍိုက်စုတ်ပ္ဍဲကွဳရတ်မပြဲတုဲ —။” (ဇ—၃ဝ၁။ အစွောံ။) = “(မင်းသည်) ထိုလေးယောက်ကုန်သောသမီးတို့ကို တန်ဆာဆင် စေ၍ ယာဉ်ပေါင်းချုပ်စီးစေ၍—။” (ညောင်ကန်)')
,(276,3,1,'ငြင်းခုံခြင်း။','က္တဵုဒှ်ကယာန် = အငြင်းဖြစ်ပွားသည်။')
,(276,3,4,'ငြင်းခုံသည်။ ငြင်းဆိုသည်။','“အရေဝ်အပါဂှ် ဍာံပြတဴရ၊ လ္ပကယာန်ကဵုအပါညိ။” = “အဖေ့စကားသည် မှန်ကန်သည်။ အဖေ့ကို မငြင်းပါနှင့်။”')
,(277,3,4,'ငြင်းဆိုချေပသည်။ ငြင်းချက်ထုတ်သည်။', NULL)
,(278,3,4,'ငြင်းခုံသည်။ အငြင်းပွားသည်။', NULL)
,(279,3,1,'ငြင်းခုံခြင်း၊ အငြင်းအခုံ။','က္တဵုဒှ်ကယျာန်ဓဝါတ် = အငြင်းအခုံဖြစ်ပွားသည်။ || “ကောန်သၟိၚ်ပန်ဂှ် တၞဟ်တၞဟ်ဟီုတုဲ ဒှ်ကယာန်ဒဝါတ်ကဵုရၚ်သ္ကံ—။” (ဇ—၂၄၈။ အစွောံ။) = “မင်းသားလေးယောက်တို့သည် တစ်ခြားစီပြောဆိုကုန်၍ အငြင်းအခုံဖြစ်ကြကုန်၏။”')
,(280,3,4,'ငြင်းပယ်သည်။ ငြင်းဆန်သည်။', NULL)
,(281,3,4,'အချေအတင်ငြင်းခုံသည်။ အချီအချငြင်းခုံသည်။', NULL)
,(282,3,1,'အခေါက်လျှော်ကို ခေါင်းလျှော်ရာတွင် သုံးရသောချုံနွယ်ပင်။ တရော်။', NULL)
,(282,3,4,'တစ်ခုခုသောဒဏ်ကို ခံရပါများသောကြောင့် မှတ်သွားသည်။ ကျွတ်သွားသည်။','“ဒးတက်လဝ်ဂၠိုၚ် ကယျဝ်အာဣရ။” = “ရိုက်ခံထိပါများ၍ မှတ်သွားပြီ။” || ‘တယျဝ်’ ဟုလည်း ရေးသည်။')
,(283,3,4,'လှပအောင်လုပ်သည်။ အလှဆင်သည်။','“မၞိဟ်ကျေဝ်ကျေဝ် ဟွံဒးက ယျေဝ်ဂၠိုၚ်ရ။” = “လှသောသူသည် များစွာအလှပြင်ရန် မလိုပါ။” || “သၟိၚ်အလဵုအသဳပၞာန်ဗၟာဝွံ ဖံက်ဂၠံၚ်ကၠောန်ဒဒန် တဵုဥဒျာန်ကၠအ်ပ္ကဴ သိုၚ်သ္ၚိတိုက်သမၠုၚ်တုဲ ၜိုန်ကယျေဝ်လဝ်ဍုၚ်ကီုရ၊ ညးဍုၚ် ကွာန်တအ် ဟွံမွဲကဵုအခေါၚ်ဗၠးၜးမ္ဂး ဍုၚ်ဂှ်ရှ်သာဟွံမွဲရ။” = “မြန်မာစစ်အစိုးရသည် လမ်းဖောက် တံတားခင်း ဥယျာဉ်ပန်းခြံစိုက် မြင့်မားသောတိုက်တာများဆောက်၍ တိုင်းပြည်ကို အလှဆင်သော်လည်း ပြည်သူပြည်သားများ လွတ်လပ်မှုမရှိလျှင် ထိုတိုင်းပြည်သည် အနှစ်သာရမရှိပေ။”')
,(284,3,1,'၁။ နွယ်တန်းသီး။', NULL)
,(284,3,1,'၂။ မျှော်စင်။', NULL)
,(284,3,4,'ကိုင်းသည်။ ညွတ်သည်။','“ကယျောဝ်ဇကုတုဲ ၜှ်ပ္ကဴရ။” = “ကိုယ်ကိုကိုင်းပြီး ပန်းခူးသည်။” || “ကၞာၚ်ကြုက်ဇၞော်ဂှ် တယျောဝ်တိတ်အာဒၟံၚ် လ္ပာ်ကြုၚ်တေံရ။” = “သရက်ကိုင်းကြီးသည် ချောင်းဖက်ဆီသို့ ဖြာထွက်သွားသည်။”')
,(285,3,4,'လည်ဆန့်သည်။ လည်ပင်းကိုင်းညွတ်သည်။', NULL)
,(286,3,1,'၁။ မွန်ပျို့ကဗျာ။','လင်္ကာကယျဟ် = ပျို့ကဗျာလင်္ကာ။')
,(286,3,1,'၂။ (ကွတ်ကယျဟ်) = ရေတွက်ခြင်းအတတ်။ သင်္ချာအတတ်။ (?) (ပါဠိ—ဂဏန)', NULL)
,(287,3,1,'‘ကြိယာဗာ’ နှင့်အတူတူ။', NULL)
,(288,3,4,'အနာအကျိတ်အခဲကြေပျောက်အောင် မန်းမှုတ်ပြီး လက်ဖြင့်ဝိုက်ခြေသည်။', NULL)
,(289,3,4,'စတိလုပ်သည်။', NULL)
,(290,3,4,'ပါးအောင်လုပ်သည်။ လျော့ပါးစေသည်။ လျော့နည်းစေသည်။','“သ္ပလွဳ တၞဟ်န ကရဳကၠေံဓဝ်ရာဂတဏှာ။” = “တဏှာရာဂတရားကို လျော့ပါးစေရန်အလို့ငှာ အားထုတ်သည်” ‘ကြဳ’ (ကြိ) လည်းရှု။')
,(291,3,4,'‘ကရေကရောတ်’ ရှု။', NULL)
,(292,3,10,'(န) သနားကြင်နာခြင်း။ ကရုဏာ။','‘ကြုတ်ဏာ’ ဟုလည်း အနည်းအားဖြင့်တွေ့ ရသည်။')
,(293,3,11,'(န) ကရုဏာစိတ်။ သနားကြင်နာတတ်သောစိတ်။', NULL)
,(294,3,10,'(န) သနားကြင်နာမှုနှင့်ရော၍ ဖြစ်သောဒေါသ။ ကရုဏာဒေါသ။', NULL)
,(295,3,10,'(န) (စာပေ) သနားကြင်နာမှုရသ။ ကရုဏာရသ။', NULL)
,(296,3,4,'ညည်းတွားသည်။ ရေရွတ်သည်။ မြည်တမ်းသည်။','“သေဋ္ဌဳဗြဴ ယာံကရေကရောတ်တဴကဵု ကောန်တြုံတိဿဂှ်တုဲရ။” (ဇ—၁၄။ အစွောံ။) = “သူဌေးမသည် သားတိဿနှင့် ငိုကြွေးမြည်တမ်း၏။”')
,(297,3,1,'နောက်ဘက်။ နောက်ကျော။','(ဝိ) နောက်မှာ။')
,(298,3,4,'ကျောခိုင်းသည်။ စွန့်ပယ်သည်။','“ယွံမၞးတံ၊ ဒေဝဒတ်ဝွံ ကရဴကၠေံအ္စာရောၚ်။ ဒစးကၠေံပါၚ်ကျာ်တြဲရောၚ်” ခမဳတံဂး။ (ဇ—၂၃၁။ အစွောံ။) = “ငါ့သျှင်တို့ ဒေဝဒတ်သည် ဆရာကို ကျောခိုင်းစွန့်ပယ်၏။ မြတ်စွာဘုရားစကားကို ဆန့်ကျၚ်၏။”')
,(299,3,4,'ကျောခိုင်းသည်။','“လ္ပကရဴစးကဵုအ္စာညိ။” = “ဆရာကို ကျောမခိုင်းပါနှင့်။”')
,(300,3,1,'မျက်ကွယ်ရာ။','“လ္ပသုၚ်အရက် ကရဴမတ်မိမညိ။” = “မိဘမျက်ကွယ်တွင် အရက်မသောက်ပါနှင့်။”')
,(301,3,1,'ဒီရေရောက်သော ချောင်းဘေးရှိရွှ့ံညွန်တော။', NULL)
,(302,3,4,'ခွဲခြမ်းသည်။','ကရေက်ဒုန် = ဝါးကိုခြမ်းသည်။ || ကရေက်အှ်ော = ထင်းခွဲသည်။')
,(302,3,9,'တစ်ခြမ်း။ တစ်ပိုင်း။','အှ်ောပိကရေက် = ထင်းသုံးခြမ်း။')
,(303,3,1,'၁။ ချိုင့်ဝှမ်း။','ကရော်ဒဵု = တောင်ကြားချိုင့်ဝှမ်း။')
,(303,3,1,'၂။ ခွက်။','ကရော်ဍာ် = ရေခွက်။ (‘ခရော်’ ဟုလည်းရေးသည်။)')
,(304,3,1,'၁။ ရေသွယ်ရန် သွပ်၊ ဝါးစသည်ဖြင့် လုပ်ထားသောအရာ။ ရေတံလျှောက်။','ကရံက်သ္ၚိ = အိမ်အမိုးရေတံလျှောက်။')
,(304,3,1,'၂။ နွယ်ပင်လျှောက်သောတန်း။', NULL)
,(304,3,1,'၃။ ဓါးစသည်တို့တွင် အလျားလိုက်ဖော်ထားသောအကြောင်း။ ပြော့ကြောင်း။ မျှော့ကြောင်း။', NULL)
,(305,3,4,'လိုက်ဖက်ကြည့်ကောင်းအောင် ဆင်ယင်ပေးသည်။','“ကောန်ၚာ်ဂှ် ကရိုက်လဝ်ကဵုပ လောအ်သာ်ဗ္ကေတ်ဂှ် ရံင်ကျေဝ်ကွေံကွေံရ။” = “အင်္ကျီအနီရောင်ဖြင့် ကလေးနှင့်လိုက်ဖက်အောင် ဆင်ယင်ထားသည်မှာ ကြည့်၍အလွန်လှသည်။” || ကြိုက်’ (ကြိ) လည်းရှု။')
,(306,3,5,'သင့်တင့်လျောက်ပတ်စွာ။ အထိုက်အလျောက်အားဖြင့်။', NULL)
,(307,3,5,'စိတ်ကြိုက်။ စိတ်တိုင်းကျ။ စိတ်အလိုကျ။','“ဂၞိန်ယာတ်ပလောအ်ကျေဝ်ကျေဝ် နွံဒၟံၚ်ဂလိုၚ်၊ ဒၞာဲဒးကဵုမတ်ဂှ် ရုဲကေတ်ကရိုက်စိုတ်ရ။” = “အဆင်လှသော ထဘီအင်္ကျီအဝတ်အစား များစွာရှိသည်၊ ကြိုက်နှစ်သက်ရာကို စိတ်တိုင်းကျရွေးယူပါ။” || “ပ္ကဴဒကှ်တၠအဲဂှ် ဆကရိုက် စိုတ်သၟိက်ကဵုဂှ် မွဲဍောၚ်ၜါဍောၚ်လေဝ်ကဵုဒှ်ရ ကဵုဒါန်ကုပိုဲညိရ။” (ဇ—၂၆၁။ အစွောံ။) = “သင်၏ကြာပန်းတို့ကို သင့်စိတ်အလိုကျ သင်ပေးချင်သလောက် တစ်ပွင့်နှစ်ပွင့်လည်းဖြစ်စေ ငါတို့ကို ပေးပါလော့။”')
,(308,3,1,'၁။ တံစဉ်း။ (သံတိုက်ရန်)','‘ကြာၚ်’ (ကြိ) နှင့်နှိုင်းယှဉ်။')
,(308,3,1,'၂။ (ဆင်ချိတ်ရန်) ချွန်းတောင်း။', NULL)
,(309,3,1,'(ပန်းတစ်မျိုး၏) အဖူးအငုံ။ (?)', NULL)
,(310,3,1,'ကရင်လူမျိုး။ ကရင်တိုင်းရင်းသား။','ကရေင်နာဍိ၊ ကရေင်မန် = ပိုးကရင်။ မွန်ကရင်။ || ကရေင်ဗၟာ = မြန်မာကရင်။ စကောကရင်။')
,(311,3,1,'ကရင်နီလူမျိုး။ ကယားတိုင်းရင်းသား။', NULL)
,(312,3,1,'အကြောင်း။ မျှော့ကြောင်း။ လျှာထိုးအကြောင်း။ အက်ကွဲကြောင်း။','ကရောၚ်ဂၠံၚ် = လမ်းအက်ကွဲကြောင်း။ || ကရောၚ်ဆု = သစ်သားအက်ကြောင်း။ || ကရောၚ်တိ = မြေအက် ရာအကြောင်း။ || ကရောၚ်ၜုန် = ဓါးမြောၚ်ပျော့ကြောင်း။ ဓါးမြောၚ်မျှော့ကြောင်း။')
,(313,3,4,'ရင့်မာစေသည်။ ရင့်ကျက်စေသည်။','တရံၚ်လဝ်စိုတ် = စိတ်တင်းထားသည်။ အားတင်းထားသည်။ စိတ်ခိုင်မာအောင်ထားသည်။ || တရံၚ်လဝ်ပါရမဳ = ပါရမီရင့်စေသည်။ || ‘ကြံၚ်’ (ကြိ) လည်းရှု။')
,(314,3,4,'ကူညီသည်။ ရိုင်းပင်းသည်။','ဗိုၚ်ကရိုၚ် = ဝိုင်းဝန်းကူညီသည်။')
,(314,3,4,'ကူညီသည်။ ရိုင်းပင်းသည်။','“ကလောန်အဲ အဲကၠောန်ကေတ်ဂွံဒၟံၚ်ရ၊ ဗှ်ေဟွံဒးကရိုၚ်အဲရ။” = “ငါ့အလုပ်ကို ငါလုပ်ယူလို့ရတယ်၊ နင်ငါ့ကို ကူဘို့မလိုပါ။”')
,(315,3,1,'၁။ ကြားဖြတ်ခြင်း။ လမ်းအကြားမှ ဖြတ်ခြင်း။','ဂၠံၚ်ကရတ် = ဖြတ်လမ်း။ ‘ကြတ်’ (ကြိ) လည်းရှု။')
,(315,3,1,'၂။ ဆောင်း။ (ငါးဖမ်းကိရိယာ)', NULL)
,(316,3,1,'ဆပ်သွားဘီး။ (ယက္ကန်းသုံး)','')
,(316,3,3,'ဆေးကြောသော။','ဍာ်ကရာတ်ဇိုၚ် = ခြေဆေးသောရေ။ || ဍာ်ကရာတ်မၞိက် = ပတ္တမြားဆေးထားသောရေ။ || ‘ကြာတ်’ (ကြိ) လည်းရှု။')
,(317,3,1,'ငါးဖမ်းဆောင်း။','‘ကရတ်-၂’ နှင့်အတူတူ။')
,(318,3,1,'ဝက်မှင်ဘီး။', NULL)
,(319,3,11,'(န) သနားကြင်နာခြင်း။ ကရုဏာတရား။', NULL)
,(320,3,4,'ညည်းသည်။ ညည်းညူသည်။','“သြန်ဍေံဟွံမွဲဂးတုဲ ဍေံကရောတ်ဒၟံၚ်လၟိုန်ရ။” = “သူ့မှာပိုက်ဆံမရှိဘူးဆိုကာ သူအမြဲညည်းညူနေတာပဲ။”')
,(321,3,4,'ညည်းတွားသည်။ ညည်းညူသည်။', NULL)
,(322,3,1,'ပူဆွေးသည်။ ဝမ်းနည်းကြေကွဲသည်။', NULL)
,(323,3,4,'ငိုမြည်တမ်းသည်။ ရှိုက်ကြီးတငင်ငိုသည်။','“သၟိၚ်စိၚ်မိၚ် (ဒဒှ်သၟိၚ်စုတိ) တုဲ နလပှ်ဇွိတ်သပေါတ်ကောန်ၚာ်ဂှ်တုဲ — ရေရောတ်ကရောတ်သ္အဝ် ယာံတဴသ္ငံသ္ငံ—။”(ဇ—၁၅၆။ အစွောံ။) = “ဆင်မင်းသည် မင်း၏နတ်ရွာစံကြောင်းကို ကြားသိပြီးနောက် မင်းသားငယ်ကို နှာမောင်းဖြင့်သုံးသပ်၍ ညည်းတွားငိုမြည်တမ်းလျက် သည်းစွာငိုကြွေးလေ၏။” || “ဂတာံဂှ် မိၚ် သဒ္ဒရမျှာၚ်စိၚ်ဗြဴ မဟီုဍိုန်ဍောတ်ကရောတ်သ္အဝ်တဴဂှ် ကလၚ်ဒၟံၚ်တုဲ ဟွံတံၚ်ဒဇက်ဇိုၚ်စိၚ်ရ။” (ဇ— ၂၆၇။ အစွောံ။) = “ဗုစွန်သည် သာယာစွာငိုမြည်တမ်းသော ဆင်မ၏အသံကိုကြား၍ မ,သံ­ နားထောင်လျက် ဆင်၏ခြေကို မဆွဲတော့ဘဲနေ၏။” || ‘သရောတ်သအဝ်’ လည်းရှု။')
,(325,3,3,'(ဆံပင်) လိမ်ကောက်မာကြမ်းသော။','သော်ကရန် = လိမ်ကောက်မာကြမ်းသော ဆံပင်။')
,(326,3,4,'ဓါးဖြင့်အရာပေးသည်။','“ကဂှ် ကရန်ထောံတုဲ ဂွပ်လဝ်ကဵုၜဵုညိ။” = “ငါးကို ဓါးရာပေးပြီး ဆားနှင့်သိပ်ထားပါ။”')
,(327,3,1,'ရေညှိ။', NULL)
,(328,3,4,'အက်သည်။ အက်ကွဲသည်။','“ပ္ၚာန်ကရောန်အာရ။” = “ပန်းကန်အက်သွားသည်။”')
,(329,3,11,'(န) အက္ခရာတို့၏ဖြစ်ကြောင်းဖြစ်သော လျှာလည်၊ လျှာဖျားစသည်။ ကရိုဏ်း။', NULL)
,(330,3,6,'အနီးအနား။','“အပေါတ်ဏအ် စွံလဝ်ကရပ်အဲညိ” = “ဤပစ္စည်းကို ကျွန်တော့်အ နားမှာထားပါ။”')
,(330,3,4,'အနားကပ်ထားသည်။ နီးကပ်စေသည်။','“ပလၚ်ဂဥုဲဂှ် ကရပ်လဝ်ကဵု အဲညိ။” = “ဆေးပုလင်းကို ကျွန်တော့်အနားကပ်ထားပါ။” || ‘ကြပ်’ (ကြိ) လည်းရှု။')
,(331,3,1,'သားငါးကိုမီးကင်ရန် ညှပ်ရသောဝါးတံ။ တံညှပ်။','“ကဂှ် စုတ်ပ္ဍဲကရာပ်တုဲ ပရာၚ်ရ။” = “ငါးကို တံညှပ်ထဲထည့်ပြီး မီးကင်သည်။” || ‘ကြာပ်’ (ကြိ) လည်းရှု။')
,(332,3,1,'အကြား။ စပ်ကြား။', NULL)
,(332,3,3,'ကျဉ်းမြောင်းသော။','“ကွဳသၟိၚ်ဨကရာတ်ၜါ — အာဆဵု ဒးညးသ္ကအ် ပ္ဍဲဋ္ဌာန်ကရေပ်မွဲ—။” (ဇ—၁၅၁။ အစွောံ။) = “မင်းဧကရာဇ်နှစ်ပါး၏ရထားတို့သည် ကျဉ်းမြောင်းသောနေရာတစ်ခု­ ဆုံမိကြ၏။”')
,(332,3,4,'ကျဉ်းကျပ်စေသည်။ ကြားတွင်ညှပ်မိစေသည်။','‘ကြေပ်’ (ကြိ) လည်းရှု။')
,(333,3,4,'အကြပ်ကိုင်သည်။','“သြန်အဲဂၠေံလဝ်ဂှ် အဲကလေၚ်လေဲဟွံမာန်ဏီ၊ လ္ပကရေပ် ဒရတ်အဲညိ။” = “ကျွန်တော်ချေးယူထားသောငွေကို ကျွန်တော်မပေးဆပ်နိုင်သေးပါ၊ ကျွန်တော့်ကို အကြပ်မကိုၚ်ပါနှင့်။”')
,(334,3,4,'၁။ (မိုး) သည်းထန်သည်။','“ဗြဲကရိုပ်ဗွဲမလောန်ရ။” = “မိုးအလွန်သည်း ထန်စွာရွာသွန်းသည်။”')
,(334,3,4,'၂။ စေတနာ၊ သဒ္ဓါတရားဖြင့် ကျွေးမွေးသည်၊ အလှူပေးသည်။','တရိုပ်ကဵုဒါန် = အလှူပေးသည်။')
,(335,3,1,'စိတ်အလို။ စိတ်ဆန္ဒ။', NULL)
,(336,3,6,'အတူတကွ။ နှင့်အတူ။','“မၚ်ဗၠာဲအာဂၠာဲအှ်ော အာဂၠာဲသၞေဝ် ကရောံညး ဂမၠိုၚ်။” (ဇ—၁၂၃။ အစွောံ။) = “လုလင်သည် လူအများနှင့်အတူ ထင်း၊ ဟင်းရွက်သွားရှာ၏။” || “ညးပိစှ်ောပိဂှ် ညာတ်ဗောဓိသတ်တုဲ ဒ္ဂေတ်ဗက်ကၠောန်ၜိုတ် ကရောံဗောဓိသတ်ရ။” (ဇ—၃၁။ အစွောံ။) = “သုံးဆယ့်သုံးယောက်ကုန်သောသူတို့သည် ဘုရားလောင်းကိုမြင်၍ ဘုရားလောင်းနှင့်အတူတကွ လိုက်၍လုပ်ကိုၚ်ကြကုန်၏။” || “ကဵုအဲဂွံအာ ကရောံနာဲပိုဲတံညိကီု။” (ဇ—၂၄၃။ အစွောံ။) = “ငါ့ကို သင်တို့နှင့်အတူ သွားပါရစေ။”')
,(337,3,1,'ကြုံးဝါးခြင်း။ ဥဒါန်းကျူးခြင်း။ ဝမ်းမြောက်သောစကား။','ဂလာန်ကရီု = ကြုံး ဝါးသောစကား။ ဥဒါန်းကျူးရင့်သောစကား။ || “(ဗောဓိသတ်)ကျိုၚ်ကျဝ်တိုန်ဍိုက်စိၚ်တုဲ ကရီုညံၚ် ကေသရာဂှ်ကြီုတုဲ (တိတ်ဗ္တိုက်ပၞာန်သတြုရ။)” (ဇ—၈ဝ။ အစွောံ။) = “ဘုရားလောင်းသည် တန်ဆာဆင်၍ ဆင်ထက်တွင်တက်စီးကာ ကေသရာဇာခြင်္သေ့မင်း၏ ကြုံးဝါးခြင်းကဲ့သို့ ကြုံးဝါး လျက် ရန်သူစစ်ကို ထွက်တိုက်၏။” || “ယွံမရာတ်—၊ (ပစ္စေဂဗုတ်ဂှ်) နအနုဘဴဣတေံ ကလာၚ် ကၠုၚ်စိုပ် လတူပြသာဒ်မရာတ်တုဲ ဂါထာကရီု မရနုက်ကဵုဒစာံမြဴဝွံဂှ် ဣတေံကြီုတဴရောၚ်။” (ဇ— ၄၁၈။ အစွောံ။) = “အရှင်မင်းကြီး၊ ထိုပစ္စေကဗုဒ္ဓါသည် မိမိ၏တန်ခိုးအာနုဘော်ဖြင့် ကောင်းကင်ခရီးဖြင့် အရှင်မင်းကြီး၏နန်းပြာသာဒ်ပေါ်သို့ လာရောက်၍ ရှစ်ခုမြောက်သော ဥဒါန်းဂါထာကို ကျူးရင့်၏။ || “ကရီုမြဴဝွံ ကောန်တြုံသၟိၚ်ဂါမနိဂှ် ကြီုတဴကဵုဇကုပ္ဍဲစိုတ်ရ။” (ဇ—၈။ အစွောံ။) = “ဂါမဏိမင်းသားသည် ဤဝမ်းမြောက်သောစကားကို မိမိစိတ်ထဲ­ကျူးရင့်၏။” || ‘ကြီု’(ကြိ)၊ ‘အကြီု’(န) လည်းရှု။')
,(338,3,1,'(ဆင်၏) ဟည်းသံ။ အော်ဟစ်ကြုံးဝါးသံ။','“နကဵုဗရုကရီုဇၟူဂှ် (သၟိၚ်စိၚ်)ကရေဲဂအတ် ရမျှာၚ်ကြီုတုဲ ဒြေပ်ဗတိုက်လောပ်အာ ပ္ဍဲဒေါဝ်ဗဵုပၞာန် (သတြုရ။)”(ဇ—၁၅၆။ အစွောံ။) = “ဆင်မင်းသည် ကြိုးကြာသံနှင့်တူသော ဟည်းသံကိုပြု၍ အော်ဟစ်ကြုံးဝါး၍ ရန်သူ့ဗိုလ်ထုအလယ်သို့ ပြေးဝင်တိုက်ခိုက်၏။”')
,(339,3,1,'မိုးချုန်းသံ။ ထစ်ကြိုးသံ။ ထစ်ချုန်းခြင်း။ (ပါဠိ—ဂဇ္ဇိတ)', NULL)
,(340,3,4,'ဖြူးသည်။', NULL)
,(341,3,4,'ဟစ်အော်သည်။','ကရေဲကော် = အော်ခေါ်သည်။')
,(341,3,1,'(ဆင်၏) ကျည်ခြင်း။ ကြိုးကြာသံနှင့်တူသော အောင်သံဖြင့်ဟစ်အော်ခြင်း။','“(စိၚ်ဂှ် လပိုက်ဂစိုတ်ကၠေံဣသိဂှ်တုဲ) နကရေဲဇၟူဂှ် ဂအတ်ရမျှာၚ်ဇၞးတုဲ စိၚ်လောပ်အာဂြိုပ်ဇၞော်ရ။” (ဇ— ၁၆၁။ အစွောံ။) = “ဆင်သည် ရသေ့အား ဆောင့်ပုတ်သတ်ပြီးလျှင် ဆင်ပြောင်၏အောင်သံဖြင့် ကြိုးကြာသံကဲ့သို့မြည်၍ တောထဲသို့ဝင်သွား၏။”')
,(342,3,1,'၁။ ဂျင်။','“ကောန်ၚာ်တအ်ဂှ် ၜံက်ဝေၚ်ဒၟံၚ်ကရောဲအိုတ်ရ။” = “ထိုကလေးများသည် ဂျင်ပေါက်ကစားနေကြသည်။”')
,(342,3,1,'၂။ (ကစားစရာ) ဘောလုံး။ (ပါဠိ—ကန္ဒုက)','“သၟတ် ယညဒတ္တဂှ် ၜံက်ဝေၚ်ကရောဲတုဲ ကရောဲဂှ်လုပ်အာ ပ္ဍဲဂမြေၚ်တၞအ်ဇြုံဇာတ်ဂှ်တုဲ ဒတုံဒးဇြုံဇာတ်ဂှ်ရ။” (ဇ—၄၄၄။ အစွောံ။) = “ယညဒတ်၏ မြေ­ခတ်အပ်သော အိမ်ကျင် (ဘောလုံး) သည် လိမ့်လျက်သွားလေ၏။ ထိုတောင်ပို့တွင်း­ မြွေဟောက်၏ဦးခေါင်းပေါ်­ ကျလေ၏။” (ညောင် ကန်)')
,(342,3,1,'၃။ ကျောက်ဆူးကြိုးတင်ချစက်။ ဝန်တင်ဝန်ချစက်။', NULL)
,(343,3,4,'ဆဲရေးသည်။ စကားနာထိုးသည်။','“မူပဗှ်ေဂွံကၠုၚ်ကရောဲဒၟံၚ်အဲရော။” = “ဘာဖြစ်လို့ငါ့ကို နင်လာပြီးစကားနာထိုးနေရသလဲ။”')
,(344,3,1,'လေရဟတ်။', NULL)
,(345,3,1,'ဆဲဆိုအရှက်ခွဲသည်။ ရှက်စေသည်။ အရှက်ရစေသည်။','“ဗြဴဒမိက်မဟွံမွဲကဵုသဳလဂှ်) သၟိၚ်ဣန်ကရောဲဂဝ ပျုတ်ဗဒေက်ကၠေံတုဲ ဋ္ဌာန်ဍုၚ်သွဝ်တေံဟေၚ် သၟိၚ်ဣန်တိုန်အာရ။”(၅၅ဝ။ ဇ—၃၇၄။ ဒု—၃၅၉။ အစွောံ။) = “ထိုသီလမရှိသော မိန်းမယုတ်ကို သိကြားမင်းသည် အရှက် ရအောင်ရှုတ်ချ၍ မိမိနေရာနတ်ပြည်သို့ ပြန်တက်သွား၏။”')
,(346,3,4,'ညည်းညူသည်။ ညည်းတွားသည်။ (ပါဠိ—ထုနာတိ','နိတ္ထုန)')
,(347,3,1,'နှာရည်။ နှပ်ရည်။', NULL)
,(348,3,4,'ဦးခေါင်းတွင်ပန်ဆင်သည်။','ကရှ်ပ္ကဴ = ပန်းပန်သည်။')
,(349,3,1,'တစ်စလယ်။ (နို့ဆီဗူးနှစ်ဗူးရှိသော အခြင်အတွယ်)', NULL)
,(350,3,4,'(ရေ) သွန်သည်။ လောင်းသည်။', NULL)
,(351,3,4,'ရေစက်ချအမျှဝေသည်။', NULL)
,(352,3,4,'ကိုယ်ခန္ဓာကို ဆူဖြိုးစေသည်။','“ဍေံဏအ်မွဲဂှ် စတုဲတိက် ဆကရောအ်ဇကု ဂလိုၚ်ဖျုန်သၟးရ။” = “ဤသူတစ်ယောက်သည် စပြီးအိပ်ကာ ခန္ဓာကိုယ်ကို ဆူဖြိုးစေရုံ အသားကို တိုးစေရုံမျှသာတည်း။”')
,(353,3,1,'ခရာ။ (တူရိယာပစ္စည်း)', NULL)
,(354,3,1,'၁။ သန်ဖက်ခါပြီးနောက်တစ်ရက်။ ဖိန်းနွဲခါ။', NULL)
,(354,3,1,'၂။ သေတ္တာ။ တံတင်း။','“ယြဴညးမွဲ ဂွံစဖျုန်မြာ်ထဝ်တုဲ ဟွံဗျုဟွံချိုတ်ရ” သာ်ဝွံစုတ်လဝ်လိက်တုဲ စုတ်လဝ်ပ္ဍဲက လာရ။ (ဇ—၁၅၉။ အစွောံ။) = “ရွှေဥဒေါင်း၏အသားကို စားရသောအကြင်သူသည် မအိုမ သေလတ္တံ့” ဟုစာရေး၍ တံတင်း (သေတ္တာ) ထဲ­ထည့်ထား၏။')
,(354,3,1,'၃။ လူသေအလောင်းထည့် သောခေါင်း။ တလား။', NULL)
,(355,3,1,'လူသေအလောင်းထည့်သောခေါင်း။ တလား။','‘ကလာ/ကဠာ/တလာ—၃’ နှင့်အတူတူ။ || “ဇွဂၞကျာ် စုတ်လဝ်ပ္ဍဲကဠာဒၞိဟ်တုဲ—။” (ဇ—၂ဝ၇။ အစွောံ။) = “မိဖုယား၏အလောင်းကို တလား­ လျောင်းစေလျက်—။” (ညောင်ကန်)')
,(356,3,1,'ကရမက်။ (အသားနံ့သာပင်တစ်မျိုး)', NULL)
,(357,3,4,'၁။ (အချိန်၊ နေရာစသည်ကို) လွန်သည်။ ကျော်လွန်သည်။','“ပ္ဍဲကာလဂှ် သၟိၚ်ဗာရာဏသဳ ပကၠေံကာဂစိုတ်တုဲ ကလိအာထပှ်တ္ၚဲရ။” (ဇ—၅၂၉။ အစွောံ။) = “ထိုအခါ ဗာရာဏသီမင်းသေ၍ ခုနစ်ရက်မြောက်သောနေ့ဖြစ်၏။” || “သကိုပ်သာဗၞိက်သမၠီုဂှ် ဗ္ဂန် ကေတ်ကွဳစောတ်မသုန်ကၠံဂှ်တုဲ ဇက်အာရ။ ဗဗွဲလၟေၚ် ကလိကၠေံဒမံၚ်မၞိဟ်တုဲ အာစိုပ်ပါၚ်တရၚ် ကန္တာရ။” (ဇ—၁။ အစွောံ။) = “လှည်းကုန်သည်မိုက်သည် ငါးရာကုန်သောလှည်းတို့ကိုက၍ ထွက်သွားလေသည်ရှိသော် အစဉ်သဖြင့် လူတို့၏နေရပ်ကိုလွန်၍ ကန္တာရ၏အဦးအဝသို့ရောက် ၏။”')
,(357,3,4,'၂။ (ရုပ်အဆင်း၊ အရည်အချင်း၊ ဉာဏ်ပညာ၊ အတတ်စသည်) လွန်သည်။ သာလွန်သည်။','“ဂၞကျာ်ဥပရိဒေဝဳ မၞုံရုပ်မဂေါဝ်လောန် မကလိကၠေံဗြဴပ္ဍဲဍုၚ်မၞိဟ် မၞုံရုပ်သာ်မဟွံဂွံစိုပ်ဗြဴ သွဝ်ညိကီု။” (ဇ—၂ဝ၇။ အစွောံ။) = “ဥပရီမိဖုယားသည် အလွန်အဆင်းလှ၏၊ လူမိန်းမ၏အ ဆင်းကို လွန်၏။ နတ်သမီးအဆင်းကို မမှီတတ်။” || “သၟိၚ်ကုသတၠဍုၚ်ကုသဝတဳ မပတၠကွတ် မကလိကၠေံကွတ်ညး အလုံဂတာဇမ္မုဒိပ် မဒှ်သၟိၚ်မပြဲ။” (ဇ—၅၃၁။ အစွောံ။) = “ဇမ္ဗူဒိပ်တစ်ခွင် သူတကာတို့၏အတတ်ထက် သာလွန်သောအတတ်ရှိသော မြတ်သောမင်းဖြစ်သော ကုသဝတဳပြည့်ရှင်ကုသမင်း။”')
,(357,3,4,'၃။ (တစ်စုံတစ်ခုသော အတားအဆီး၊ အကန့်အသတ်စသည်ကို) လွန်သည်။ လွန်မြောက်သည်။','“ကုတၠအရှန်တံဂှ် ဒုဟ်ပွသုမၚ်္ဂလကီု ဒုမၚ်္ဂလကီု ကလိကၠေံတုဲရ။” (ဇ—၈၇။ အစွောံ။) = “ရဟန္တာပုဂ္ဂိုလ်တို့အား သုမင်္ဂလအမှုဟူ၍၄င်း ဒုမင်္ဂလအမှုဟူ၍၄င်း မရှိ၊ ထိုအပြစ်တို့ကို လွန်မြောက်ပြီးသည်ဖြစ်၏။”')
,(358,3,4,'မည်းညစ်စေသည်။ ညစ်ညမ်းစေသည်။ ညစ်နွမ်းစေသည်။','“ကၠိက်တံ ဂှ် ပိုဲကလိကၠေံလျးမၞိက်ဝွံညိဂးတုဲ ပဒတဴလွဳပရာရ။ ကလိကၠေံဟွံကၠိတုဲရ။” (ဇ—၂၈၅။ အစွောံ။) = “ထိုဝက်တို့သည် ပတ္တမြားရောင်ကို မည်းညစ်သွားအောင်ပြုအံ့ဟု အားထုတ်ကုန်၏။ မည်း ညစ်အောင်ပြုခြင်းငှာ မတတ်နိုင်ကုန်။” || ‘ကၠိ’ (ကြိ) လည်းရှု။')
,(359,3,4,'လက်ခံနိုင်သောစည်းကို ဖောက်ဖျက်ကျော်လွန်သည်။ အတိုင်းအရှည်ကိုလွန်သည်။','“(ဗမၞိဟ်ဗြဴဂှ် ဇၞော်ကဵုလောဘလောန်၊ ဆဍုတ်သၞေၚ်ထဝ် သၟိၚ်ၜိုပ်မပရအ်ကဵုဂှ် ဟွံပေၚ်ကဵု တရိုပ်စိုတ်) ကလိကၠေံဗၞတ်တုဲ အနိၚ်ပိုက်ကေတ်ဍုတ်သၞေၚ် သီုဖအိုတ်တံဂှ်ရ။” (ဇ—၁၃၆။ အစွောံ။) = “ထိုပုဏ္ဏေးမသည် အလွန်လျှင်လောဘကြီး၏။ ဟင်္သာမင်းဝေပေးသော ရွှေအတောင်တို့ဖြင့် အလိုမပြည့်မူ၍ အတိုင်းအရှည်ကိုလွန်၍ ရွှေဟင်္သာမင်း၏ အားလုံးသောအမွေးအတောင်တို့ကို အတင်းအဓမ္မနှုတ်ယူ၏။” || “ယွံတၠညး၊ နလဟီုမွဲ မလောန်နူဗၞတ် လ္ပဟီုညိ။ နဂလာန်မွဲ မကလိကၠေံဗၞတ်ဂှ် လ္ပဟီုညိ။” (ဇ—၂၁၅။ အစွောံ။) = “အရှင်မင်းကြီး၊ ပမာဏကိုလွန်သောအ ပြောကို မပြောလေနှင့်။ အတိုင်းအတာကို လွန်သောစကားကို မဆိုလေနှင့်။”')
,(360,3,4,'ရရှိသည်။','“ပူဂဵုမဂွံဟုဲဟာဲကဵုတၠပညာတုဲ ကလိဂွံတသိုက် မဆောတ်ဟွံမွဲရ။” = “ပညာရှိနှင့်ပေါင်းဖော်ရသောသူသည် ချမ်းသာသုခကို ရရှိမည်မချွတ်။” || “ဒေဝဒတ်ပလွဳသၟိက်ဂ စိုတ်ကျာ်တြဲတုဲ ဒဒိုက်မရိၚ်ကတၚ်ဟေၚ် မဒးကလိဂွံဂတမတ်ရ။” = “ဒေဝဒတ်သည် မြတ်စွာဘုရားကို လုပ်ကြံရန်အားထုတ်သဖြင့် ခါးသီးသောဒုက္ခကို မျက်မှောက်ရရှိ၏။”')
,(361,3,4,'သေသည်။ စုတေသည်။ ကွယ်လွန်သည်။ ဘဝပြောင်းသည်။', NULL)
,(362,3,4,'၁။ ကျော်လွန်သည်။ သာလွန်သည်။ လွန်မြောက်သည်။', NULL)
,(362,3,4,'၂။ သေဆုံးသည်။ ကွယ်လွန်သည်။','“သီုမိမၜါ ကလိလောန်အာအိုတ်တုဲရ။” = “မိဘနှစ်ပါးစလုံး ကွယ်လွန်ကြကုန်ပြီ။”')
,(363,3,4,'အပြစ်ကျူးလွန်သည်။', NULL)
,(364,3,4,'သေသည်။ စုတေသည်။ ကွယ်လွန်သည်။', NULL)
,(365,3,1,'မနက်ဖြန်ပြီး နောက်တစ်နေ့။ သန်ဘက်ခါ။','“ယးဂတတုဲ ပိုဲသတီရ၊ ကလဳ တေံတုဲ အဲသတီရ သာ်ဝွံဇလိၚ်ဇၚဲဖအိုတ်ကၠေံတ္ၚဲရ။” (ဇ—၂၁၈။ အစွောံ။) = “မနက်ဖြန်ခါသိ စေမည် သန်ဘက်ခါသိစေမည်ဟု ရှည်ဝေးအောင် အချိန်ဆွဲ၍ ရက်ကိုကုန်လွန်စေ၏။”')
,(366,3,4,'၁။ ရေထဲကိုယ်ကိုဖော့ကူးသည်။ ကိုယ်ဖော့သည်။', NULL)
,(366,3,4,'၂။ အလုံးဖြစ်အောင် လက်ဖြင့်လုံးသည်။','ကလဲမဝေၚ် = လောက်စာလုံးလုံးသည်။')
,(367,3,1,'ဆွေမျိုးသားချင်း။', NULL)
,(368,3,1,'ဆွေမျိုး။ ဆွေမျိုးညာတိ။','“အဲတုန်လေဝ် မိမကလောဒညာတ်အဲဟွံမွဲ။” (ဇ—၉၆။ အစွောံ။) = “အကျွန်ုပ်မှာကား မိဘဆွေမျိုးများမရှိ။” || “(ရသိဝွံ) ကလောဒညာတ် တၠအဲလေဝ်ဟွံသေၚ်။” (ဇ—၂၅၉။ အစွောံ။) = “ဤရသေ့သည် သင်၏ဆွေမျိုးညာတိလည်းမဟုတ်။”')
,(369,3,1,'မိဘနှစ်ဖက်စလုံးမှ ဆွေမျိုးသားချင်းများ။', NULL)
,(370,3,1,'ဆွေမျိုးညာတိ။ ဆွေမျိုးသားချင်း။', NULL)
,(371,3,1,'ဆွေမျိုးစဉ်ဆက်။', NULL)
,(372,3,1,'ဆုကလဴ = ကလောပင်။', NULL)
,(373,3,1,'(အသံ၊ စကား) မပီမသဖြစ်အောင်ပြုသည်။','ဟီုကလဴလဝ်ရမျှာၚ် = အသံမပီမသ ဖြစ်အောင်ပြောသည်။ || ဟီုကလဴလဝ်ဂလာန် = စကားမရှင်းအောင် တမင်လုပ်ပြောသည်။ ‘ကၠဴ’ (ကြိ) လည်းရှု။')
,(374,3,4,'၁။ ရှင်းလင်းစေသည်။ ပီသစေသည်။','ကလးအဓိပ္ပါယ် = အဓိပ္ပါယ်ရှင်းပြသည်။')
,(374,3,4,'၂။ မောင်းနှင်သည်။ နှင်တံနှင့်နှင်သည်။','လေံကလး = နှင်တံ။')
,(374,3,4,'၃။ (ငွေ၊ ပိုက်ဆံ) ကျသင့်သည်ကို ပေးချေသည်။','ကလးသြန်၊ ကလးသၠုဲ = ကျသင့်ငွေကိုရှင်းသည်။ ပိုက်ဆံရှင်းသည်။')
,(375,3,4,'၁။ (မျက်စိ) ကန်းစေသည်။','“ဂစေံတၞောတ်အာတ်အရီုဗၚ်ကဵုခဍာ် ကဵုခဍာ်ၜံက်က လက်ကၠေံ မတ်စိၚ်ဒမြိုဟ်ဂှ်ရ။” (ဇ—၃၅၇။ အစွောံ။) = “နှံစုတ်ငှက်သည် ကျီးကို ထိုဆင်ကြမ်း၏မျက်စိတို့ကို ကန်းသွားအောင် နှုတ်သီးဖြင့်ထိုးဖောက်ပစ်ပါရန် ကျီးထံအကူအညီတောင်း၏။”')
,(375,3,4,'၂။ (တံခါးစသည်) အကြားအလပ်မရှိ ထိစပ်စေသည်။ စေ့သည်။ အလုံပိတ်သည်။','“တရၚ်ဂှ် ကၟာတ်ကလက်ကၠေံညိ။” = “ထိုတံခါးကို စေ့အောင်ပိတ်လိုက်ပါ။” || “နၜဲ မှေဟ် ပိုဟ်နဝိုဟ် မၞးတံချအ်ကလက်လဝ်သိုၚ်ကတောဝ်အိုတ်” ရဴဝွံကဵုလန်ဟီု။ (ဇ—၂၄၁။ အစွောံ။) = “ပဲကြီးမုံ့ညက်ဖြင့် သင်တို့နားပေါက်တို့ကို ဆို့ပိတ်ထားကြကုန်လော့” ဟုကြေညာစေ၏။')
,(375,3,4,'၃။ ပျက်ပြုန်းစေသည်။ အမျိုးတုံးစေသည်။','“ဂကူဇၞော်တအ်ဂှ် ၚိတ်ကလက်ဒၟံၚ် ဂကူဍောတ်ဂမၠိုၚ်ဟာ။” = “လူမျိုးကြီးတို့သည် လူမျိုးငယ်များအား အမျိုးတုံးသွားအောင် ဝါးမျိုနေ ကြသလား။”')
,(376,3,4,'(ခေါ်သောအခါ) ပြန်ထူးသည်။ ထူးသံပေးသည်။','“ယွံတၟံလး၊ ပယတ်အဲကော်ဂှ် တၠအဲကလုက်ကဵုအဲ၊ တ္ၚဲဝွံအဲကော်ဂှ် မူပဟွံကလုက်ကဵုအဲရော” သၟိၚ်ကၞုဲဂး။ (ဇ—၅၇။ အစွောံ။) = “အိုကျောက်ဖျာ၊ အခါတိုင်းငါခေါ်သည်ရှိသော် သင်သည် ငါ့ကိုထူး၏။ ယခုငါခေါ်သောအခါ အဘယ်ကြောင့်မထူးသနည်း” ဟုမျောက်မင်းဆို၏။')
,(378,3,1,'ဖိန်းနွှဲခါပြီးနောက်တစ်နေ့။ ယနေ့မှ၍ စတုတ္ထမြောက်ရက်။', NULL)
,(379,3,1,'၁။ သရဲဲတစ္ဆေ။ ဘီလူး။','ကလော်အပိၚ်သာတ် = မြေဘုတ်ဘီလူး။ || ကလော်အပၠေအ် = အစိမ်းသရဲ။')
,(379,3,1,'၂။ အစောင့်နတ်။ ကိုးကွယ်ရာရိုးရာနတ်။','ကလော်သ္ၚိ = အိမ်စောင့်နတ်။ || ကလော်ဍေၚ် = ပုသိမ်သားအနွယ်ဝင် မွန်လူမျိုးတို့ကိုးကွယ်ရာ ရိုးရာပန်းအိုဆွဲနတ်။ || ကလော်သတ်ဗြဴ = ပဲခူးသားအနွယ်ဝင် မွန်လူမျိုးတို့ကိုးကွယ်ရာ ရိုးရာအုန်းသီးနတ်။ || ကလော်ယာတ် = မုတ္တမသားအနွယ်ဝင် မွန်လူမျိုးတို့ကိုးကွယ်ရာ ရိုးရာအဝတ်အစားနတ်။')
,(379,3,1,'၃။ အလုပ်တစ်ခုခု­ အလွန်ကျွမ်းကျင်သူ။','ကလော်က = ငါးရှာကျွမ်းကျင်သူ။ || ကလော်ဍာ် = ရေကူးကျွမ်းကျင်သူ။ || ကလော်ကမ်ပျူတာ = ကွန်ပျူတာကျွမ်းကျင်သူ။')
,(380,3,1,'လိပ်ပြာ။ (ပိုးကောင်)', NULL)
,(381,3,4,'နတ်ဝင်သည်။ နတ်ပူးသည်။', NULL)
,(382,3,1,'လိပ်ပြာ။ (ပိုးကောင်)', NULL)
,(383,3,1,'နတ်အုန်းသီး။ (မင်းမဟာဂီရိနတ်ကို ရည်စူး၍ အိမ်းတွင်း­ ဆွဲသောအုန်းသီး။)', NULL)
,(384,3,4,'ထမင်းလုံးတစ္ဆေခြောက်သည်။', NULL)
,(385,3,4,'ရေတွင်နှစ်သည်။ တို့သည်။','“ဖျုန်ပရာၚ်ဂှ် ကလံက်စကဵုဍာ်ဗ္စးညိ။” = “အသားကင်ကို အချဉ်ရည်နှင့်တို့စားပါ။”')
,(386,3,4,'သားမယားပြုကျင့်သည်။ မုဒိမ်းကျင့်သည်။', NULL)
,(387,3,4,'ဟန်ဆောင်သည်။ ဟန်ပြုသည်။','ကလံက်ပချိုတ် = သေဟန်ဆောင်သည်။ သေဟန်ပြုသည်။ ‘ပကလော်’ လည်းရှု။ || “(တၞဟ်နရပ်စဗ္ၜေံဗြဴဂှ်) အဲကလံက်ပချိုတ်တုဲ အဲသ္တိက်ဒၟံၚ်ရ။” (ကၠဵုကၟက်ဂးကဵုကၠဵုဗြဴရ။) (၅၅ဝ။ ဇ—၄၃၇။ ဒု—၆၄ဝ။ အစွောံ။) = “(ဆိတ်မကို ဖမ်းစားရန်အလို့ငှာ) ငါသည် သေဟန်ပြု၍ အိပ်အံ့” (ဟုမြေခွေးဖိုသည် မြေခွေးမကိုပြော၏။) (၅၅ဝ။ တ—၅၆၅။ ညောင်ကန်။)')
,(388,3,4,'၁။ ခြောက်လှန့်သည်။ မောင်းထုတ်သည်။','“ကလိုက်ထောံခ္ဍာ်ညိ။” = “ကျီး ကန်းကို မောင်းထုတ်လိုက်ပါ။”')
,(388,3,4,'၂။ လှုပ်ရှားသည်။ ဗောင်ဗင်ခတ်သည်။','“ဍာ်ပ္ဍဲနုၚ်ဂှ် ဗှ်ေယဵု နၚ်ဂှ် ကလိုက်တိုန်ဒၟံၚ်ရောၚ်။” = “နၚ်ရွက်လာသော ရေအိုးထဲမှရေသည် ဗောင်ဗင်ခတ်နေသည်။”')
,(389,3,4,'ဆူပူထကြွသည်။ တုန်လှုပ်ချောက်ချားသည်။ မငြိမ်မသက်ဖြစ်သည်။', NULL)
,(390,3,4,'၁။ နားထောင်သည်။','ကလၚ်ဒွက် = သီချင်းနားထောင်သည်။ || ကလၚ်ဓဝ် = တရားနာသည်။')
,(390,3,4,'၂။ အတုံးဖြစ်အောင်ထွင်သည်။','“နကဵုဂၞေဟ်ဇာဒိသိုၚ်ဂှ် ကိတ်ကလၚ်ပ္တိတ်ဖျုန် ပြေၚ်ဂှ်တုဲ ကဵုကၠဵုဂှ်စရ။” (ဇ—၁၅၇။ အစွောံ။) = “ခြင်္သေ့သည် မိမိ၏အစွယ်တို့ဖြင့် ကျွဲအသားကို အတုံးဖြစ်အောင်ထွင်၍ မြေခွေးအားစားစေ၏။”')
,(391,3,1,'ဘက်တစ်ဖက်။ အမြှောင့်။ အလျားစောင်း။','“ဇၟာပ်တလၚ် ဍေံသ္ကေက်သ္ကာ လောန်နူအဲရ။” = “အဖက်ဖက်က သူငါ့ထက်ထူးချွန်ထက်မြက်တယ်။” || ပိကလၚ် = သုံးမြှောင့်။')
,(392,3,4,'နားထောင်သည်။','ကလၚ်ပၚ်မှိၚ်ဓဝ် = တရားနာသည်။')
,(393,3,4,'အမိန့်နာခံသည်။', NULL)
,(394,3,4,'စကားနာယူသည်။ စကားနားထောင်သည်။','“ကလၚ်အရေဝ်မိမညိ။” = “မိဘစကားကို နားထောင်နာယူပါ။”')
,(395,3,4,'လေထဲတွင်လွင့်သည်။ ပျံသည်။ စျာန်ဖြင့်ကောင်းကင်တွင်တည်သည်။','“ဂဂဵုဂတး ပန်ဒးစုတ်ဒြၚ်တၟအ်ဂှ်တုဲ ဂတှ်ေတၟအ်ကလှ်ေတိတ်တုဲ ကလာၚ်အာတုဲ ဒးစုတ်ဗ္ၜေအ်ဂှ်ရ။” = “မိုးကြိုးပစ်ရာ ကျောက်စွန်းကိုထိပြီး ထွက်လာသောကျောက်ပြားသည် လေထဲတွင်လွင့်ပြီး ဆိတ်အားထိမှန်သွား၏။” || “ဣသိတၠဇျှာန်ဂှ် ကလာၚ်ဒၟံၚ်ပ္ဍဲအကာသတုဲ တွံဓဝ်ကဵုမှာဇန်ဂမၠိုၚ်ရ။” = “စျာန်ရှင်ရသေ့သည် စျာန်ဖြင့်အာကာသတွင်တည်လျက် လူများကိုတရားဟော၏။”')
,(395,3,1,'ကင်မလင်းသီး။', NULL)
,(396,3,4,'လေဟုန်စီးသည်။ ခုန်ပျံကစားသည်။', NULL)
,(397,3,1,'၁။ ကျွဲရိုင်း။ ပြောင်။', NULL)
,(397,3,1,'၂။ ဆက်ရက်ငှက်။ သာရိကာငှက်။', NULL)
,(398,3,4,'ထင်မှတ်မှားသည်။ မမှတ်မိဖြစ်သည်။','“ကၠဵုဂှ် ဍေံကလိၚ်အာတၠဍေံတုဲ ဍေံကဳတၠ ဍေံရ။” = “ထိုခွေးသည် သူ့သခင်ကို သူမမှတ်မိသဖြင့် သခင်ကိုဟောင်၏။” ||  ကလိၚ်ကာလ = အချိန်မှားသည်။ || ကလိၚ်ဂၠံၚ် = လမ်းမှားသည်။ လမ်းမမှတ်မိဖြစ်သည်။ || ကလိၚ်မၞိဟ် = လူမှားသည်။ || ကလိၚ်ရုပ် = ရုပ်သဏ္ဍာန်ကို အမှတ်မှားသည်။ || ကလိၚ်ဒိုဟ်၊ ကလိၚ်ဒိုဟ်ကၠၚ် = အရပ်မျက်နှာကို မမှတ်မိဖြစ်သည်၊ အမှတ်မှားသည်။ || “ယွံပြဘာဝတဳ၊ ——၊ အဲဗ္ၜူဒၟံၚ်ရုပ်ဒေံ ဗြဴတုဲ ဒိုဟ်ကၠၚ်အဲကလိၚ်အာတုဲရ” (သၟိၚ်ကုသဂး။) (၅၅ဝ။ ဇ—၅၃၁။ ၉—၁၆၁။ အစွောံ။) = “အိုနှမပဘာဝတီ၊ ငါသည် နှမရုပ်ရည်­ မူးယစ်နေသည်ဖြစ်၍ အရပ်မျက်နှာကို မမှတ်မိလောက် အောင်ပင်ဖြစ်ခဲ့ပြီ။” || ‘တလိၚ်’ ရှု။')
,(399,3,4,'တစ်စုံတစ်ရာကို မမှတ်မိဖြစ်သည်။ ထင်မှတ်မှားသည်။', NULL)
,(400,3,4,'၁။ ပြန်သည်။ တစ်ဖန်ပြန်ပြုသည်။','ကလေၚ်စဴသ္ၚိ = အိမ်ပြန်သည်။ || ကလေၚ်ဟီု = ပြန်ပြောသည်။ || ကလေၚ်ကၠောန်တၟိ = အသစ်တစ်ဖန်ပြန်လုပ်သည်။ || ယဲကလေၚ် = ရောဂါပြန်ထသည်။')
,(400,3,4,'၂။ ပြန်ပေးသည်။ ပြန်ပို့သည်။','“အပေါတ်ဂှ် အဲဟွံဒှ်ကေတ်ရ။ ကလေၚ် ထောံကဵုတၠဍေံညိ။” = “ထိုပစ္စည်းကို ငါမယူဖြစ်တော့ပါ။ ပိုင်ရှင်ကို ပြန်ပေးလိုက်ပါ။”')
,(401,3,4,'လည်ပြန်လှည့်သည်။','“ကောန်စိၚ်ဗ္တာၚ်ဂှ် ကလေၚ်ကအ်တုဲ သ္ၚဳဳရံၚ် (ဓဇဲတအ်) သီုသ္ဍိုက်မၠိုက်တုဲ အာဂကောံသၟိၚ်ရ။” (ဇ—၁၅၆။ အစွောံ။) = “ဆင်ဖြူငယ်သည် လည်ပြန်လှည့်၍ လက်သမားတို့ကို ချစ်နှစ်သက်စွာကြည့်ပြီးလျှင် မင်းနှင့်အတူလိုက်သွား၏။”')
,(402,3,4,'ကျေးဇူးဆပ်သည်။ ကျေးဇူးတုံ့ပြန်သည်။', NULL)
,(403,3,4,'စိတ်ကိုချုပ်တည်းသည်။ စိတ်ကို မူလအခြေသို့ ပြန်ရောက်စေသည်။','“(ဂမှဳဂှ်) ညာတ်မာတုဂံါမွဲ မကျိုၚ်ကျဝ်လဝ် အလၚ်္ကာရဂှ်တုဲ စိုတ်စပ်အာတုဲ —— ညံၚ်ရဴဒြာဲမဒးကံကီု ကလေၚ်စိုတ်ဟွံမာန်တုဲ ဒတူတလှာဲရာဂဂှ်တုဲ ဇြေဟ်ဇြာဲဖျိုဟ်ဂတးတုဲ လတေၚ်ကြာန်ဓမာန်တဴရ။” (၅၅ဝ။ ဇ—၅၂၇။ ၉—၂၁/၂၂။ အစွောံ။) = “ထိုရဟန်းသည် တန်ဆာဆင်ထားသော မိန်းမတစ်ယောက်ကို မြင်လေလျှင် တပ်စွန်းသောစိတ်ရှိသည်ဖြစ်၍ ထိုမိန်းမသို့ ရောက်သောစိတ်ကို ပြန်လည်စိမ့်သောငှာ မတတ်နိုင်ရကား မြှားသင့်သောသမင်ကဲ့သို့ ရာဂအပူမီး နှိပ်စက်သည်ဖြစ်၍ ကြုံလှီဖြော့တော့သွားကာ အကြောပြိုင်းပြိုင်းထလျက်ရှိ၏။”')
,(404,3,4,'(ကျေးဇူးရှင်ကို) ပြန်၍ပြစ်မှားသည်။','“အဲပြာ်လဝ် (လမျီု) ဍေံတုဲ လၟုဟ်ဍေံ ကလေၚ်ဒြိုဟ်ကဵုအဲပၠန်ရောၚ်သွံ။” (၅၅ဝ။ ဇ—၄၈၂။ ၇—၂၁၄။ အစွောံ။) = “သူ့အသက်ကို ငါကယ်ထားပြီးနောက် ငါ့ကို ယခုသူပြစ်မှားပြန်ဘိသည်တကား။”')
,(405,3,4,'အကြောင်းပြန်သည်။ သတင်းစကားပြန်ကြားသည်။', NULL)
,(406,3,4,'(တောင်း၊ ဖျာ၊ နံရံစသည် ရက်ရာတွင်) အစပျိုးရက်သည်။', NULL)
,(407,3,4,'စကားတုံ့ပြန်သည်။ အကြောင်းပြန်သည်။', NULL)
,(408,3,4,'ဖုတက်သည်။ ဖူးရောင်သည်။','ကလံၚ်ဂုဟ် = ဖူးရောင်တက်သည်။ || ကလံၚ်တိုန် = ဖူးရောင်သည်။')
,(409,3,1,'၁။ ပြည်တောင်း။','သ္ၚုမွဲကလတ် = ဆန်တစ်ပြည်။')
,(409,3,1,'၂။ စင်ပြွမ်းသီး။', NULL)
,(410,3,4,'(အချောင်းအတံဖြင့်) ထိုးသွင်းကွာဟစေသည်။ ကော်သည်။ ကလန့်သည်။', NULL)
,(411,3,4,'၁။ ချောသည်။','“ဂၠံၚ်ဂှ် ကလိတ်ဒၟံၚ်ရောၚ်၊ စွံသတိတုဲကွာ်ညိ။”= “ထိုလမ်းသည် ချောနေသည်။ သတိထားပြီးလျှောက်ပါ။”')
,(411,3,4,'၂။ ချော်လဲသည်။','ကလိတ်စှ်ေ = ချော်လဲကျသည်။')
,(411,3,3,'၁။ ချောသော။ ချောကျိသော။', NULL)
,(411,3,3,'၂။ ကြော့မော့သော။ ကြွကြွရွရွ လှပတင့်တယ်သော။','“ဍေံဓယိကၠေၚ်တုဲ ဂြးလဝ်သော်ဍေံကလိတ်ဒၟံၚ်ရ။” = “သူသည် သူ့ဆံ ပင်ကို ဆီလိမ်းပြီးဖြီးထားသည်မှာ ကြွကြွရွရွရှိလှသည်။”')
,(412,3,4,'၁။ (အသားအရေ) စိုပြည်ချောမွေ့သည်။ ပြေပြစ်သည်။','“ကောန်သၟိၚ်သောတ္ထိသေဏဂှ် ဒှ်ယဲကုဋ္ဌပြင်ဏဳဂှ် နဓဝ်သစ္စဂၞကျာ်သမ္ဘူလာတုဲ ယဲဗၠးအာ တုဲ အရံၚ်သာ်ဇကု မဂွံကလိတ်ကလောတ်ဂေါဝ်ပၠန်ရ။” (နိဿဲ။ ၅၅ဝ။ ဇ—၅၁၉။ ၈—၂၅၃။ အစွောံ။) = “သောတ္ထိသေဏမင်းသားသည် နူနာရောဂါစွဲ၍ သမ္ဘူလမိဖုယား၏ သစ္စာတရားကြောင့် ရောဂါပျောက်ကင်း၍ အသားအရေ ပြန်လည်ချောမွေ့စိုပြည်လာရ၏။”')
,(412,3,4,'၂။ အဆင်ပြေသည်။ အဆင်ချောသည်။ အခက်အခဲမရှိဖြစ်သည်။ ဘေးအန္တရာယ်မရှိဖြစ်သည်။','“ကလောန် ကိစ္စဂှ် ကလိတ်ကလောတ်ဒၟံၚ်ဖအိုတ်ရဟာ။” = “ထိုအလုပ်ကိစ္စ အားလုံးအဆင်ချောပါရဲ့လား။” || “တရဴပိုဲမအာဂှ် ဟၟဲကဵုဘဲအန္တရာဲ ကလိတ်ကလောတ်တဴရ။” = “ငါတို့သွားသောခရီးသည် ဘေးအန္တရာယ်မရှိ ခရီးချောမွေ့ပါသည်။”')
,(413,3,4,'ချော်လဲကျသည်။','“လ္ပဒြေပ်၊ ဒြေပ်မ္ဂး ကလိတ်စှ်ေဏောၚ်။” = “မပြေးနှင့်၊ ပြေးလျှင် ချော်လဲကျလိမ့်မည်။”')
,(414,3,4,'ချွတ်ချော်သည်။ တိမ်းပါးသည်။ ယိမ်းယိုၚ်သည်။ (ပါဠိ—ခလတိ','ပက္ခလ)')
,(415,3,1,'ယက်ကန်းစင်ရှိ ရက်ပြီးအဝတ်ကို လိပ်သွင်းသည့် လက်လိပ်သစ်လုံး။', NULL)
,(416,3,1,'တမန်။ ကိစ္စတစ်ခုခုကိုဆောင်ရွက်ရန် စေလွှတ်ခြင်းခံရသူ။','“ပ္ဍဲကာလအဲဍိက် ထတ်စောံပါတေံဂှ် ဒဒှ်ကလုတ် တရဴဗၞတ်ကၠံယောဇနာဂှ် လိက်ကွးစုတ်ပ္ဍဲကအ်အဲတုဲ — အဲဍိက်မ ဒုၚ်ကာကလုတ်အဴ။ ——။” (စိၚ်ဗြဴဗျုဂး။) (ဇ—၄ဝ၉။ အစွောံ။) = “အကျွန်ုပ်ပျိုရွယ်သန်စွမ်း သောကာလ­ တမန်အဖြစ်ဖြင့် ယူဇနာတစ်ရာရှိသောခရီးကို အကျွန်ုပ်၏လည်­ စာခွေကိုဖွဲ့၍ — အကျွန်ုပ်သည် တမန်တို့၏အမှုကို ဆောင်ရွက်ပေး၏” ဟုဆင်အိုမဆို၏။ || “ကလုတ်တံဂှ် အာပတီပြောဟိတ်ပၠန်ရ။” (ဇ—၂၇၆။ အစွောံ။) = “တမန်တို့သည် ပုရောဟိတ်၏အထံသို့သွား၍ တောင်းကုန်၏။” (ညောင်ကန်)')
,(417,3,1,'မျိုးစေ့ဖောက်ရာတွင် ထွက်လာသောအပင်အတက်။ အညှောက်။','ၜဲကလုတ် = ပဲပင်ပေါက်။')
,(417,3,4,'အညှောက်ထွက်အောင် အပင်ဖေါက်သည်။ မျိုးစေ့ပျိုး၍ အပင်ဖောက်သည်။','“မလဵုဂှ် ကလုတ်လဝ်တုဲရဟာ။” = “ဗူးမျိုးစေ့ကို အပင်ဖောက်ထားပြီးပြီလား။”')
,(418,3,1,'အချစ်တမန်။ ချစ်သူနှစ်ဦးအကြား စေ့စပ်ပေးသောအောင်သွယ်။ အောင်သွယ်တော်။', NULL)
,(419,3,1,'တမန်။ သံတမန်။','“——၊ မရှာတ်ဗလးဏာကလုတ်တမာန် ဇရေၚ်ဒိုဟ်ပန်တုဲ ဂမှဳမၞုံကဵုဂုန် မၞုံကဵုသဳလတံဂှ် ဍေံတံနိမန်နၚ်—။” (ဇ—၄၉၈။ အစွောံ။) = “မြတ်သောမင်းကြီး၊ တရားစောင့်ကုန်သော ရဟန်းပုဏ္ဏားတို့အား ပင့်ဘိတ်တတ်ကုန်သော တမန်တို့ကို အရပ်လေးမျက်နှာတို့သို့ ဥဒဟိုသွားစေကုန်လော့။” (ညောင်ကန်)')
,(420,3,1,'စစ်သံမှူး။ စစ်ရေးဆိုင်ရာတမန်။', NULL)
,(421,3,1,'သေမင်းတမန်။','ဗောဓိသတ်(သၟိၚ်) ညာတ်သော်(ဗု)ဂှ်တုဲ “ကလုတ်သၟိၚ်ယီု ကၠုၚ်စိုပ်အဲတုဲရသွံ” ချပ်တုဲ—။ (ဇ—၅၂၅။ အစွောံ။) = ဆံဖြူကိုမြင်၍ ဘုရားလောင်းသုတ သောမမင်းသည် “သေမင်းတမန်သည် ငါ့ဆီကို လာခဲ့လေပြီ” ဟုကြံ၏။')
,(422,3,1,'လင်းဝက်။ ဝေသာလီဗျိုင်း။', NULL)
,(423,3,4,'၁။ သုတ်လိမ်းသည်။','ကလေတ်ဂြိၚ်ကဵုမုက် = မျက်နှာကို အိုးမဲသုတ်သည်။')
,(423,3,4,'၂။ စိပ်အောင်လုပ်သည်။ နီးကပ်အောင်လုပ်သည်။','“ဒၞးဂှ် ဒၞးလဝ်ဍေံသြိၚ်အာ ကလေတ်ပၠောပ် ဍေံညိ။” = “စည်းရိုးကာထားသည်မှာ ကျဲလွန်းသွားသည်၊ စိပ်အောင် ကပ်သွင်းလိုက်ပါ။” ‘ကၠေတ်’ (ကြိ) လည်းရှု။')
,(424,3,1,'ပလွေ၊ ပြွေ။', NULL)
,(425,3,1,'ချက်။ ချက်တိုင်။','‘ပေါၚ်တၠိုတ်')
,(425,3,1,'ချက်။ ချက်တိုင်။','ပံၚ်တၠိုတ်’ နှင့်အတူတူ။')
,(426,3,1,'ရှေးခေတ်က ရွာကိုအုပ်ချုပ်ရသော အကြီးအကဲအမတ်။', NULL)
,(427,3,1,'အကျိတ်အဖု။ အကျိတ်နာ။', NULL)
,(427,3,4,'အကျိတ်ရောင်သည်။','ယဲကလေန် = အကျိတ်ရောင်ရောဂါ။')
,(428,3,1,'အလုပ်။ အမှု။','“ဗောဓိသတ်ဒှ်ပ္ဍဲဂကူသဝ် နကလောန်သဝ်ဟေၚ် မဒ္ဂေတ်ဂယိုၚ် လမျီုရ။” (ဇ—၆၉။ အစွောံ။) = “ဘုရားလောင်းသည် အဆိပ်ကိုဖြေတတ်သော အမျိုး­ဖြစ်၍ ဆေးကုသောအမှုဖြင့် အသက်မွေး၏။” || ‘ကမၠောန်’ လည်းရှု။')
,(429,3,1,'လုပ်ငန်းကိုင်ငန်း။ အလုပ်အကိုင်။','“ယွံသဟာဲ၊ ပိုဲညးၜါဂှ် တမ်ဒြပ်ကီု ကွဳကီု ဂၠဴကီု သွံရာန်ကလောန်ကမေတ်ဂှ် တုပ်သၟဟ်ရောၚ်။” (ဇ—၉၈။ အစွောံ။) = “အဆွေ၊ ငါတို့နှစ်ဦးသည် ဥစ္စာအရင်းအနှီး၊ လှည်းနွား၊ အရောင်းအဝယ်အလုပ်အကိုင် တူညီကြကုန်၏။”')
,(430,3,1,'အလုပ်အကိုင်။ လုပ်ငန်းဆောင်တာ။','“သၟိၚ်ဂှ် ဒးဂၞပ်ကဵုဖျုန်ဒြာဲသန်။ မၞိဟ်ညးကွာန်တံညးဂမၠိုၚ်ဂှ် သ္ဒးဗက်ဒြာဲရိုဟ်ဟ်တ္ၚဲတုဲ ကလောန်ကေၚ်ကာ သၟိက်ကၠောန်စဟွံဂွံရ။” (ဇ—၁၂။ အစွောံ။) = “ထိုမင်းသည် သမင်သားကို အလွန်နှစ်သက်၏။ ရွာသားများသည် နေ့တိုင်းနေ့တိုင်း သမင်လိုက်နေကြရကုန်သဖြင့် မိမိတို့၏လုပ်ငန်းဆောင်တာကို လုပ်ကိုင်ခွင့်မရကြကုန်။”')
,(431,3,4,'အလုပ်များသည်။ အလုပ်ရှုပ်သည်။', NULL)
,(432,3,1,'လက်ရာ။','“ရုပ်ထဝ်ထမၞတ် သၟိၚ်ကုသသောန်လဝ် မဒှ်ကလောန်တဲသၟိၚ်ကုသဂှ် အ္စာဓမာတ်ဂှ်ညာတ်တုဲ သလှ်ေဂးဗြဴအဆေဝ်သွဝ်ရ။” (ဇ—၅၃၁။ အစွောံ။) = “ကုသမင်းသွန်း လုပ်ထားသော ကုသမင်း၏လက်ရာဖြစ်သော ရွှေစင်ရုပ်ကိုမြင်၍ ပန်းထိမ်ဆရာသည် နတ်သမီး ဟုထင်မှတ်၏။”')
,(433,3,4,'(ခြေ၊ လက်စသည်) ခေါက်သည်။ အဆစ်လွဲသည်။','“ဍေံလောတ်စှ်ေတုဲ တဲဍေံက လပ်အာရ။” = “သူလဲကျပြီး လက်အဆစ်လွဲသွားသည် (ဝါ) လက်ခေါက်သွားသည်။”')
,(434,3,1,'၁။ ကလာပ်စည်း။ သက်ရှိတို့၏ အခြေခံအကျဆုံး ရုပ်အဖွဲ့အစည်း။', NULL)
,(434,3,1,'၂။ ကလာပ်စည်း။ နိုင်ငံရေးအဖွဲ့အစည်းတစ်ခု၏ အခြေခံအဖွဲ့။', NULL)
,(435,3,1,'ရုပ်ကလာပ်။ အလောင်း။', NULL)
,(436,3,4,'(ရေ) ဖုံးလွှမ်းသည်။','“ဍာ်ကလိုပ်ဒၟံၚ်သီုကွာန်ရ။” = “တစ်ရွာလုံး ရေဖုံးလွှမ်းနေသည်။”')
,(437,3,4,'လျှာဖျားနှင့်လျက်သည်။','“ဍာ်သဂြာဂှ် ကလေမ်စမ်ရံၚ်ညိ။” = “သကြားရည်ကို လျက်စမ်းကြည့်ပါ။” || ကလေမ်စ = လျက်စားသည်။')
,(438,3,1,'ခေါင်အုပ်၊ အိမ်ခေါင်။','‘ကၠီု’ (ကြိ) လည်းရှု။')
,(439,3,1,'ခေါင်ယိုသည်။ (ဥပစာ) အကြီးအကဲလုပ်သူက မှားယွင်းစွာကျင့်ကြံပြုလုပ်သည်။', NULL)
,(440,3,1,'ရှစ်ရှားပင်။', NULL)
,(441,3,4,'၁။ ဖြေချသည်။ တွဲလျားချသည်။ ဖားလျားချသည်။','ကလာဲလဝ်သော် = ဆံပင်ကိုဖြေချသည်။ ဆံပင်ဖားလျားချသည်။ || ‘တလာဲ’ ရှု။')
,(441,3,4,'၂။ အပေါ်သို့ပန်းထွက်သည်။ အပေါ်သို့ ခုန်ပျံတက်သည်။','ဍာ်ကလာဲတိတ် နူအကြာတၟအ် = ကျောက်ကြားမှ စီးထွက်လာသောရေ။')
,(441,3,4,'၃။ ထကြွသည်။','“(ဗောဓိသတ်ဣသိ ညာတ်လပံက်လမာဲဂၞကျာ်တုဲ ကိလေသပါတ်တိုန်) ဟိုတ်နူဂမ္တဴကိလေသကလာဲတိုန်တုဲ သ္ၚဳဣန်ရဳယာပိုတ်ဟွံမာန်ရ။” (ဇ—၂၅၁။ အစွောံ။) = “ဘုရားလောင်းရသေ့သည် မိဖုယား၏ဖုံးကွယ်အပ်သောအင်္ဂါကိုမြင်၍ ကိလေသာကြီးထွားလာ၏။ ကိလေသာတည်းဟူသော ပူပန်ခြင်းသည် ထကြွတိုးတက်လာသဖြင့် ဣန္ဒြေကိုမဆောင်နိုင်ဘဲရှိ၏။”')
,(442,3,1,'ဆီးဖြူသီး။', NULL)
,(443,3,4,'ရေထဲတွင်ပေါလောပေါ်အောင် ကိုယ်ကိုဖော့ထားသည်။', NULL)
,(444,3,1,'မယား။ ဇနီး။ အိမ်ရှင်မ။ ကတော်။', NULL)
,(445,3,4,'သုတ်လိမ်းသည်။', NULL)
,(446,3,4,'အစာငတ်စေသည်။ အငတ်ထားသည်။','“ကောန်ၚာ်ဟီုဝါတ်ဂှ် ကလောဝ်လဝ်စၞ မွဲဗဂါပ်ညိ။” = “ပြောဆိုရခက်သောကလေးကို အစာတစ်နပ် အငတ်ထားလိုက်ပါ။” || ‘ကၠောဝ်’ (ကြိ) လည်းရှု။')
,(447,3,4,'အရိုအသေပြုသည်။ ဦးညွတ်သည်။ အလေးပြုသည်။','ထံက်ကလဵု = ဒူးထောက်သည်။ ပုဆစ်ဒူးတုပ်ထိုင်သည်။')
,(448,3,1,'၁။ ပိုးစုံးကြူး။ ပိုးစိမ်းဖြူ။','“ညံၚ်ရဴကလဵုလိၚ် မအာပ်လျးတ္ၚဲကီု။” (ဇ—၂၈၅။ အစွောံ။) = “နေမင်း၏အလင်းရောၚ်ကို မယှဉ်နိုင်ဘဲရှုံးသော ပိုးစုံးကြူးကဲ့သို့။” || ‘လလိၚ်’ ဟုလည်းရေးသည်။')
,(448,3,1,'၂။ နားထင်ရိုးတွင် ရုတ်တရက်တိုက်ခိုက်မိသောအခါ မျက်စိမှ မီးပွင့်သကဲ့သို့ ထွက်လာသောအလင်းရောင်။', NULL)
,(449,3,4,'ထိခိုက်မှုကြောင့် မျက်စိမှ မီးပွင့်သကဲ့သို့ ခံစားရသည်။', NULL)
,(450,3,4,'ပြုတ်ထွက်သည်။ ကျွတ်ထွက်သည်။','“ဇိုၚ်ခုၚ်မွဲတၞုၚ် ကလှ်တိတ်အာရ။” = “ခုံခြေတစ်ချောင်း ပြုတ်ထွက်သွားသည်။” || “(ဗမၞးမုဟ်ပိုတ်ဂှ်) တိုန်သဳကၠဳ (သၟိၚ်) ဂှ် ဒးဒၟံၚ်ဒစး ပသာန်တ္ၚဲဂှ်တုဲ ကြေက်မဖျပ်ပ္တုပ်လဝ်မုဟ်ဂှ် တလှ်ဒတုံစှ်ေအာရ။” (ဇ—၁၂၆။ အစွောံ။) = “နှာခေါင်းပြတ်သောပုဏ္ဏားသည် မင်းအားခစားစဉ် ထိုးသောနေအပူရှိန်ကြောင့် ချိပ်ဖြင့်လုပ်ထားသော နှာခေါင်းတုသည် ကျွတ်၍ပြုတ်ကျသွား၏။”')
,(451,3,4,'၁။ ပျက်စီးသည်။ ဆုံးပါးသည်။ ဖျက်ဆီးသည်။','“ယြဴသၟိၚ် မွဲ ဟွံမွဲကဵုဗဗွဲဓဝ်တုဲ —— ပိုန်ယဿပတ်သၟိၚ်အိုဿီု မဒးကလှ်လဖှ်လီုလာ်အာအိုတ်ဟေၚ်ရ။” (ဇ— ၃၉၆။ အစွောံ။) = “တရားမစောင့်သောမင်းသည် အလုံးစုံသော စည်းစိမ်အကျော်အစော ပျက် စီးဆုံးပါးရလိမ့်မည်။” || “ယွံခမဳ၊ ကိလေသမ္ဂးဝွံ ဍေံကလှ်လဖှ်ကၠေံဂုန်ညးရောၚ်။” (ဇ—၄၃၁။ အစွောံ။) = “ရဟန်း၊ ကိလေသာမည်သည်ကား ဂုဏ်ကျေးဇူးကို ဖျက်ဆီးတတ်၏။”')
,(451,3,4,'၂။ ပယ် သည်။ ပယ်ဖျက်သည်။ ပယ်စွန့်သည်။ ပယ်ဖျောက်သည်။ ပယ်သတ်သည်။','“(ကောန်ဗြဴမာပိ မကၠုၚ်လှေအ်လှန်ကျာ်တြဲဂှ်) ကျာ်တြဲကလှ်လဖှ်ကၠေံ ကောန်ဗြဴမာပိဂှ်ရ။” (ဇ—၁၃၂။ အစွောံ။) = “ဖြားယောင်းရန်လာကုန်သော မာရ်နတ်သမီးသုံးယောက်တို့ကို မြတ်စွာဘုရားသည် ပယ်တော်မူ၏။” || “ယွံခမဳတံ၊ — ဓဝ်လောဘပ္ဍဲသန္ထာန်ဂှ် သ္ဇိုၚ်ကလှ်ဒပှ်ကၠေံမာန်သန်ဟေၚ်။” (ဇ— ၇ဝ။ အစွောံ။) = “ရဟန်းတို့၊ အတွင်းသန္ထာန်မှ လောဘတရားကို ပယ်ဖျောက်နိုင်ခဲလှ၏။” || “ဓုတၚ်မ္ဂးဂှ် ဒ္ဂေတ်မကလှ်လဖှ်ကၠေံကိလေသရ။” = “ဓုတၚ်မည်သည် ကိလေသာကို ပယ်သတ် နိုင်သောအကျင့်ဖြစ်သည်။”')
,(451,3,4,'၃။ (အမြတ်မှအယုတ်သို့၄င်း၊ အကောင်းမှအဆိုးသို့၄င်း) ရွေ့လျှောသည်။','“ယွံသၟိၚ်မပြဲ၊ မဟီုဂလာန်မုသာဂှ် မဒးကလှ်လဖှ်အာ နူဋ္ဌာန်ဇကုရောၚ်။ ——၊ ဒေဝတဴသ္ဍးအာ ဟွံမၚ်မွဲဇကုရ။ ဟီုမုသာတုဲ ပါၚ်မသ္အုဲပ္ဍးအာရ။” (ဇ—၄၂၂။ အစွောံ။) = “မြတ်သောမင်းကြီး၊ မုသားကိုဆိုခြင်းဖြင့် မိမိ၏မင်းအဖြစ်မှ ရွေ့လျှောရလတ္တံ့။ မိမိအားနတ်မစောင့် စွန့်ခွာကုန်လတ္တံ့။ မုသားဆိုခြင်းဖြင့် ပါးစပ်နံစော်ပုပ်ဟောၚ်သွားလတ္တံ့။”')
,(451,3,4,'၄။ (စိတ်) ပျံ့လွင့်သည်။ မတည်မငြိမ်ဖြစ်သည်။','စိုတ်ကလှ်လဖှ် = စိတ်ပျံ့လွင့်သည်။')
,(452,3,4,'၁။ တံတောင်နှင့်တွက်သည်။', NULL)
,(452,3,4,'၂။ ပဲ့ထွက်သည်။ ဖဲ့ထုတ်သည်။','“အဲကၠဟ်ဏာမြဂှ် ဒးစုတ်ဆုဂှ်တုဲ ကဝေက်ဆုမွဲ ကလှ်ေတိတ်အာရ။” = “ဓါးမကို ငါပစ်လွှတ်လိုက်ရာ ထိုသစ်ကိုထိမှန်သွားပြီး သစ်စတစ်စပဲ့ထွက်သွားသည်။” || “ကၠောန်ကၠိက်ဂှ်တုဲ ကလှ်ေပ္တိတ် ကဵုအဲ ဖျုန်မွဲကလောအ်ညိ။” = “ထိုဝက်ကိုပေါ်ပြီးလျှင် အသားတစ်တုံး ငါ့ကို ဖဲ့ထုတ်ပေးပါ။”')
,(453,3,4,'၁။ သိစေသည်။ ရှင်းပြသည်။','“ညံၚ်ညးဂွံကၠိုဟ် ဒးကလိုဟ်ထ္ၜးရ။” = “သူရှင်းလင်းသဘောပေါက်အောင် ရှင်းပြရမည်။”')
,(453,3,4,'၂။ အသိပေးသည်။ ကြားသိစေသည်။ ပြောပြသည်။','“ဟိုတ်နူဗမၞိဟ်ဗြဴတုဲ ဗမၞးဒးဂွအာဒေါဝ်ပုရိသာတ်တုဲ ဗမၞးထေဲသလံၚ်စဴအာရ၊ ဒဒှ်ဂှ် ညးအာဟီုကလောဟ်ကဵုဗမၞိဟ်ဗြဴရ။” = “ပုဏ္ဏေးမကြောင့် ပုဏ္ဏားသည် ပရိသတ်အလယ်­ အရှက်ရသွားသဖြင့် အမျက်ဒေါသမီးတောက်လောင်လျက် ပုဏ္ဏားပြန်သွား၏၊ ထိုအကြောင်းကို သူ တပါးတို့သည် ပုဏ္ဏေးမအား သွားရောက်ပြောပြ၏။”')
,(454,3,4,'၁။ ဖြုတ်သည်။','“ဒဒန်ဂှ် ကလိုဟ်လဝ်ဂှ်ရ ကၠောံဟွံဂွံရ။” = “တံ တားကိုဖြုတ်ထားသောကြောင့် ကူး၍မရတော့ပါ။” || ကလိုဟ်လဝ်ကွဳ = လှည်းဖြုတ်ထားသည်။ (နွားကိုမတပ်ဆင်ထား)')
,(454,3,4,'၂။ ပေါက်အောင်ဖောက်သည်။ ထွင်းသည်။','“ဗဒၚ်ဆုဂှ် ကလိုဟ်လဝ် ရ။” = “သစ်သားနံရံကို ဖောက်ထားသည်။” || “(ဆုဓုပ်ပြကာဂှ်) ကလိုဟ်ကၠေံကြုတ်ဍေံတုဲ ဒ ကှ်လဝ်။” (ဇ—၃၁။ အစွောံ။) = “ထုပိကာသစ်ကိုထွင်း၍ ခြောက်စေသည်။” ‘ကၠိုဟ်’ (ကြိ) လည်းရှု။')
,(454,3,4,'၃။ မျက်စိမှိတ်ကျသည်။','“သၟိၚ်အဇာတသတြု မတ်တလိုဟ်စှ်ေဗက် နိမိတ်နရက်တံဂှ် ကၠုၚ်ပြာကတ်တုဲ တိက်လှိၚ်ဟွံသိုက်သက်က်ရ။” = “အဇာတသတ်မင်းသည် မျက်စိမှိတ်ကျသွားသည်နှင့် တစ်ပြိုင်နက် ငရဲနိမိတ်များ ထင်ရှားလာသဖြင့် ချမ်းသာစွာ လုံးဝမအိပ်စက်ရပါ။”')
,(454,3,4,'၄။ (သေနတ်) မောင်းပြုတ်သည်။','“သေနာတ်တလိုဟ်အာ ဒးစုတ်ဍေံရ။” = “သေနတ်မောင်းပြုတ်၍ သူ့အားထိမှန်သွားသည်။”')
,(455,3,4,'၁။ နားပေါက်ဖောက်သည်။ နားသသည်။', NULL)
,(455,3,4,'၂။ ကြားသိစေသည်။ အသိပေးသည်။ ပြောပြသည်။', NULL)
,(456,3,4,'(နွားစသည်) နဖားဖောက်သည်။ နဖားထိုးသည်။', NULL)
,(457,3,4,'ရှိခိုးသည်။ ကန်တော့သည်။','ကလအ်မိမ = မိဘကိုကန်တော့သည်။')
,(458,3,1,'နန်းလုံးကြိုင်ပင်။', NULL)
,(459,3,4,'ပူဇော်ကန်တော့သည်။ ရှိခိုးပူဇော်သည်။','ကလအ်ဗဇဴမိမ = မိဘကို ပူဇော်ကန်တော့သည်။')
,(460,3,4,'ဖျောက်ပစ်သည်။ ဖြေဖျောက်သည်။ ပျောက်စေသည်။','“ဂၠေံကေတ်ဏာဒြပ်ညး တုဲ လ္ပကလေအ်စထောံညိ။” = “သူတစ်ပါးပစ္စည်းကို ငှားယူသွားပြီး မဖျောက်ပစ်လိုက်ပါနှင့်။” || “(ဣသိဍောတ်ဂှ်) ‘ဗြဴကလော်ကွေံရောၚ်’ ချပ်တုဲ ဖေက်တိုန်တုဲ ကလေၚ်ကလေအ်ထောံစိုတ် မထၞေန်စေန်စပ်မံၚ်ကဵုဗြဴဂှ်(ရ။)” (၅၅ဝ။ ဇ—၅၂၆။ ၉—၁၉။ အစွောံ။) = “ထိုရသေ့ငယ်သည် ‘ဘီလူးမအမှန်ဖြစ်လိမ့်မည်’ ဟုတွေး၍ ကြောက်လာသဖြင့် ထိုမိန်းမိ­ တပ်စွန်းတွယ်တာနေ သောစိတ်ကို ပြန်လည်ဖြေဖျောက်လိုက်၏။” || ‘ကၠေံ’ (ကြိ) လည်းရှု။')
,(461,3,4,'၁။ (လျှာ)ထုတ်သည်။','‘တလေအ်’ ဟုလည်းရေးသည်။ || တလေအ်လတာ် = လျှာထုတ်သည်။')
,(461,3,4,'၂။ (ဓါး၊ ကတ်ကြေးစသည်ကို) ထက်အောင် ၚရုတ်ဆုံစသည်တွင် ဘယ်ပြန် ညာပြန်ခတ်သည်။ ကျင်းသည်။ ထက်အောင်ပြုသည်။', NULL)
,(461,3,4,'၃။ (ချိန်ခွင်) တစ်ဖက်လေးသည်။ တစ်ဖက်အလေးချိန်စီးသည်။','‘တလေအ်’ ဟုလည်းရေးသည်။ “ကေဝ်ထဝ်မ္ဂး ဒးကေဝ်ဓဝ်ဓဝ်ရောၚ်။ လတာ်သၠဒကေဝ် တလေအ်ဒၟံၚ်မွဲလ္ပာ်ဟွံဂွံရ။” = “ရွှေချိန်လျှင် တည့်တည့်မတ်မတ်ချိန်ရပါမည်။ ချိန်ခွၚ်လျှာ တစ်ဖက်စောင်း၍မရပါ။”')
,(461,3,4,'၄။ ဖျောက်သည်။ ပျောက်ကွယ်စေသည်။','“ကလော်ဗြဴဂှ် ကလေအ်ထောံကၠေံ ကောန်ဍေံပၠန်ရ။” (ဇ—၉၆။ အစွောံ။) = “ထိုဘီလူးမသည် မိမိသားကို ဖျောက်ပစ်လိုက်ပြန်၏။” || ‘ကၠေအ်/ကၠေံ’ (ကြိ) လည်းရှု။')
,(462,3,4,'၁။ ကိုယ်ယောင်ဖျောက်သည်။ ရုပ်သွင်ကို တန်ခိုးဖြင့် ကွယ်ပျောက်စေသည်။','“ကလော်ကလေအ်လဝ်ဇကု မၞိဟ်တအ်ဟွံဂွံညာတ်ဍေံရ။” = “ဘီလူးကိုယ်ယောင်ဖျောက်ထား၍ လူများမမြင်ရပါ။”')
,(462,3,4,'၂။ ကိုယ်ယောင်ဖျောက်သည်။ ပုန်းကွယ်နေသည်။','“အဲဟွံဆဵုဍေံတၟာလအ်ရ။ မူဒှ်ဍေံဂွံကလေအ်လဝ်ဇကုရော အဲဟွံတီရ။” = “သူ့ကို ငါမတွေ့တာကြာပြီ။ ဘာဖြစ်လို့များ သူကိုယ်ယောင်ဖျောက်ထားမှန်း ငါမသိပါ။”')
,(463,3,4,'ရှာမတွေ့အောင် ရှောင်နေသည်။ ခြေရာဖျောက်သည်။', NULL)
,(464,3,4,'တစ်ဖက်ကမ်းသို့ ပို့ဆောင်သည်။','“ညးကလောအ်ကဵုပိုဲ သြၚ်လ္ပာ်တေံရ။” = “ကျွန်တော်တို့ကို တစ်ဖက်ကမ်းသို့ သူပို့ဆောင်ပေးသည်။” || “ယဝ်ရမိက် ကၠောံဂှ် အဲကလောံကဵုရ” ကျာံဂးကဵုကၞုဲ။ (ဇ—၂ဝ၈။ အစွောံ။) = “(ဟိုမှာဘက်ကမ်းသို့) သင်ကူးလိုပါက ငါပို့ဆောင်ပေးပါမည်။” || ‘ကၠောအ်’ (ကြိ) လည်းရှု။')
,(465,3,1,'အတုံး။','ကလောအ်တၟအ်၊ တၟအ်ကလောအ် = ကျောက်တုံး။ || ကလောအ်ထဝ် = ရွှေတုံး။')
,(465,3,4,'၁။ ခဲသည်။ အတုံးဖြစ်စေသည်။','“ဍာ်ဂံက်လောန်အာမ္ဂး ဍေံကလောအ်အာရောၚ်။” = “ရေသည် အေးလွန်လျှင် ခဲသွားလိမ့်မည်။”')
,(465,3,4,'၂။ အတုံးဖြစ်အောင် ပိုင်းဖြတ်သည်။ တုံးသည်။','“ဖျုန်ကၠိက်ဂှ် ဒန်ကလောအ်ထောံ တၟာတၟာၝောအ်တဲညိ။” = “ထိုဝက်သားကို လက်မအရွယ်ဖြစ်အောင် ခုတ်တုံးလိုက်ပါ။”')
,(465,3,9,'အတုံးကိုရေတွက်ရာတွင် သုံးသောစကားလုံး။','ဖျုန်ပိကလောအ် = အသားသုံးတုံး။')
,(466,3,1,'အဖုအပိမ့်နာ။ အနာစိမ်း။', NULL)
,(467,3,1,'ကြက်ဥရန်ဝပ်ရန်နေရာ။ ကြက်တင်း။', NULL)
,(468,3,1,'ခါချဉ်အုံ။ ခါချဉ်အိမ်။', NULL)
,(469,3,10,'(န) ကောင်းခြင်းငါးပါးနှင့် ပြည့်စုံသောအမျိုးသမီး။', NULL)
,(470,3,10,'(န) ရှုချင်စဖွယ်ရှိသော ကောင်းခြင်းလက္ခဏာ။', NULL)
,(471,3,11,'(န) ကလျဏပုထုဇဉ်။ ကောင်းမြတ်သောပုထုဇဉ်။', NULL)
,(472,3,11,'(န) ကလျာဏမိတ္တ။ မိတ်ဆွေကောင်း။','“ယွံနာဲပိုဲတံ၊ သၟိၚ်အဇာတသ တြုဝွံဂှ် ဂွံကလအ်ကၠေံကျာ်ဓဝ်သၚ်တုဲ ဂွံဟုဲဟာဲကလျာနိမိတ်တုဲ လၟုဟ်ဂွံလဟိၚ်စိုတ်ရ။”(ဇ—၅၃ဝ။ အစွောံ။) = “ငါ့ရှင်တို့၊ အဇာတသတ်မင်းသည် ဘုရားတရားသံဃာတို့ကို ကန်တော့ရ၍ က လျာဏမိတ္တနှင့် ပေါင်းဖော်ရခြင်းကြောင့် ယခုစိတ်၏ချမ်းသာခြင်းကိုရပြီ။” || ‘ကညာနိမိတ်’ နှင့် အတူတူ။')
,(473,3,1,'သေတ္တာ။ ဗူး။', NULL)
,(474,3,4,'ချိုင့်ခွက်ဖြစ်သည်။','“ဂအာၚ်တိဂှ် ကလှံက်ဒၟံၚ်ညိရောၚ်။” = “ထိုမြေကွက်သည် အနည်းငယ်ချိုင့်နေသည်။” || “ကလှံက်ဂှ် ဗဝ်ဗပေၚ်ထောံတိ ညိ။” = “ထိုချိုင့်ခွက်ကို မြေပုံဖြည့်ထည့်လိုက်ပါ။”')
,(475,3,4,'ချိုင့်ခွက်ဖြစ်သည်။', NULL)
,(475,3,1,'ချိုင့်။ ချိုင့်ခွက်။','‘ကလှံက်’ နှင့် အတူတူ။')
,(476,3,4,'ယုတ်လျော့သည်။ လျော့နည်းသည်။','“ၜိုန်သေဋ္ဌဳကဵုဒါန် ဗွဲမဂၠိုၚ်ကီုလေဝ် ဟိုတ်အနုဘဴဒါန်ကုသဵုတုဲ ဒြပ်ပ္ဍဲတိုက်ဒြပ်သေဋ္ဌဳဂှ် ဟွံကလှံက်ယုတ်အာသက်က်ရ။” = “ထိုသူဌေးသည် များစွာအလှူဒါနပြုသော်လည်း အလှူဒါန၏အာနုဘော်ကြောင့် သူဌေး၏ ဥစ္စာတိုက်­ ဥစ္စာတို့သည် လုံးဝမယုတ်လျော့သွားပေ။”')
,(477,3,4,'ထွင်းဖောက်သည်။ ထိုးဖောက်သည်။ စူးဝင်သည်။','“မၚ်ဗၠာဲဗလး ဏာကံဂျိဂှ် ဒးနူကၟံၚ် လုပ်ကလှၚ်ကၠေံဂြိုဟ်ဍေံတုဲ ကၠိုဟ်သာတ်တိတ်အာ လပါ်ဗတတေံတုဲ စိၚ်ဂှ် လောတ်ဒၟံၚ်ဒၞာဲဂှ်ရ။” (ဇ—၃၇၄။ အစွောံ။) = “လုလင်သည် ဆိပ်လူးမြှားဖြင့် ပစ်လွှတ်လိုက်ရာ ဆင်ဦးကင်းမှထိမှန်၍ အသည်းကို ဖောက်ထွင်းစူးဝင်၍ အမြီးဘက်သို့ ပေါက်ထွက်သွားပြီးလျှင် ထိုဆင်သည် ထိုနေရာ­လျှင် လဲသွား၏။” || “သၟိၚ်ပဥ္စာလဝွံဂှ် ပ္ဍဲဋ္ဌာန်စၞေဟ်ဂှ် ညံၚ်ဇလမစတ်ခ လှၚ်ဇိုၚ်အဲဂှ် ကဵုကံခလှၚ်ကၠေံတုဲ ကဵုလောတ်လောတမဝ်ဒၟံၚ် ညံၚ်အဲမဒးဇလဝွံညိရ” လထဴချဴ။ (ဇ—၅၂ဝ။ အစွောံ။) = “ပဥ္စာလမင်းသည် စစ်မြေပြင်­ ငါ့ခြေကိုဆူးစူးသကဲ့သို့ မြှားစူးစေ၍ မြေ­လူးလဲကျပါစေသား” ဟု အဘိုးအိုကျိန်ဆဲ၏။')
,(478,3,4,'မခံမရပ်နိုင်ဖွယ်ပြောသည်။ နားမခံသာအောင်ပြောသည်။ မှိုချိုး မျှစ်ချိုးပြောသည်။','“ဒုၚ်နၚ်သၟတ်ဗြဴတုဲ ဇကုဒှ်တၠသ္ၚိရဂးတုဲ ပညံၚ်ရဴဍိက်ကီု ဟီုကလှၚ်တဴက တောဝ်မတ်ရ။ (ဇ—၂၁၉။ အစွောံ။) = “သတို့သမီးကို ခေါ်ဆောင်လာပြီးလျှင် ငါသည် အိမ် ရှင်လင်ယောကျာ်းဖြစ်ပြီဟေ့ဆိုကာ ကျေးကျွန်သဖွယ်ပြု၍ နားမခံသာအောင် ပြောဆိုဆက်ဆံ၏။”')
,(479,3,1,'ကွင်း။ ကွင်းပြင်။','ကလှာတ်ဝါ = လယ်ကွင်းပြင်။ ကလှာတ်က္ၜၚ်ကျာ = လေယာဉ်ကွင်း။')
,(479,3,3,'ပြောင်တလင်းဖြစ်သော။ ပြောင်ရှင်းသော။','“ပ္ဍဲဂအာၚ်တိဂှ် တၞံဆု ဟွံမွဲ ကလှာတ်ဒၟံၚ်ရ။” = “ထိုမြေကွက်­ သစ်ပင်မရှိ ပြောင်ရှင်းနေသည်။”')
,(480,3,1,'‘ခလှာတ်က္ဍိုပ်’ ရှု။', NULL)
,(481,3,4,'‘ခလှောတ်’ ရှု။', NULL)
,(482,3,4,'ပြောင်စပ်စပ် ပြက်ချော်ချော် ပြုမူပြောဆိုသည်။','“ၚာ်တြုံဂှ် ခလိန်/ကလှိန်ကွေံရ။” = “ထိုသူငယ်သည် ပြောင်စပ်စပ် ပြက်ချော်ချော် ပြုမူပြောဆိုတတ်သည်။”')
,(483,3,4,'ကျီစယ်သည်။ နောက်ပြောင်သည်။','“ဍေံတံသၟိက်ကလှိန်ဗၟက် ဝေၚ်တုဲ ဍေံတံဟီုဝေၚ်ရောၚ်။ ဂလာန်ဍေံတံဟီုဂှ် တၠအဲလ္ပပပၞတ်ညိ။ လ္ပကေတ်ဆောညိ။” (ဇ— ၂၆၁။ အစွောံ။) = “သူတို့သည် နောက်ပြောၚ်ကျီစယ်လို၍ ပြောဆိုခြင်းဖြစ်၏။ သူတို့ပြော သောစကားကို သင်သည် အမျက်မထွက်ပါနှင့်၊ ဗွေမယူပါနှင့်။” || “(သၟတ်တြုံဂှ်) သၟိက်ကလှိန်ဗ မက်ဝေၚ်ဂှ်ဒှ်တုဲ ရပ်တဲသၟတ်ဗြဴဂှ်ရ။” (ဇ—၂၆၆။ အစွောံ။) = “ထိုသူငယ်သည် ကျီစယ်လိုသည် ဖြစ်၍ ထိုသူငယ်မ၏လက်ကို ကိုင်၏။”')
,(484,3,1,'ကတော်။ အိမ်ရှင်မ။','‘ကလဝ်’ ရှု။')
,(485,3,1,'၁။ ထောက်။ ကျားကန်။ (အိမ်အစိတ်အပိုင်း)', NULL)
,(485,3,1,'၂။ လင်းနို့။','ကဝစာၚ် = လင်းဆွဲ။ || ကဝကၞိ = လင်းနို့အငယ်စား။')
,(486,3,4,'(ကျွဲ၊ နွား၊ ဆိတ်၊ မြင်းစသည်ကို) ကြိုးရှည်ဖြင့်ချည်ကာ စားကျက်တွင် စားစေသည်။ လံထားသည်။', NULL)
,(487,3,1,'၁။ ကဗျာလၚ်္ကာဆရာ။ စာဆိုတော်။', NULL)
,(487,3,1,'၂။ ပညာရှိ။', NULL)
,(488,3,1,'ဝမ်းတွင်းအပူအပုပ်။','စၞကဝု = အပူအပုပ်အစာ။ ကဝုစှ်ေ = အပူအပုပ်ဆင်းသည်။ အပုပ်ကျသည်။ ‘ဖျေံကဝု’ (ကြိ) လည်းရှု။')
,(489,3,4,'လှည့်သည်။ လိမ်သည်။','“ကွးဘာတက္ကသဵု ကဝဲချာလေဝ်ဟွံလေပ်သွံ။” = “တက္ကသိုလ်ကျောင်းသားသည် နှီးကိုတောင် မချည်တတ်ပါလား။” || “ဒေံအဲ ဒးဒုၚ်ကဝဲကတောဝ်ရ။” = “ကျွန်တော်၏ညီသည် နားရွက်ဆွဲလိမ်ခံရသည်။”')
,(490,3,4,'သော့ခတ်သည်။ သော့ပိတ်သည်။', NULL)
,(491,3,1,'ဥသြငှက်။', NULL)
,(492,3,4,'ခွေသည်။ ရစ်သည်။ ထုံးသည်။','“ဇုက်ဂှ် ကဝးစွံလဝ်ညိ။” = “ကြိုးကို ခွေပြီးထားပါ။” || “(သၟိၚ်နာ်ဂှ်) ကဝးဗိုၚ်လဝ်ရသိတုဲ လတူကၞိပ်ရသိဂှ် ယိုက်လဝ်ဒၞံက်မဇၞော်တုဲ—။” (ဇ— ၂၅၃။ အစွောံ။) = “နဂါးမင်းသည် ရသေ့ကို ရစ်ခွေပတ်၍ ရသေ့ဦးခေါင်းပေါ်­ ပါးပျဉ်းကို ဆောင်း၍—။”')
,(492,3,1,'အခွေ။ အရစ်။ အထုံး။','ကဝးဇုက်သတ်ဗြဴ = အုန်းဆံကြိုးအခွေ။')
,(492,3,9,'အခွေ၊ အထုံးစသည်ကို ရေတွက်ရာတွင် သုံးသောစကားလုံး။','ဇုက်ၜါကဝး = ကြိုးနှစ်ခွေ။ ကြိုးနှစ်ထုံး။')
,(493,3,4,'ကွေးကောက်ရစ်ခွေသည်။', NULL)
,(494,3,1,'အူအခွေ။', NULL)
,(495,3,1,'ပန်းကုံး။ ပန်းခွေ။','ကဝးပ္ကဴလၞီလၞာ် = လွမ်းသူ့ပန်းခွေ။')
,(496,3,1,'တစ်ဝက်။ ထက်ဝက်။ ခွဲ။','စှ်နာဍဳကဝက် = ဆယ်နာရီခွဲ။')
,(496,3,4,'မမီဘဲ နောက်ကျကျန်ရစ်သည်။','“ညးၚုဟ်လဇုဲအာတုဲ ကဝက်အာ ဟွံဂတာပ်ကွဳပၟတ်ရ။” = “သူအိပ်ရာထ နောက်ကျသွားသဖြင့် မီးရထားမမှီပဲ နောက်ကျကျန်ရစ်ခဲ့သည်။”')
,(497,3,1,'တစ်ဝက်တစ်ပျက်။ တစ်ပိုင်းတစ်စ။','“ယာဲဂှ် အဃောကောန်ၚာ်လှိၚ် ကၠောန်ဂွံ လဝ်ကလောန် ကဝက်ကဝုဲတုဲ ကောန်ၚာ်ၚုဟ်အာ ဒးဒိုအ်လဝ်ကလောန်ဂှ်ရ။” = “မိခင်သည် ကလေးအိပ်ပျော်နေစဉ် အလုပ်ကိုတစ်ဝက်တစ်ပျက်လုပ်ထားပြီး ကလေးနိုးသွားသဖြင့် ထိုအ လုပ်ကို ရပ်နားထားရသည်။”')
,(498,3,1,'တစ်ဝက်စျေး။ ထက်ဝက်စျေး။','“နာဍဳအဲဂှ် အဲကလေၚ်သွံထောံ ကဝက်ၚုဟ်ရ။” = “ငါ့နာရီကို တစ်ဝက်စျေးနှင့် ငါပြန်ရောင်းလိုက်တယ်။”')
,(499,3,1,'ခရီးတစ်ဝက်။', NULL)
,(500,3,1,'နေ့တစ်ဝက်။','“တ္ၚဲဏအ် အဲဂွံမၚ်သဳ ကဝက်တ္ၚဲရ။” = “ယနေ့နေ့တစ်ဝက် ငါဥပုသ်စောင့်ရသည်။”')
,(501,3,1,'နှစ်ဝက်။', NULL)
,(502,3,1,'လမ်းလျှောက်ဟန်။','“ကဝါ်သၟတ်ဗြဴဂှ် ရံၚ်စခိုဟ်ကွေံကွေံရ။”= “ထိုသူငယ်မ၏ လမ်းလျှောက်ဟန်သည် အလွန်ကြည့်ကောင်းသည်။” || “တီဇမောဝ်ဍာ် ကဝါ်ကဇၞော်” = ရေကြောနှင့် ငါးကြီးအသွားအလာကို သိသည်။ ပင်လယ်ရေကြောင်းခရီး­ ကျွမ်းကျၚ်လိမ္မာသည်။')
,(502,3,4,'၁။ လှည့်လည်သယ်ဆောင်သည်။','ကဝါ်က္ဍိုၚ်ကျာ် = စေတီထီးတော်ကို သယ်ဆောင်၍ လှည့်လည်သည်။ ထီးတော်လှည့်သည်။ || ကဝါ်ထပိုဲ = ရှင်လောင်းလှည့်သည်။ || ကဝါ်ဇံၚ် = ပဒေသာပင်သယ်ဆောင်၍ မြို့ရွာလှည့်လည်သည်။ ပဒေသာပင်လှည့်သည်။')
,(502,3,4,'၂။ ခေါ်ဆောင်သည်။ လိုက်ပါပို့ဆောင်သည်။','“ညးကဝါ်ဏာကၟုဲဂှ် အာဂေတ်ဗဵုဝေၚ်ကွာန်ရ။” = “ဧည့်သည်အား ရွာကိုလှည့်ပတ်ကြည့်ရှုရန် (အတူတကွ) သူခေါ်ဆောင်သွားသည်။” || ‘ကွာ်’ (ကြိ) လည်းရှု။')
,(503,3,4,'မှိုၚ်သည်။ ကုပ်နေသည်။','“မူပဟွံအာဗဵုပေဲါသဘၚ်တုဲ ကဝုက်ဒၟံၚ်ပ္ဍဲသ္ၚိဂှ်ရော။” = “ဘာကြောင့်ပွဲမသွားကြည့်ဘဲ အိမ်တွင်ကုပ်နေသနည်း။”')
,(504,3,1,'၁။ အကွဲအစ။','ကဝေက်ပလၚ် = ပုလင်းကွဲအစအန။')
,(504,3,1,'၂။ သူတောင်းစားခွက်။','“မၚ်ဗၠာဲဒိုက်အာရ။ ဒးသပိုၚ်ယာတ်ခမၞက်တုဲ ရပ်ကဝေက် ဒးကြိုၚ်ကြၚ်အာတ်စ—။” (ဇ—၂၉၁။ အစွောံ။) = “ထိုလုလင်သည် ဆင်းရဲသွား၏။ အဝတ်နွမ်းကိုဝတ်၍ ခွက်လက်စွဲကာ လှည့်လည် တောင်းစားရ၏။”')
,(504,3,1,'၃။ အိုးခြမ်းကွဲ။','“(ခမဳဂှ်) ကတဵုဗဒှ်ဒေါသ ညံၚ်ၜဵုညးထောံစုတ် ပ္ဍဲကဝေက် ဂမ္တဴကီုမဒှ်။” (ဇ—၂၅၂။ အစွောံ။) = “ထိုရဟန်းသည် ပူသောအိုးခြမ်းကွဲ­ ထည့်လိုက်သော ဆားကဲ့သို့ အမျက်ဒေါသဖြစ်တတ်၏။”')
,(505,3,1,'အသုပ်။ လက်သုပ်။','ကဝေက်ကစ္စဳ = သင်္ဘောသီးလက်သုပ်။ (‘ပဝေက်’/‘ပွေက်’ သည်သာလျှင် မှန်ကန်သောစာလုံးပေါင်းဖြစ်သည်။ ‘ပေက်’ (ကြိ) မှ ဆက်နွှယ်ဆင်း သက်လာသော ဝေါဟာရဖြစ်သည်။)')
,(506,3,1,'ခြေပွတ်အိုးခြမ်း။ ခြေသုတ်။ (ပါဠိ—ပါဒကထလိက)', NULL)
,(507,3,4,'၁။ ကွေးသည်။','“ဇွဟ်စှ်ေတုဲ ဒးကဝံက်ဒၟံၚ်ရ။” = “အဖျားကျပြီး ကွေး၍နေရသည်။” || (ဦးခေါင်း၊ စပါးနှံစသည်) ငိုက်ကျသည်။ ညွတ်ကျသည်။')
,(508,3,4,'ခွေ၍နေသည်။ ကွေး၍နေသည်။', NULL)
,(509,3,4,'ကော့ကွေးသည်။', NULL)
,(510,3,1,'ပဒဲကော။ (ဟင်းခတ်အမွှေးအကြိုင်)', NULL)
,(511,3,4,'အဆီပြန်သည်။ အဆီဝင်းသည်။','“ပ္ဍဲဍာ်ဂှ် ကၠေၚ်ကဝေၚ်ဒၟံၚ်ရ။” = “ထိုရေထဲမှာ အဆီဝင်းနေသည်။” || “ခါအဲသကိုဟ်ထောံ ပ္ဍဲဍာ်ဂှ်လေဝ် ကၠေၚ်သွဟ်တံဝွံ ကဝေၚ်ဒၟံၚ် ညးညာတ်စုတ်ပၠန်ရ” ခမဳဂှ်ချပ်။ (ဇ—၄၁။ အစွောံ။) = “ဤထောပတ်တို့ကို အကယ်၍ရေထဲသို့ သွန်ပစ်လျှင်လည်း အဆီဝင်းသဖြင့် လူတို့မြင်ကုန်ပြန်ရာ၏” ဟုထိုရဟန်းတွေး၏။')
,(512,3,1,'ချစ်သူ။ ရည်းစား။', NULL)
,(513,3,1,'၁။ ညောင်းခြင်း။ အညောင်း။','ဒးကဝိုၚ် = အညောင်းမိသည်။ || ပၠးကဝိုၚ် = အညောင်းဆန့်သည်။ အညောင်းအညာဖြေသည်။ ‘ကွိုၚ်’ (ကြိ) လည်းရှု။')
,(513,3,1,'၂။ အကွေ့အကောက်။','ကဝိုၚ်ၜဳ = မြစ်ကွေ့။')
,(514,3,1,'ညောင်းညာခြင်း။ အညောင်းအညာ။','‘ကွိုၚ်ကွုဲ’ (ကြိ) လည်းရှု။')
,(515,3,4,'အကြွေးဝယ်သည်။','“အပေါတ်ဏအ် အဲကဝုတ်လဝ်ဂွံဟာ။”= “ဤပစ္စည်းကို ကျွန်တော်အကြွေးယူလို့ရမလား။” || “ပိုဲကေတ်စဖျုန်ဂၠဴတၠခွါကဝုတ်ဂှ်—။” (ဇ—၁၉၉။ အစွောံ။) = “ရွာသူကြီး၏နွားကို ငါတို့အကြွေးဝယ်စားသည်မှာ—။”')
,(515,3,4,'အကြွေးဝယ်သည်။','‘တွုတ်’/‘ဗွဲတွုတ်’ လည်းရှု။')
,(516,3,4,'နပန်းးလုံးသည်။ နပန်းသတ်သည်။','“သၟတ်တြုံၜါဂှ် တၞဟ်နစမ်ဒြဟတ် ကဝိုတ်ညး သ္ကအ်ရ။” = “ထိုသူငယ်နှစ်ယောက်တို့သည် အားစမ်းရန်အတွက် နပမ်းလုံးကြသည်။”')
,(516,3,4,'နပန်းးလုံးသည်။ နပန်းသတ်သည်။','“ဗောဓိသတ် (ကၞုဲ) ဍိုက်ပေၚ်တဴအစောံဒြဟတ်ဇၟူရောၚ်။ — ဗန်ကဝိုတ်လေငတ်သၟိၚ်ကၞုဲဂှ်ပၠန်—။” (ဇ— ၅၈။ အစွောံ။) = “ဘုရားလောင်းမျောက်သည် ဆင်ပြောင်အားအစွမ်းနှင့် ပြည့်စုံ၏။ ဘုရားလောင်းသည် ထိုမျောက်မင်းအား နပန်းလုံးဖက်ညှစ်၏။” || “(ပြောဟိတ်ဂှ်) ရပ်စပ်ကဝိုတ်ကဝးသာ် ဇၟာ်အဲတုဲ ဗပေၚ်ဂၞပ်စိုတ်ဇကုတုဲ အာကၠေံရ” ဂၞကျာ်ဂးကဵုသၟိၚ်ရ။ (ဇ—၁၂ဝ။ အစွောံ။) = “ပုရောဟိတ်သည် အကျွန်ုပ်အား ချုပ်ကိုင်သတ်ပုတ်ကုတ်ခြစ်၍ မိမိ၏စိတ်အလိုကို ပြည့်စေပြီးလျှင် ထွက်သွား၏” ဟုမိဖုရားသည် မင်းအားပြော၏။')
,(518,3,1,'၁။ ကရဝေး။ (ပါဠိ—ကောသဖလ','တက္ကောလ)')
,(518,3,1,'၂။ အစုံ။ အတွဲ။ နှစ်ဆောင်ပြိုင်။', NULL)
,(518,3,4,'အစုံဖြစ်သည်။ အတွဲဖြစ်သည်။ နှစ်ဆောင်ပြိုင်ဖြစ်သည်။','မကဝါန်ၜါၜါ = အစုံလိုက်ဖြစ်သော။ အတွဲလိုက်ဖြစ်သော။ နှစ်ခု,နှစ်ခုဖြစ်သော။/ တၞံအံၚ်ရေၚ်ကဝါန် = နှစ်ပင်စုံတွဲဖြစ်သော အင်ကြင်းပင်စု။')
,(520,3,1,'ဆေးဥတလုံး။ (ဆေးဖက်ဝင်)', NULL)
,(521,3,1,'နွားလျှာပင်။ မှန်သင်း။ (ဆေးဖက်ဝင်)', NULL)
,(522,3,4,'ကွေးသည်။ ကောက်သည်။','“တြုံကုန်ဝွံ သတိက်ကဝေန်ဒၟံၚ်ရ။” (ဇ—၂၃၂။ အစွောံ။) = “ထိုငကုန်းသည် ကွေး၍အိပ်နေ၏။” || “ကၠဵုဂှ် ကၠုၚ်ဇရေၚ်ကမၠိုၚ်ဂှ်ပၠန်တုဲ သာမဏဳ ကၠဟ်ဒးတုဲ ကဝေန်ဒၟံၚ်ရ။” (ဇ—၂၇၁။ အစွောံ။) = “ထိုခွေးသည် ရေတွင်းနားသို့ လာပြန် သည်ရှိသော် သာမဏေတို့က ခဲ,အုတ်တို့ဖြင့် ပစ်ခတ်ကြရာ ထိမှန်၍ ကွေး၍နေ၏။”')
,(524,3,4,'ဆံပင်ကောက်သည်။ ကောက်သောဆံပင်ရှိသည်။', NULL)
,(525,3,4,'ဆံပင်ကောက်သည်။ ဆံပင်ကောက်အောင်လုပ်သည်။', NULL)
,(526,3,4,'ကောက်ကွေးသည်။ ခွေ၍နေသည်။ ဖွဲ့ခွေသည်။', NULL)
,(527,3,4,'၁။ ကောက်ကွေးသည်။', NULL)
,(527,3,4,'၂။ မှိုင်ကုပ်၍နေသည်။', NULL)
,(528,3,4,'ဆံပင်ကောက်သည်။ ဆံပင်ကောက်အောင်လုပ်သည်။ (အလှပြင်ဆိုင်တွင်)', NULL)
,(529,3,1,'ကြက်ဟင်းခါးသီး။', NULL)
,(530,3,4,'အကွင်းဖြစ်အောင် လှီးဖြတ်သည်။', NULL)
,(531,3,1,'အကွင်းလိုက်လှီးထားသောအရာ။','ကဝေဝ်ဂအဳ = အကွင်းလိုက်လှီးထားသောသခွားသီး။ သခွားသီးကွင်း။')
,(531,3,1,'အကွင်းလိုက်လှီးထားသောအရာ။','ကဝေဝ်က = အကွင်းလိုက်လှီးထားသောငါး။')
,(532,3,1,'ပဲလင်းမြွေသီး။', NULL)
,(533,3,4,'အောက်သို့တွဲကျသည်၊ ညွတ်ကျသည်။ ကိုင်းကျသည်။','“တၞံကြုက်ဂှ်သတ်ဂၠိုၚ် ကၞာၚ်ကဝေအ်အာရ။” = “ထိုသရက်ပင်သည် အသီးများ၍ အကိုင်းအောက်သို့ ညွတ်ကျသွား သည်။”')
,(534,3,1,'ရစ်တိုင်။ ရစ်လုံး။ ချည်ရစ်ကိရိယာ။', NULL)
,(535,3,1,'အကင်း။ အသီးကင်း။','ကသိပၞဟ် = ပိနနဲသီးအကင်း။')
,(536,3,1,'လှုပ်ခြင်း။ လှုပ်ရှားခြင်း။', NULL)
,(536,3,4,'လှုပ်စေသည်။ လှုပ်ခါစေသည်။ တုန်လှုပ်စေသည်။','ကသဳဇိုၚ်တဲ = ခြေလက်လှုပ်ရှားသည်။ || ကသဳကတောဝ် = နားရွက်ကိုလှုပ်သည်။ || “ခ္ဍာ်ကသဳကၞာၚ်တုဲ သတ်ကြေၚ်လမုဟ်တံဂှ် ဒတုမ်ပြဟ်စှ်ေတုဲ ကၠဵုဂြိုပ်ဂှ် လပှ်စရ။” (ဇ—၂၉၄။ အစွောံ။) = “ကျီးသည် သပြေခက်ကိုလှုပ်၍ မှည့်သောသပြေသီးတို့ကို ကြွေကျစေ၍ မြေခွေးသည် ကောက်စား၏။” || “ယွံခမဳ၊ ၜိုန်တၟအ်သိနနရာတ် ကျာမပိုက်ကသဳမာန်ဏီဂှ် သၠဆုလၟုဟ်အပြောံဂှ် မူဟိုတ်ဍေံဟွံပိုက်ကသဳသၞုံရော။” (ဇ—၄၃၃။ အစွောံ။) = “ရဟန်း၊ မြင်းမိုရ်တောင်ကိုပင် တိုက်ခတ်လှုပ်ခါစေနိုင်သောလေသည် အချည်းအနှီးသော သစ်ရွက်ရော်မျှကို အဘယ်မူ၍ မတုန်လှုပ်စေဘဲ ရှိပါငြားအံ့နည်း။” || ‘မသက္ကုကသဳ’ လည်းရှု။')
,(537,3,1,'ကာသိကတိုင်း။', NULL)
,(538,3,4,'လှုပ်ရှားသည်။ လှုပ်ခါသည်။ လှုပ်ခတ်သည်။','“ခဍာ်ဂှ် ကသဳဂ ရိုက်ကၞာၚ်ကြေၚ်ဂှ်တုဲ သတ်ကြေၚ်လၟုဟ်ဂမၠိုၚ် ပြဟ်စှ်ေရ။” = “ထိုကျီးသည် သပြေကိုင်းကို လှုပ်ခါသည်ရှိသော် သပြေသီးမှည့်များ ကြွေကျလာ၏။”')
,(539,3,4,'ဟိုဘက်ဤဘက်လှုပ်ရှားသည်။ ဘယ်ချည်ညာချည်လှုပ်သည်။','ကသဳဂရာၚ်တၚ်ၜံၚ် = ဒူးလှုပ်သည်။ ဒူးနန့်သည်။')
,(540,3,4,'စိတ်တုန်လှုပ်သည်။ —စေသည်။','“ဣသိလောမကဿပတုန် ဓဝ်ကိလေသတ ဏှာဂှ် ကသဳစိုတ်တုဲ သၟိက်ဂွံကောန်ဗြဴဨကရာတ် တၠစရာဲရုပ်ဂှ်ရ။” (ဇ—၄၃၃။ အစွောံ။) = “လောမကဿပရသေ့သည် ကိလေသာတဏှာတရားက စိတ်ကိုတုန်လှုပ်စေသဖြင့် အလှပိုၚ်ရှင် ဘုရင့်သမီးတော်အား လိုချင်တောင့်တလေ၏။” || “ယွံသၟိၚ်မပြဲ၊ ဂၞကျာ်ဘိမ္မာယသောဓရာဂှ် ပ္ဍဲဘဝအတိက် ဘဝကြဴတေံဂှ် ကာလဂၞကျာ်ဒှ်ပ္ဍဲဘဝတိရစ္ဆာန်တေံကီုလေဝ် ဂၞကျာ်မၞုံစိုတ်ဇြဟာန်ပ္ဍဲအဲဂှ်တုဲ ညးမဟီုပ္တေဟ်ကဵုစိုတ်ဟွံမာန် ညးမကသဳစိုတ်ဂၞကျာ်ဟွံမာန်ဂှ် မဂပ်ဂဝ်ပအသဝ်ရ” ကျာ်ဂး။ (ဇ—၄၈၅။ အစွောံ။) = “မြတ်သောမင်းကြီး၊ ဘိမ္မာယသောဓယာမိဖုယားသည် အတိတ်ဘဝ တိရစ္ဆာန်ဖြစ်သောအခါ­လည်း မိဖုယားသည် ငါ­ချစ်ခြင်းစိတ်ရှိုသည်ဖြစ်၍ သူတစ်ပါးတို့ အယုံမသွင်းနိုင်ခြင်း၊ စိတ်ကိုမတုန်လှုပ်စေနိုင်ခြင်းသည် အံ့ဖွယ်ဖြစ်၏” မြတ်စွာဘုရားမိန့်တော်မူ၏။')
,(541,3,1,'ငလျင်။ မြေငလျင်။','“ကသဳတိက္တဵုဒှ် ဓါတ်သော်လ္ဂုၚ်ပြဵုအာ။” (ရာဇာဝံသ သံခိပ်။ အစွောံ။) = “မြေငလျင်လှုပ်ခတ်၍ ရွှေတိဂုံဆံတော်ရှင် အက်ကွဲပြိုသွားသည်။”')
,(542,3,4,'စည်းစိမ်တော်ထိုၚ်ခင်းကို ရွေ့စေသည်။ ကြွမြန်းတော်မူသည်။ (ဘုရင်စသူတို့ ထိုင်နေရာမှ ထသွားရာတွင်၄င်း၊ နန်းအိမ်တွင်စံမြန်းနေရာမှ ခရီးထွက်ခွာရာတွင် ၄င်းမွန်ဘာသာတွင်သုံးသော ထူးခြားသောအသုံးအနှုန်းဖြစ်သည်။)','“ခါစိုပ်အခိၚ်နူဂယး တၠညး ဖရၚ်မၚ်ဂံၚ် ကသဳသၞာစှ်ေဂၠုၚ်ဖ္ဍိုက် ကေုာံသေနာပတိသၟိၚ်ဗိုလ်နာဲဒပ်။” (အကြီုရာဇာဓိရာဇ်) = “နံနက်အချိန်ရောက်သောအခါ ဘုရင်မင်းခေါင်သည် သေနာပတိတပ်မှူးဗိုလ်မှူးများနှင့်အတူ စီးတော်လှေသို့ ကြွမြန်းသက်ဆင်းတော်မူသည်။” || “သၟဝ်ဂၠးဂတာဇိုၚ်ထဝ် ကသဳသၞာတသိုက် က္ည ပ္တန်သမာဓိ ဆဍုၚ်ဒလညိကၠာရ” အမာတ်ဒိန်ပ္တီတၠညးရာဇာဓိရာဇ်ရ။ (ရာဇာဝံသကထာ)= “ရွှေဖဝါးတော်အောက် တင်လျှောက်ပါသည်။ အရှင်ဘုရား ဒလမြို့တွင် ခေတ္တကြွမြန်းနားနေတော်မူ ပါဘုရား” ဟုအမတ်ဒိန်မှ ဘုရင်ရာဇာဓိရာဇ်အား တင်လျှောက်၏။')
,(543,3,4,'နှလုံးသား­ တုန်လှုပ်သွားသည်။ နှလုံးသားကို တုန်လှုပ်သွားစေသည်။','“ယွံညးမသၟဟ်ကဵုပိုဲ၊ ကောန်မဟီုဂလာန်မ္ဂးဣတဂှ် ဍေံမကသဳအာ ပ္ဍဲဖျုန်ဂြိုဟ်အဲရောၚ်။ ဂလာန်မ္ဂးဣတဂှ် မတုပ်ကဵုဖျုန်ဂြိုဟ်ရ” လၟဂး။ (ဇ—၃၁၅။ အစွောံ။) = “အဆွေ၊ အဘဟူ၍ဆိုလာ သောသားသည် အဘ၏နှလုံးသား­ တုန်လှုပ်သွားစေ၏။ အဘဟူသောစကားသည် နှလုံးသားနှင့်တူ၏။”')
,(544,3,1,'လှော်တက်။', NULL)
,(545,3,1,'ရေးဆွဲခြင်း။ ရေးဆွဲထားသောအရာ။','အ္စာကသူ = ပန်းချီဆရာ။ || ဒေဝတဴကသူကၞေၚ် = ဖူးစာရေးနတ်။ || ‘ချူ’ (ကြိ) လည်းရှု။')
,(546,3,1,'ဆန်းကြယ်စွာ ရေးဆွဲထားသော ပန်းချီကား။', NULL)
,(547,3,1,'ကျိန်ဆဲခြင်း။ ကျိန်စာ။','‘ချဴ’ (ကြိ) လည်းရှု။')
,(548,3,1,'ဆိုင်းကြိုး။','ဇုက်ကသး = ဆိုင်းကြိုး။ (စွန်ဆိုင်းကြိုး)')
,(549,3,4,'ပူလောင်ခြင်းကို ခံစားရသည်။','“မၞိဟ်ယဲဂှ် ကသက်ကသာဒၟံၚ်ရ။” = “လူနာသည် ပူလောင်ခံစားနေရသည်၊ (ဝါ) မခံချည့်မခံသာ ဝေဒနာခံစားနေရသည်။”')
,(550,3,1,'၁။ သားဖွားရာတွင်ပါလာသော ချက်ကြိုး။ အချင်း။','ကသုက်ကောန်ၚာ် = ကလေးချက်တိုင်။ ကလေးအချင်း။')
,(550,3,1,'၂။ စာချုပ်ချုပ်ဆိုခြင်း။','လိက်ကသုက် = စာချုပ်။')
,(550,3,1,'၃။ (အုန်းသီးစသည်) ဆံခြည်ထွေး။','ကသုက်သတ်ဗြဴ = အုန်းသီးဆံခြည်ထွေး။')
,(551,3,1,'အမွေး။','ကသော်စာၚ် = ကြက်မွေး။')
,(552,3,1,'မွေးညှင်း။', NULL)
,(553,3,1,'အရေပြားတွင်ပေါက်သော ပွေးယားနာ။', NULL)
,(554,3,1,'ပျက်ရယ်ပြုခြင်း။ လှောင်ပြောင်ခြင်း။','သ္ပကသံက်ကသာ = ပျက်ရယ်ပြုသည်၊ လှောင်ပြောင်သည်။ || ‘ချံက်ချာ’ (ကြိ) လည်းရှု။')
,(555,3,1,'ကလေးငယ်တွင် ပေါက်တတ်သောပွေး။ နို့ပွေး။', NULL)
,(556,3,1,'ကျောက်အပေါ်တက်နေသော ချေးညှော်။ ကျောက်အပွေး။', NULL)
,(557,3,4,'ဖားလျားကျသည်။', NULL)
,(558,3,1,'(တရားခံချုပ်ရန်) ထိပ်တုံး။ လက်ထိပ်။', NULL)
,(558,3,4,'ခြေထိပ်လက်ထိပ်ခတ်သည်။','ကသိၚ်ဇိုၚ် = ခြေထိပ်တုံးခတ်သည်။ || ကသိၚ်တဲ = လက်ထိပ်ခတ်သည်။')
,(559,3,1,'နှောၚ်ဖွဲ့ခြင်း။ ချုပ်နှောၚ်ခြင်း။ အနှောင်အဖွဲ့။', NULL)
,(560,3,1,'ရေခတ္တာပင်။ ပင်လယ်ကြက်သွန်။', NULL)
,(561,3,1,'အတွင်း။ အပေါက်။','ကသိုၚ်ဇြုံ = မြွေတွင်း။ || ကသိုၚ်ကၞိ = ကြွက်တွင်း။')
,(562,3,1,'နှာခေါင်းပေါက်။', NULL)
,(563,3,4,'အတင်းပြုလုပ်သည်။ အဓမ္မပြုလုပ်သည်။ လုယက်သည်။','‘တသိုၚ်’ ရှု။')
,(564,3,4,'တွန်းရွှေ့သည်။ လျှောသည်။','ကသေတ်စှ်ေ = လျှောဆင်းသည်။ တွန်းရွှေ့ဆင်းသည်။ || ကသေတ်တိုန် = တွန်းရွှေ့တက်သည်။ || ကသေတ်အာ = တွန်းရွှေ့သွားသည်။ || ကသေတ်အာကဵုတကေတ် = ဖင်နှင့်တွန်းရွှေ့သွားသည်။')
,(565,3,1,'သနပ်ပင်၊ သနပ်ကြီးပင်။ (ဆေးလိက်ဖက်)','သၠကသန် = သနပ်ဖက်၊ သနပ်ရွက်။')
,(566,3,1,'ရေယုန်နာ။ (အရေပြားပေါ် ပေါက်တတ်သောအနာစက်)', NULL)
,(567,3,4,'ညည်းတွားသည်။ ဝမ်းနည်းပူဆွေးသည်။ ငိုကြွေးမြည် တမ်းသည်။', NULL)
,(568,3,11,'(န) ကသိုဏ်း။ (ပါဠိ—ကသိဏ)','ကသိုန်စှ် = ကသိုဏ်းဆယ်ပါး။ || ပၟဝ်ကသိုန် = ကသိုဏ်းရှုသည်။')
,(569,3,1,'ကြက်သွန်။','ကသိုန်ဗ္တာၚ် = ကြက်သွန်ဖြူ။ || ကသိုန်ဗ္ကေတ် = ကြက်သွန်နီ။')
,(570,3,1,'အကြံ။ အတွေး။','‘ချပ်’ (ကြိ) လည်းရှု။')
,(571,3,1,'အကြံအစည်။ အတွေးအခေါ်။','“အတိုၚ်ကသပ်ဂၞန် အစဳရေၚ်သီုဖအိုတ်ဂှ် ဟီုကဵု ကောန်ဗြဴသၟိၚ် သီုဖအိုတ်ရ။” (ဇ—၁၂၆။ အစွောံ။) = “အလုံးစုံသောအကြံအစည် အစီအမံတို့ကို မင်းသမီးအားပြောပြ၏။”')
,(572,3,1,'စိတ်အကြံအစည်။ စိတ်ခံစားမှု။', NULL)
,(573,3,4,'အကြံအောင်သည်။ အကြံအစည်အောင်မြင်သည်။ အပြီးသို့ရောက်သည်။','“(ဗြဴအယုတ်စၞာဲဂှ်) ဍေံဒရိုဟ်ဖျေံဏာ(ဗောဓိသတ်) ပ္ဍဲလပါ်တၟံတေံရ၊ ဗောဓိသတ်ဒတုံစှ်ေတုဲ ‘ကသပ်အဲစိုပ်ဒတုဲရ’ ဍေံဂးတုဲ ဍေံမိပ်စိုတ် အိုဟ်တၟိုဟ်စိုတ်တုဲ ဍေံစှ်ေအာကဵုတြုံပိုတ်တေံရ။”(၅၅ဝ။ ဇ—၁၉၃။ ပ—၅၄၃။ အစွောံ။) = “ထိုစဉ်းလဲသောမိန်းမယုတ်သည် ဘုရားလောင်းအား တောင်ကမ်းပါးပြတ်သို့ တွန်းချလိုက်၏။ ဘုရားလောင်းကျသွားသည်ရှိသော် ‘ငါ့အကြံအောင်ပြီ’ ဟု ဝမ်းမြောက်ဝမ်းသာလျက် ငပြတ်ရှိရာသို့ ဆင်းသွား၏။”')
,(574,3,4,'အကြံကြီးသည်။ ကြံကြီးစည်ရာလုပ်သည်။', NULL)
,(575,3,1,'အကြံဉာဏ်။', NULL)
,(576,3,4,'အကြံကုန်သည်။ ဘာလုပ်ရမှန်းမသိဖြစ်သည်။', NULL)
,(577,3,12,'(န) ဒၚ်္ဂါး။ အသပြာ။','“ထိုၚ်ကသာပ်ကဵုထိုၚ်ကောန်တြေဟ်ဂှ် လဝ်မွဲစွံရ။” (ဇ—၂၈၈။ အစွောံ။) = “အသပြာထုပ်နှင့် ကျောက်စရစ်ထုပ်ကို အတူထား၏။”')
,(578,3,1,'ငွေကြေးအသပြာ။','“(ဂလာကၠေဝ်မွဲ) ညာတ်သရာဲဍုၚ်မွဲပတၠရုပ် ကဵုကသာပ်ကနှံ ဗွဲမဂၠိုၚ်တုဲ ဂိုၚ်လဝ်ပသမ္ဘာရ။” (သၠပတ်ဒ္ၚောဝ်သၜောံ) = “တစ်ယောက်သောကုလားသည် ရုပ်အဆင်းလှသော ပြည့်တန်ဆာမတစ်ယောက်ကိုမြင်၍ များစွာသောငွေကြေးအသပြာပေး၍ မယားပြုထား၏။”')
,(579,3,4,'ငိုက်ကျသည်။ ကိုင်းကျသည်။','“တၞံသြောအ်ကသိုပ်အိုတ်ရ။” = “စပါးပင်များသည် ကိုင်းကျကုန်ပြီ။”')
,(579,3,4,'ငိုက်ကျသည်။ ကိုင်းကျသည်။','ကသိုပ်စှ်ေ = ငိုက်ကျသည်။ ငိုက်စိုက်ကျသည်။')
,(580,3,1,'ကြို့ပင်။','‘ဆုဗြီုဗြံ’ နှင့်အတူတူ။')
,(581,3,1,'မိုးရာသီ။', NULL)
,(582,3,1,'မိုးလယ်ခေါင်။', NULL)
,(583,3,1,'၁။ အမျှင်စ။ အမြိတ်။ အဆာ။ ပန်းပွါး။','ကသာဲယာတ် = စောၚ်အမြိတ်။ ‘ဒသာဲ’ ရှု။ || ကသာဲကၟဟ် = တံမြက်စီးအမျှင်စ။ || ကသာဲဇုက်= ကြိုးအမျှင်စ။')
,(583,3,1,'၂။ ကသာပင်။ (ဆေးဖက်ဝင်)', NULL)
,(584,3,3,'(သားငါးစသည်) နုပ်နုပ်စဉ်းထားသော။ အတုံးငယ်တုံးထားသော။','“ဖျုန်ကက လောအ်ဇၞော် အဲသစဟာ။ ဟွံသေၚ်သာ်ဂှ် ဖျုန်မကသာဲလကောတ်ဂှ် အဲသစဟာ” ခဍာ်ချပ်။ (ဇ—၄၂။ အစွောံ။) = “အမဲတုံးကြီးကိုတည်း စားရအံ့လော။ ထိုသို့မဟုတ်မူ အမဲတုံးငယ်ကို တည်းစားရအံ့လော” ဟုကျီးကြံ၏။')
,(585,3,4,'တီးတိုးပြောသည်။ တိုးတိုးပြောသည်။ နှစ်ကိုယ်ကြားပြောသည်။','“သာ်ဝွံအ္စာစိၚ်ကသေဲဟီုကဵုစိၚ်ဗ္တာၚ်ရ။” (ဇ—၁၂၂။ အစွောံ။) = “ဆင်ဦးစီးသည် ဆင်ဖြူတော်ကို ဤသို့တိုးတိုးပြော၏။” || “(ဒေါၚ်ဗြဴဂှ်) ကသေဲဟီုကဵုကောန်ဗြဴသၟိၚ်ရ။” (ဇ—၁၂၆။ အစွောံ။) = “ထိုနတ်ကတော်မသည် မင်းသမီးအား နှစ်ကိုယ်ကြားတီးတိုးပြော၏။”')
,(586,3,1,'ဝစ္ဆံ။ ဝတ်မှုန်။','ကသဝ်ပ္ကဴ = ပန်းဝတ်မှုန်။')
,(587,3,4,'ညည်းညူသည်။ ညည်းတွားသည်။','“ခမဳမွဲကသဝ်ဒၟံၚ်သၟိက်ဂွံရာံ—။” (ဇ—၈၅။ အစွောံ။) = “ရဟန်းတစ်ပါးသည် လူထွက်လို၍ ညည်းညူနေသည်။” || ‘ဂသဝ်’ ဟုလည်း တွေ့ရသည်။')
,(588,3,4,'အခင်းအပြင်နှင့် ပွတ်ထိစေလျက် လျှောက်သည်။ ရှပ်တိုက်သွားသည်။', NULL)
,(589,3,4,'ဆင်ခြေလျှောသည်။ လျှောကျသည်။','ဋ္ဌာန်တသောဝ်ဝါတ် = ဆင်ခြေလျှောဖြစ်၍ တက်ဆင်းရန်ခက်သောနေရာ။')
,(590,3,1,'ချုံပုတ်။ ပုပျပ်သောအပင်။ ပင်ပုပင်ငယ်။','ကသဵုဂြိုပ် = ချုံပုတ်။ ချုံပင်စု။ || ကသဵုပ္ကဴ ဇဗ = ကုလားဇလပ်ပန်းချုံ။ || ကသဵုတၞံဇြဲ = ပေါက်ခါစညောင်ပင်ငယ်။')
,(591,3,4,'ထိုၚ်၍ ခြေထောက်ကိုဆန့်တန်းသည်။ ခြေဆင်းသည်။', NULL)
,(592,3,1,'ထွေးပြီးသောတံတွေး။','“ညံၚ်ရဴဍာ်ကသှ် ချဟ် တုဲညးဟွံကၠာန်ရ။” = “တံတွေးကဲ့သို့ ထွေးပြီးနောက် သူပြန်မလျက်တော့ပါ။” || ‘ဂစှ်/ဍာ်ဂစှ်’ နှင့်အတူတူ။ || ‘ချဟ်’ (ကြိ) လည်းရှု။')
,(593,3,4,'မှုတ်ထုတ်သည်။','ကသိုဟ်သၟောဝ် = နှပ်ညှစ်သည်။ “ဇြုံဇာတ်ဂှ် ကသိုဟ်ဒၟံၚ်ရ။” = “ထိုမြွေဟောက်သည် တရှဲရှဲနှင့်မှုတ်နေသည်၊ (ဝါ) အော်မြည်နေသည်။”')
,(594,3,4,'တိုင်ပင်ဆွေးနွေးသည်။ ညှိနှိုင်းတိုင်ပင်သည်။ (?)', NULL)
,(595,3,1,'၁။ သော့။', NULL)
,(595,3,1,'၂။ ဗူးစို့။ ဗူးအဖုံး။', NULL)
,(595,3,1,'၃။ ခန္ဓာကိုယ်တွင်းရှိအဆုတ်။', NULL)
,(596,3,4,'အဖော်ညှိသည်။', NULL)
,(597,3,4,'အဖော်ညှိသည်။ သွေးဆောင်ဖျောင်းဖျသည်။', NULL)
,(598,3,1,'သက်ရင်းပင်။ (ဆေးဖက်ဝင်)', NULL)
,(599,3,4,'၁။ ငြိမ်သက်သည်။ မှိန်းသည်။ မှေးခံသည်။','“ညးစပုၚ်တုဲ ကဟဳဒၟံၚ်ရ။” = “သူ ထမင်းစားပြီးနောက် မှိန်းနေသည်။” || “ဟိုတ်ဒုဟ်ဍေံနွံတုဲ ဍေံဟွံဟီုမွဲသာ် ဍေံကဟဳဒၟံၚ်ရောၚ်။” = “သူ့အပြစ်ရှိသောကြောင့် ဘာတစ်ခုမျှ သူမပြောဆိုဘဲ မှေးခံနေခြင်းဖြစ်သည်။”')
,(599,3,4,'၂။ အနည်းငယ်တူးလောၚ်သည်။','“ပုၚ်ကဟဳအာရ။” = “ထမင်းတူးလောင်သွားသည်။”')
,(600,3,4,'စိတ်ဆိုးသည်။ ဒေါမွှန်သည်။','“ဟိုတ်အဲဟွံရီုဗၚ်ညးတုဲ ညးကဟောန်ဒၟံၚ်ကဵုအဲ ရ။” = “သူ့ကို ကျွန်တော်မကူညီသဖြင့် ကျွန်တော့်ကို သူဒေါမွှန်နေသည်။”')
,(601,3,4,'စိုးရိမ်ပူပန်သည်။ နောင်တရသည်။','‘သ္ၚောံ’ ရှု။')
,(602,3,4,'စိတ်ဆိုးသည်။ ဒေါမွှန်သည်။', NULL)
,(603,3,4,'(ပါးစပ်ဖြင့်) စုပ်သည်။','ကၜေတ်ၜဴ = ကြံစုပ်သည်။')
,(604,3,4,'၁။ အစဉ်အဆက်မှ ဖြစ်လာသည်။','“ဇြုံလ္ပကဵုချိုတ်အဵု လေံလ္ပကဵုကဝ်၊ —၊ ဂ လာန်ဒတန်ကဝ် ဟီုကၠုၚ်က္ၜဝ်ရောၚ်။” (သၠပတ်ပေါရဏာံပေါရဒံါ, အစွောံ) “မြွေလည်းမသေစေ နှင့်၊ တုတ်လည်းမကျိုးစေနှင့် ဟူသောစကားသည် ကမ္ဘာတည််ကတည်းက အစဉ်အဆက် ပြော ဆိုလာခဲ့သောစကားတည်း။”')
,(604,3,4,'၂။ နလန်ထသည်။ အဖျားပျောက်စ နလန်ထသည်။', NULL)
,(605,3,4,'ချောင်းဟန့်သည်။','ခ္ဍက်ကဟေမ် = ‘အဟင်းအဟင်း’ ဟု ချောင်းဟန့်သည်။')
,(606,3,4,'ပြုံးသည်။','“ဒဒှ်ဗမၞးမဟီုဆောတ်အာဂှ် သၟိၚ်တီတုဲ သၟိၚ်ကအီတုဲ—။” (ဇ—၂၁၁။ အစွောံ။) = “မင်းသည် ပုဏ္ဏားချွတ်ယွင်း၍ ဆိုမိသည်ကိုသိ၍ ပြုံး၏။” || “ကောန်ဗြဴအဲမွဲဂှ် ဍေံ ဂြိုၚ်ကအီဒှ်လောန်။” (ဇ—၂၁၇။ အစွောံ။) = “အကျွန်ုပ်­ ပြုံးရယ်တတ်လွန်းသော (ရယ်ရွှၚ် တတ်လွန်းသော) သမီးတစ်ယောက်ရှိ၏။” || ‘အီ’ ဟုအပြောတွင်သုံးသည်။')
,(606,3,4,'ပြုံးသည်။','‘ဂအီ’ လည်းရှု။')
;